#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Raspberry Pi Zero 2W FPV tracker — оптимизированная отладочная сборка.

Архитектура управления:

 - Поток MSP override в fc_io_loop никогда не прерывается, пока есть свежие
   RC-данные. Это лечит зависание тротла при выключении AUX, на которое нарвались
   ранее: Betaflight ожидает непрерывный поток MSP override-кадров.

 - Per-axis OVERRIDE_* флаги. Все False по умолчанию = чистый passthrough,
   AUX вообще ничего не меняет на FC. Включаешь по одной оси при отладке.
   В норме (после проверки осей) выставляешь OVERRIDE_ROLL/PITCH/YAW = True,
   OVERRIDE_THROTTLE опционально.

 - AIM_OFFSET_Y действует только на pitch (вертикальная прицельная точка),
   на расчёт газа НЕ применяется. Иначе постоянный фантомный dy = +10
   уносил бы I-компонент газа к нулю.

 - Жёсткие ограничители дефлекции (MAX_*_DEFLECT) предохраняют от
   срабатывания runaway_takeoff_prevention в BF при тестах без аэродинамики.

Трекинг:

 - Захват ровно в позиции прицела (ACQ_LOCK_AT_CROSSHAIR_EXACTLY) — размер берётся
   из связной компоненты под прицелом, а центр прибит к (CENTER_X, CENTER_Y).

 - Lucas-Kanade flow + template-matching с distance penalty.
   Веса 0.78 flow + 0.22 match — flow устойчивее к освещению и переходным
   фоновым артефактам, match даёт абсолютный якорь к шаблону.

 - Субпиксельная параболическая интерполяция пика matchTemplate.
   Точность позиции ~0.1 px вместо ±0.5 px пиксельной квантовки матчера.

 - Медленная адаптация шаблона (TEMPLATE_UPDATE_ALPHA = 0.010) — постепенно
   подбирает текущий вид цели на сближении, не давая фону «утянуть» якорь.

PID:

 - Roll/Pitch — P+D+I через _pid_axis_step, conditional anti-windup:
   I-компонент не накапливается, если выход уже саттурирован в том же знаке.

 - Yaw — отдельная ветка из-за фильтра filtered_dx_yaw и yaw_weight
   (ослабление при больших adx), но та же логика anti-windup.

 - Компенсация тангажа от MSP_ATTITUDE. fc_pitch_deg сглаживается фильтром
   и сдвигает прицельную точку так, чтобы стационарный наклонный полёт
   к цели не вызывал лишних pitch-корректировок.

 - Все накопители сбрасываются при переходе non-controllable → controllable
   (TRACKED → HOLD/LOST/AUX_OFF → TRACKED), windup между сессиями не переносится.
"""

from picamera2 import Picamera2, Preview, MappedArray
from libcamera import Transform
import cv2
import numpy as np
import serial
import struct
import time
import threading
import os
import collections
import math
import signal
import subprocess
import hashlib

cv2.setNumThreads(1)

# =========================================================
# 1. UI / КАРТИНКА
# =========================================================
CAMERA_ROTATE_180 = False

MAIN_W, MAIN_H = 640, 480

# --- РАЗРЕШЕНИЕ ТРЕКИНГА ---
# Трекинг исторически шёл по уменьшенной вдвое картинке 320x240, то есть
# половина углового разрешения выбрасывалась. Считается это так: 41.4 град
# вертикального обзора на 240 строк = 0.17 град/пиксель. Цель 2 м на 300 м
# занимает 2.2 пикселя — ни шаблона построить, ни углов для потока найти.
# Порог захвата (5 px) достигается только со 133 м, шаблон (14 px) — с 47 м.
#
# При 640x480 угловое разрешение вдвое выше, и те же пороги достигаются с
# вдвое большей дальности: захват ~266 м, шаблон ~95 м.
#
# Зум СЕНСОРА для этого не годится: камера одна, и пилот летит по ней же —
# сужать обзор значит ослеплять пилота. Здесь обзор не меняется, растёт
# только детализация, ровно как в лупе в углу экрана.
#
# ЧЕМ ПЛАТИМ: процессором. Zero 2W упирается именно в него, а шаблон и окно
# поиска растут в площади вчетверо. Поэтому переключатель, а не насовсем —
# на стенде видно по FPS в логе, тянет аппарат или нет.
HIRES_TRACKING = False
TRACK_SCALE = 2 if HIRES_TRACKING else 1
LORES_W, LORES_H = 320 * TRACK_SCALE, 240 * TRACK_SCALE
# Разрешение, которое запрашивается у камеры. Обычно совпадает с рабочим; при
# съёмке образцов в двойном разрешении оно вдвое больше, а кадр уменьшается
# перед обработкой.
CAM_W, CAM_H = LORES_W, LORES_H   # уточняется ниже, после RECORD_HIRES

# DRM preview — окно картинки на физическом дисплее/VTX.
# PREVIEW_W / PREVIEW_H — размер окна. На FPV-выходах часто полезно слегка
# уменьшить, чтобы интерфейс не уходил за safe area дисплея.
# PREVIEW_X / PREVIEW_Y — смещение окна на дисплее. Если сверху видна тонкая
# чёрная полоса в пару пикселей — это offset композитора DRM, лечится
# отрицательным PREVIEW_Y (сдвигаем картинку вверх).
# Подбирай эмпирически: чёрная полоса сверху → уменьшай PREVIEW_Y,
# обрезается снизу → уменьшай PREVIEW_H, обрезается справа → PREVIEW_W.
PREVIEW_W, PREVIEW_H = 720, 576
PREVIEW_X, PREVIEW_Y = 0, 0
CENTER_X, CENTER_Y = MAIN_W // 2, MAIN_H // 2
CENTER_X_LORES, CENTER_Y_LORES = LORES_W // 2, LORES_H // 2

COLOR_GREEN = (0, 255, 0, 0)
COLOR_RED = (0, 0, 255, 0)
COLOR_WHITE = (255, 255, 255, 0)
COLOR_YELLOW = (0, 255, 255, 0)
COLOR_BLACK = (0, 0, 0, 0)
COLOR_CYAN = (255, 255, 0, 0)
CROSS_COLOR = COLOR_WHITE

MAG_ENABLED = True
MAG_SIZE = 170
MAG_ZOOM = 3.0
MAG_MARGIN = 6
MAG_SRC_MIN_SIZE = 8
MAG_ONLY_WHEN_AUX = False

# =========================================================
# 2. LOCK-ON ПАРАМЕТРЫ (трекинг не трогаем)
# =========================================================
ACQ_RADIUS_MAIN = 18
ACQ_RADIUS_LORES = max(8, int(round(ACQ_RADIUS_MAIN * LORES_W / MAIN_W)))

ACQ_LOCK_AT_CROSSHAIR_EXACTLY = True
ACQ_SIZE_SEARCH_RADIUS = 12 * TRACK_SCALE
# Радиусы, которые перебираются ПРИ ЗАХВАТЕ. Одного маленького не хватало:
# цель крупнее окошка касалась его края, измерение отказывало, и коробка
# начинала жизнь со значения по умолчанию. Захват случается редко, поэтому
# несколько попыток здесь стоят дёшево — это не каждый кадр.
SIZE_ACQ_RADII = (12, 20, 32, 50, 80)
# Насколько два измерения считаются одним и тем же размером.
SIZE_ACQ_AGREE_TOL = 0.25
# Снимок внутренностей захвата на диск. Ставится вручную, когда надо ПОСМОТРЕТЬ
# ГЛАЗАМИ, что именно берётся за цель: сам кадр, область поиска, маска порога
# и вырезанный эталон. Пишется только в момент захвата, поэтому не мешает.
# Разбирать по числам мы уже пробовали и трижды починили не то.
# --- ЗАПИСЬ КАДРОВ ---
# Весь день мы сравнивали прогоны между собой и знаем, что это негодно: разные
# цели, разный фон, разная манера водить. Из-за этого одна хорошая ветка была
# зарезана, а одна плохая едва не принята.
#
# Запись сырых кадров всё меняет: по ОДНОМУ И ТОМУ ЖЕ участку можно прогнать
# сколько угодно вариантов алгоритма и сравнить честно, а не через то, как
# оператор вёл руку. Заодно любую сегодняшнюю правку можно проверить задним
# числом.
#
# Пишется ВЕСЬ буфер YUV420 без сжатия — яркость И цветность. Сначала писалась
# одна яркость, и это оказалось изъяном прибора: оператор снял случай, где
# оранжевая флешка на сером стенде по ЯРКОСТИ почти неразличима (контраст цели
# 359 против 667 у соседнего пятна), а по ЦВЕТУ различалась бы легко. Проверить
# цветовой отсев по такой записи было нечем — цветность в неё не попадала.
#
# Цена: 115 КБ на кадр вместо 75, около 2.9 МБ в секунду. Полтора раза дороже,
# зато на записи можно проверять ВСЁ, что делает трекер, а не половину.
RECORD_FRAMES = False          # включается вручную, когда нужен образец
# Снимать образцы В ДВОЙНОМ РАЗРЕШЕНИИ, продолжая ВЕСТИ по обычному.
#
# Зачем. Захват дальше 100 м на 320x240 бессмыслен: машина в 4 м даёт там 13
# пикселей. Двойное разрешение отодвинуло бы захват до 200 м. Цена посчитана
# (совпадение 4.2 -> 16.9 мс, поток 4.5 -> 6.3, проекция 0.5 -> 1.7 — всего
# 9.2 -> 24.8 при бюджете 38), проходит впритык. Но СТАВИТЬ ВСЛЕПУЮ НЕЛЬЗЯ:
# все наши записи 320x240, и проверить не на чем.
#
# Поэтому здесь: камера отдаёт 640x480, трекер УМЕНЬШАЕТ кадр до привычных
# 320x240 и ведёт как прежде — поведение не меняется, — а запись сохраняет
# ПОЛНЫЙ кадр. Тогда на земле по одной и той же записи можно прогнать оба
# разрешения и сравнить честно.
#
# Включать только на время съёмки образцов: уменьшение стоит около 1 мс.
# Сколько ждать схождения автоматики камеры при запуске. Прежние
# фиксированные полсекунды не хватало, и замораживалась экспозиция для тёмной
# сцены — картинка выходила пересвеченной.
CAM_SETTLE_MAX_S = 4.0      # дольше не ждём, чтобы не задерживать запуск
CAM_SETTLE_STEP_S = 0.15    # как часто спрашивать камеру
CAM_SETTLE_STABLE = 3       # столько одинаковых ответов подряд = сошлась
# --- ПАПКА НА КАЖДЫЙ ЗАХВАТ ---
# Кампания по сбору данных — это сотня заходов, и разбирать их надо поштучно.
# Каждый захват пишется в свою папку flight_logs/zahvaty/<метка>_zahvatNN/.
# --- ПРОВЕРКА ДАТЧИКОВ ПРИ ЗАПУСКЕ, НА ЭКРАН ---
# Оператор видит сообщение сразу после старта и до взлёта. Если всё ответило —
# надпись сама пропадает через несколько секунд и не мешает. Если нет — висит,
# называя молчащий датчик поимённо.
#
# Надписи ЛАТИНИЦЕЙ: шрифты OpenCV кириллицы не знают и рисуют её знаками
# вопроса (проверено).
STARTUP_CHECK_AFTER_S = 8.0    # столько ждём отклика датчиков
STARTUP_OK_SHOW_S = 5.0        # столько показываем «всё в порядке»
STARTUP_SAFE_FRAC = 0.62       # какую долю ширины кадра считаем видимой
STARTUP_FONT = 1.6             # желаемый размер; ужимается, если не влезает
GPS_EXPECTED = False           # ставить True на замерном борту, где GPS есть
GPS_SATS_ENOUGH = 6            # со скольких спутников считаем захват годным
LOCK_LOG_ENABLED = True
LOCK_LOG_DIR = "zahvaty"
RECORD_HIRES = False
if RECORD_HIRES:
    CAM_W, CAM_H = LORES_W * 2, LORES_H * 2
RECORD_DIR = "recordings"      # внутри каталога полётных логов
RECORD_MAX_SECONDS = 25.0      # предел одной записи
RECORD_MAX_MB = 120.0          # и предел по месту на карте
ACQ_DEBUG_DUMP = True
ACQ_DEBUG_DIR = "acq_debug"   # внутри каталога полётных логов
ACQ_DEBUG_MAX = 8
# Предел растяжения области поиска размера под крупную цель. Больше — дороже
# по процессору и выше риск слить цель с фоном в одну связную компоненту.
# ЗАМЕРЕНО по заходу 154500: 85% отказов оценки размера — код 2, «пятно
# залило область поиска» (1302 кадра против 228 у «нет пятна в центре»).
# За этим стоит ЗАМОК: область поиска считалась как cur_w * 1.6, а cur_w
# упирался в LOCK_MAX_W = 38. Значит область не могла превысить 60 px, и
# цель шире 64 px отвергалась КАК СЛИШКОМ БОЛЬШАЯ — навсегда. Коробка не
# росла, потому что не могла измериться, и не могла измериться, потому что
# не росла.
SIZE_SEARCH_RADIUS_MAX = 100 * TRACK_SCALE
# Как замок размыкается: если оценка отказала именно из-за «залило область»,
# в следующий раз область берётся шире. Цена платится только когда она
# действительно нужна — при мелкой цели область остаётся прежней.
# Замерено на малине: область 81x81 стоит 5.2 мс, 161x161 — 15.1 мс,
# 201x201 — 22.4 мс. При проверке раз в 4 кадра это 1.3 / 3.8 / 5.6 мс на
# кадр при бюджете 38 мс.
SIZE_R_BOOST_STEP = 1.5
# БЫЛО 4.0, и это моя ошибка. При расширении вчетверо область поиска
# разрасталась до 201x201 на кадре 320x240 — почти весь кадр. В такой области
# порог по яркости связывает в ОДНО пятно всю сцену, и признак «залило
# область» срабатывает ГАРАНТИРОВАННО. То есть расширение не размыкало замок,
# а само его и запирало: за заход 155721 область доходила до предела 100, а
# отказ «залило» остался у 859 кадров.
#
# Область обязана быть сравнима с целью, а не с кадром. Двух шагов хватает,
# чтобы покрыть цель с запасом, дальше расширять бессмысленно.
SIZE_R_BOOST_MAX = 2.25
# Второй способ оказаться внутри цели, найденный при проверке. Когда область
# целиком лежит на объекте, МЕДИАНОЙ становится сам объект, отклоняться от неё
# нечему, и пятна в центре не находится вовсе — отказ приходит с кодом 1, а не
# 2. То есть «нет пятна» бывает по двум противоположным причинам:
#   слабый контраст цели   -> в области ЕСТЬ разброс яркости, расширять
#                             бессмысленно;
#   область внутри цели    -> область РОВНАЯ, и надо смотреть шире.
# Различаем их по разбросу яркости в самой области.
SIZE_UNIFORM_STD = 8.0

ACQ_FORCE_CENTER_LOCK = True
# СНИМКИ ЗАХВАТА (20260901_164417) закрыли вопрос, который числа скрывали.
# На каждом из шести захватов измерение размера отказало, и видно почему:
# порог по яркости НЕ ОТДЕЛЯЕТ предмет. Флешка сливается с рукой, которая её
# держит, с тенью под ней, с тёмным косяком двери за ней — всё, что темнее
# или светлее медианы области, связывается в ОДНО пятно, и оно доходит до
# края области. Отсюда 'пятно (0, 18, 34, 37)' во всех итогах: пятно начинается
# ровно на границе.
#
# Это не настройка и не порог. Разделить предмет и держащую его руку по
# яркости нельзя в принципе: они одинаково отличаются от стены.
#
# Поэтому сегментация при захвате выключена, а коробка начинает с разумного
# размера. Эталон берётся вдвое больше неё, то есть 40x40 — в него попадает
# и сам предмет, и его окружение. Именно окружение и якорит совпадение:
# внутренний кусок фактуры уезжает вместе с ростом предмета, а очертание с
# фоном вокруг — нет.
#
# Абсолютный размер при этом угадан, а не измерен, и это честно сказано. Но
# для того, ради чего размер и нужен — времени до контакта — важен не он, а
# ОТНОСИТЕЛЬНОЕ изменение: в tau = размер / скорость роста абсолютная величина
# сокращается. А относительное изменение меряет примерка масштабов, и она в
# загромождённой сцене работает — это проверено на модели комнаты.
ACQ_SIZE_BY_SEGMENTATION = False
# ЗАМЕРЕНО на модели фактурного фона. Мелкая цель 13 px (флешка в полутора
# метрах) растёт до 40, то есть в 3.08 раза. Насколько за ней успевает коробка
# при разном начальном размере:
#
#     начальная 8  (эталон 16): выросла в 1.56 раза — НЕ ДОГНАЛА
#     начальная 12 (эталон 24): выросла в 3.18 раза — почти точно
#     начальная 20 (эталон 40): выросла в 3.72 раза — перелёт
#
# Обе крайности плохи по своей причине. При 8 эталон 16x16 слишком мал, чтобы
# в нём различался масштаб, — рост не замечается. При 20 эталон 40x40 для
# 13-пиксельной цели набивается фоном, и на фактурном фоне трекер держится за
# фон, а не за предмет: оператор это и увидел как 'мелкую цель вообще не
# локает'.
#
# 12 даёт эталон 24x24 — это примерно вдвое шире цели, ровно то отношение,
# на которое рассчитан TEMPLATE_SCALE.
ACQ_DEFAULT_LOCK_W = 12 * TRACK_SCALE
ACQ_DEFAULT_LOCK_H = 12 * TRACK_SCALE
ACQ_MIN_PEAK = 1.6
ACQ_MIN_STD = 1.2

# НЕ масштабируются: именно в неизменных нижних порогах и состоит выигрыш по
# дальности. При вдвое большем разрешении цель занимает вдвое больше пикселей,
# значит те же 5 и 14 пикселей достигаются с вдвое большей дистанции.
# Верхние границы, наоборот, масштабируются — иначе близкая цель упиралась бы
# в потолок вдвое раньше и коробку начало бы обрезать.
LOCK_MIN_W = 5
LOCK_MIN_H = 5
# Предел размера коробки. Был 38, и это делало невозможным сразу две вещи.
#
# Первое: крупная цель просто не могла быть представлена. Коробка упиралась
# в 38 px, шаблон покрывал лишь кусок объекта, и матч гулял по его фактуре —
# ровно то, что оператор видит как «бегает по объекту, а при отдалении
# сползает на край или за него».
#
# Второе, и это хуже: ТЕРМИНАЛЬНЫЙ РЕЖИМ БЫЛ НЕДОСТИЖИМ. Он включается при
# box_frac >= 0.18, то есть когда коробка занимает 18% площади кадра. При
# пределе 38 на кадре 320x240 максимум составлял 1.9%. Порог нельзя было
# перейти ни при какой цели и ни на каком расстоянии — и в логах он ни разу
# и не сработал. Для 18% нужна коробка 118 px.
LOCK_MAX_W = 120 * TRACK_SCALE
LOCK_MAX_H = 120 * TRACK_SCALE
LOCK_PAD = 2.05
# Во сколько раз шаблон больше коробки цели. Значение важно тем, какую долю
# шаблона занимает ФОН, а не цель:
#     2.0 -> цель занимает 25% площади шаблона, фон 75%
#     1.3 -> цель занимает 59%, фон 41%
#
# Замерено на борту: при 2.0 на 43% медленных кадров на карте откликов
# находился конкурент НЕ СЛАБЕЕ выбранного пика. Это прямое следствие того,
# что шаблон на три четверти состоит из фона: матчер сравнивает фон с фоном,
# и совпадений находится много. Защита от неоднозначности (MATCH_AMBIGUITY_
# GUARD) это компенсирует, но ценой почти постоянного отключения якоря по
# шаблону — ведёт один оптический поток, а он копит дрейф.
#
# 1.3 оставляет немного контекста (он помогает держать мелкую цель), но фон
# перестаёт доминировать. Автор уже двигал параметр в эту сторону, с 2.9 до
# 2.0, с пометкой «меньше фона в шаблоне, лучше держит на пёстром фоне».
#
# ПРОВЕРЯЕМОЕ ПРЕДСКАЗАНИЕ: доля кадров со срабатыванием защиты должна
# заметно упасть. Если не упадёт — гипотеза про фон в шаблоне неверна, и
# правку надо откатить.
# ПРОВЕРЕНО НА БОРТУ: значение 1.3 испытано и ОТКАЧЕНО. Предсказание не
# сбылось — доля кадров со срабатыванием защиты осталась прежней (45% против
# 43%), то есть фон в шаблоне конкурентов не порождает. При этом средний
# захват просел с 18.5 до 14.8 с, длиннейший с 57.4 до 37.4 с.
# Не повторять без нового механизма объяснения.
TEMPLATE_SCALE = 2.0
TEMPLATE_MIN = 14
# Был 58, и это оказалось той самой преградой, из-за которой рамка уезжала с
# однородного предмета. Эталон 58x58 внутри чёрной точки 96 px — ровный
# квадрат без признаков, разброс яркости РОВНО НОЛЬ. Расширение коробки не
# помогало: коробка росла до предела 120, а эталон упирался в 58 и оставался
# внутри предмета.
#
# Чтобы держаться за однородный предмет, в эталон обязан попадать его КРАЙ.
# При TEMPLATE_SCALE = 2 эталон 110 покрывает предмет до 55 px целиком.
#
# ЦЕНА ЗАМЕРЕНА на малине: сравнение с эталоном 58x58 стоит 5.6 мс, 80x80 —
# 7.3 мс, 110x110 — 12.2 мс при бюджете кадра 38 мс. Платится она только
# когда цель ДЕЙСТВИТЕЛЬНО крупная, то есть на последних метрах захода.
TEMPLATE_MAX = 110 * TRACK_SCALE

SEARCH_MARGIN = 24 * TRACK_SCALE         # было 28 — чуть тише search-окно, меньше шансов уцепиться за фоновый паттерн
# --- ОТСЕВ ПО ДВИЖЕНИЮ ---
# Когда цель того же цвета и яркости, что фактурный фон, сравнивать по виду
# нечего — особенно если цель МЕЛКАЯ: маленький шаблон это просто «кусочек
# текстуры», а кусочки текстуры похожи друг на друга. Наращивание качества
# сравнения тут упирается в потолок: информации в шаблоне мало.
#
# Движение свободно от этого ограничения. Оно НЕ ЗАВИСИТ ОТ РАЗМЕРА ЦЕЛИ:
# даже трёхпиксельная цель движется иначе фона, и этого достаточно.
#
# Как считается: по сетке точек в окне поиска берётся оптический поток.
# Медиана по всем точкам — это движение ФОНА (он занимает большую часть
# площади). Дальше каждая точка сравнивается с фоном: движется как фон —
# штраф, движется иначе — не штрафуется.
#
# ТО ЖЕ ТРЕБОВАНИЕ, ЧТО И К ЦВЕТУ: не сделать хуже. Признак включается только
# когда цель ДЕЙСТВИТЕЛЬНО движется иначе фона. Если она стоит (или дрон
# летит на неподвижную наземную цель — тогда цель часть неподвижного мира),
# признак информации не несёт и остаётся выключенным.
MOTION_GUARD_ENABLED = True
# Шаг сетки точек в окне поиска, пиксели. Мельче — точнее и дороже.
# Шаг сетки для оценки движения ФОНА. Фон крупный, частая сетка ему не нужна,
# а стоимость растёт как квадрат: шаг 8 обходился в 12 мс на борту, шаг 12 —
# в 5 мс. Измерено, а не прикинуто.
MOTION_GRID_STEP = 12 * TRACK_SCALE
# Насколько цель должна двигаться иначе фона, чтобы признаку верить, px/кадр.
MOTION_MIN_SEPARATION = 1.5 * TRACK_SCALE
# Отклонение от движения фона, считающееся полным различием, px/кадр.
MOTION_REF_DIST = 3.0 * TRACK_SCALE
# Разность яркости, считающаяся полным откликом движения. Мелкая цель той же
# фактуры даёт слабый отклик, поэтому масштаб небольшой.
MOTION_DIFF_REF = 4.0
# Вес штрафа за движение вместе с фоном.
MOTION_PENALTY = 0.5

# --- ОТСЕВ ПО ЦВЕТУ ---
# Трекинг идёт по яркости, а поток с камеры — YUV420: плоскости цветности УЖЕ
# лежат в том же буфере, сразу под яркостью. Мы их выбрасывали. Брать их
# бесплатно — ни лишнего захвата, ни конвертации.
#
# Зачем: сползание на фон происходит, когда фоновое пятно похоже на цель ПО
# УЗОРУ ЯРКОСТИ. Цвет — независимый признак, он отсекает такого кандидата,
# даже если рисунок совпал.
#
# ГЛАВНОЕ ТРЕБОВАНИЕ — не сделать хуже. Обеспечивается тем, что цвет
# включается НЕ ВСЕГДА, а только когда он реально различает цель и фон. При
# захвате цветность цели сравнивается с цветностью её окружения; если они
# близки (серая цель на сером фоне), цвет информации не несёт и остаётся
# ВЫКЛЮЧЕННЫМ до конца этого захвата — поведение тогда в точности прежнее.
# ВЫКЛЮЧЕН ПО ЗАМЕРУ. Пятнадцать записей с цветностью, прогон одного и того же
# кода с цветом и без:
#
#     всего: с цветом 18.6% кадров на фоне, без цвета 17.5%
#
#     и по записям — цвет НИ РАЗУ не помог, а трижды навредил:
#         131038:  20.1% против 14.5%
#         131204:  80.6% против 75.0%
#         131212:  26.1% против 17.8%
#
# Эффект односторонний: в девяти записях ровно ноль разницы, в трёх хуже, ни в
# одной лучше. Это не шум, это признак того, что признак не работает.
#
# Почему. Цветность вдвое грубее яркости и сильно размыта, а цели у нас мелкие
# — десятки пикселей. Карта штрафа выходит грубее самой цели и сдвигает пик,
# вместо того чтобы его уточнять. Различимость при этом меряется верно: там,
# где она высокая, цвет и вредил сильнее всего.
#
# Прежнее впечатление «с цветом трекер лучше держится» было снято на глаз, на
# другой сборке и до полутора десятков других исправлений. Прямое сравнение на
# одних и тех же кадрах его не подтверждает.
#
# Код оставлен: на крупной цветной цели он может оказаться полезен, и тогда
# включается одной строкой. Но на нынешних задачах он только ест процессор.
COLOR_GUARD_ENABLED = False

# --- СЛЕЖЕНИЕ ПО ЦВЕТОВОЙ ПРОЕКЦИИ ---
# Отсев по цвету штрафом провалился (см. журнал опытов). Но сигнал в цвете ЕСТЬ,
# и провалился способ, а не признак. Замерено на 15 записях с цветностью:
#
#     контраст цель/фон   по яркости   по цвету
#         131204               5.4       110.0    <- 75% срывов
#         131140               0.9        63.7
#         131121               0.7        22.3
#         131116               1.6        30.6
#
# То есть ровно там, где трекер срывался, цель по яркости почти невидима, а по
# цвету видна прекрасно.
#
# ПРАВИЛЬНЫЙ СПОСОБ — не штрафовать поверх поиска по яркости, а СТРОИТЬ
# КАРТИНКУ, в которой цветовое отличие превращено в яркостное, и искать по ней
# обычным образом. Берётся направление «цель минус фон» в цветности, снятое при
# захвате, и каждый пиксель проецируется на него. Оранжевое на сером становится
# ярким, сам серый — плоским, фактура стенда пропадает.
#
# ЗАМЕРЕНО прогоном одного и того же кода по 15 записям:
#     слежение по яркости  11.4% кадров на фоне
#     слежение по цвету     1.1%
# Улучшение вдесятеро, и оно приходится на те самые трудные записи.
TRACK_ON_COLOR = True
# Во сколько раз цветовой контраст должен превзойти яркостный, чтобы перейти на
# цвет. ПОДОБРАНО ПЕРЕБОРОМ по 15 записям с цветностью:
#     1.4 / 1.2 / 1.0 / 0.8 -> 9.5%   (цвет выбирается редко)
#     0.5                   -> 5.8%
# То есть переходить стоит даже когда цвет выигрывает у яркости лишь вдвое
# меньше единицы — потому что проекция не просто добавляет контраст, она ещё и
# СХЛОПЫВАЕТ фактуру фона, а та мешает сильнее, чем помогает яркость цели.
TRACK_ON_COLOR_MIN_GAIN = 0.5
# Ниже этого разделения по цветности переходить нельзя вовсе: направление
# проекции станет шумом.
TRACK_ON_COLOR_MIN_SEP = 8.0
TRACK_ON_COLOR_SCALE = 2.0
# Как часто пересчитывать ФОН в оси цвета. Цвет самой цели — её опознавательный
# признак, он остаётся с захвата. А фон меняется по ходу захода: цель уходит с
# серого асфальта на жёлтое поле, и ось, в которой зашит старый фон, становится
# неверной. Поэтому фон обновляется, а цель — нет.
TRACK_ON_COLOR_BG_EVERY = 8
# Если цель и фон сравнялись по цвету, вести по цветовой проекции больше
# нельзя: направление оси превращается в шум. Возвращаемся на яркость.
TRACK_ON_COLOR_DROP_SEP = 5.0
# Насколько цветность цели должна отличаться от окружения, чтобы цвету верить.
# Единицы — сумма отклонений по U и V (каждая 0..255, серому отвечает 128).
COLOR_MIN_SEPARATION = 12.0
# Вес цветового штрафа.
#
# ЗАМЕРЕНО: при 0.25 цвет включался (различимость 14-64), но поведение не
# менялось. Причина видна из чисел момента срыва: выбранный пик 0.54,
# конкурент 0.78, разрыв 0.24. Максимальный штраф 0.25 лишь ЕДВА перекрывал
# этот разрыв, да и то при полностью чужом цвете. То есть цвет физически не
# мог переломить решение — он был слабее задачи.
#
# 0.6 даёт запас: конкурент чужого цвета проигрывает уверенно. Это безопасно
# именно потому, что цвет включается только когда различает цель и фон, а
# самой цели штраф почти не достаётся (её цвет совпадает с подписью).
COLOR_PENALTY = 0.6
# Отклонение цветности, считающееся ПОЛНЫМ несовпадением.
# Было 40 — слишком много: фон, отличающийся на 16 единиц, получал лишь 40%
# штрафа. Наблюдаемая различимость цель/фон 14-64, поэтому 20 означает, что
# заметно другой цвет штрафуется в полную силу.
COLOR_REF_DIST = 20.0
# Минимальный размер цели в пикселях ЦВЕТНОСТИ: она вдвое грубее яркости, и у
# мелкой цели цветных пикселей единицы — оценка становится ненадёжной.
COLOR_MIN_TARGET_CHROMA_PX = 2

MATCH_MIN_SCORE = 0.22
# Доверие к матчу падает, если на карте откликов есть конкурент НЕ ХУЖЕ
# выбранного. Замерено на борту в момент срыва:
#     t=58.71  score=0.54  второй кандидат=0.78
# То есть удерживал рамку только штраф за расстояние, а сам матч указывал на
# фон. Через двадцать кадров рамка туда и переехала, и score вырос до 0.87 —
# неподвижный фон совпадает идеально.
#
# Механизм объясняет обе приметы: на быстром движении цель СМАЗЫВАЕТСЯ и её
# собственный score падает, а неподвижный фактурный фон остаётся резким и
# честно выигрывает сравнение.
#
# Ниже — вес матча в слиянии с потоком. Когда конкурент сильнее выбранного,
# вес уходит к нулю и позицию ведёт ОПТИЧЕСКИЙ ПОТОК: он следит за реальным
# движением цели и на фон не смотрит. В обычной ситуации (конкурент слабее)
# ничего не меняется — правка срабатывает только в самом отказе.
MATCH_AMBIGUITY_GUARD = True
MATCH_WEIGHT = 0.22          # прежний постоянный вес
MATCH_WEIGHT_MIN = 0.02      # почти полностью доверяем потоку
# Запас пика над конкурентом, при котором матчу верим полностью.
# Откалибровано по реальному логу борта, а не выбрано на глаз:
#   обычная работа  — запас около +15%
#   момент срыва    — запас -44% (конкурент сильнее)
# Порог 10% разделяет эти случаи и НЕ задевает обычные кадры: при 25%
# (первая прикидка) вес срезался бы и в нормальной работе.
MATCH_LEAD_FULL = 0.10
MATCH_GOOD_SCORE = 0.40    # было 0.34 — выше планка «уверенного» матча
# Штраф за то, что совпадение найдено ДАЛЕКО от предсказания потока.
#
# ВОЗВРАЩЁН К 0.55 ПОСЛЕ ПРОВЕРКИ НА НОВЫХ ЗАПИСЯХ. Вчера он был снижен до
# 0.20 по перебору на семи записях — и это оказалось ПЕРЕПОДГОНКОЙ под них.
# Семнадцать новых записей, которых подбор не видел, дали обратный порядок:
#
#                       старые 7      новые 17      все 24
#     0.55 (было)          6.1%         23.8%        15.5%
#     0.42                 3.2%         23.9%        14.6%
#     0.30                 3.1%         24.6%        14.8%
#     0.20 (вчера)         2.6%         28.3%        15.2%
#
# На старых записях снижение помогало вдвое, на новых — вредит. По всем 24
# разброс 14.6-15.5%, то есть настройка НИЧЕГО НЕ РЕШАЕТ: она лишь меняет
# одну беду на другую. Значит держим прежнее значение, а искать надо не здесь.
#
# Урок записан в журнал опытов: семи записей мало, чтобы подбирать настройку.
DIST_PENALTY = 0.55
MAX_LOCK_STEP = 32

FLOW_MIN_POINTS = 3
FLOW_ERR_MAX = 20.0 * TRACK_SCALE
FLOW_MAX_STEP = 30.0 * TRACK_SCALE
FLOW_REFRESH_EVERY = 1
# Параметры расчёта потока вынесены сюда, чтобы их можно было мерить перебором
# по записям. Поток оказался САМЫМ ДОРОГИМ узлом — 8.1 мс на малине против 4.0
# у самого совпадения, — а подбирался он никогда.
# ПОДОБРАНО ПЕРЕБОРОМ по 39 записям. Результат слежения не меняется НИ НА ОДНОМ
# из вариантов ниже — ни на новых записях (5.8%), ни на старых (16.8%):
#     уровней пирамиды   2 -> 1 -> 0    без изменений
#     итераций          14 -> 8 -> 5    без изменений
#     окно вокруг точек 72 -> 48 -> 32  без изменений
# То есть поток был настроен с запасом на движения, которых у нас не бывает:
# цель смещается единицы пикселей за кадр, а пирамида из трёх уровней рассчитана
# на десятки. Берём середину: запас остаётся, цена падает.
FLOW_WIN = 15
FLOW_LEVELS = 1
FLOW_ITERS = 8
# Нижний предел запаса вокруг точек. Ниже него окно перестаёт вмещать саму
# область поиска LK, и поток начинает врать.
FLOW_WINDOW_PAD_MIN = 24 * TRACK_SCALE
# Запас окна оптического потока вокруг точек, пиксели.
#
# ВАЖНО: запас должен покрывать не только смещение цели, но и КОНТЕКСТ,
# который нужен самой пирамиде. При winSize=15 и maxLevel=2 окно 15 px на
# верхнем уровне соответствует 60 px на исходном изображении. С запасом 24 px
# точки у края окна теряли контекст, и поток по ним считался хуже, чем по
# полному кадру — средний score упал с 0.726 до 0.643.
FLOW_WINDOW_PAD = 72 * TRACK_SCALE
# ВКЛЮЧЕНО И НА 320x240. Прежде было только для 640x480, и рассуждение было
# верным ДЛЯ ТОГДАШНЕГО запаса: при постоянных 72 окно занимало почти весь
# кадр, экономить было нечего.
#
# Теперь запас считается от самих точек и выходит около 45. У типичной цели
# точки лежат кучно, окно получается примерно 114x114 против кадра 320x240 —
# это в шесть раз меньше площади, а поток стоит именно пропорционально ей.
#
# Замерено профилированием: поток оказался САМЫМ дорогим узлом, 8.1 мс на
# малине против 4.0 у самого совпадения — именно потому, что считался по
# полному кадру каждый кадр.
FLOW_WINDOW_ENABLED = True

HOLD_FRAMES = 10
LOST_LIMIT = 28

ACQ_SETTLE_FRAMES = 1
REQUIRE_AUX_TOGGLE_AFTER_LOST = True

FREEZE_TEMPLATE = False    # было True — шаблон плавно адаптируется под рост цели на сближении
TEMPLATE_UPDATE_ALPHA = 0.010   # доля нового кадра в шаблоне на каждом «уверенном» матче
# Доля свежего вида, подмешиваемая в ИСХОДНЫЙ эталон при смене масштаба.
# Больше, чем TEMPLATE_UPDATE_ALPHA, потому что случается редко — только когда
# масштаб действительно изменился, а не каждый кадр.
TEMPLATE_BASE_ALPHA = 0.15
# Следовать ли шаблону за масштабом цели при сближении.
#
# ВЫКЛЮЧЕНО, и это вывод из измерений на борту: любое вмешательство сюда
# ухудшало трекинг (0.726 -> 0.498 при пересчёте накопленного шаблона,
# 0.726 -> 0.561 при пересборке из текущего кадра). Исходное поведение — не
# трогать шаблон при смене размера — оказалось лучше обоих вариантов.
#
# Флаг оставлен, потому что исходная проблема реальна: на сближении шаблон
# застревает в старом масштабе и рамка уползает к краю объекта. Вариант с
# масштабированием ЭТАЛОНА свободен от обеих найденных причин, но в деле не
# проверен. Включать только для замера, сравнивая score с текущим.
TEMPLATE_RESCALE_ON_SIZE_CHANGE = False

# =========================================================
# 3. УПРАВЛЕНИЕ
# =========================================================

# --- ПО-ОСНЫЕ ПЕРЕОПРЕДЕЛЕНИЯ ---
# По умолчанию ВСЁ passthrough (живой стик). На локе ничего не меняется,
# моторы должны реагировать ровно как при выключенном AUX4.
# Используй это как нулевую точку:
#   1) убеждаешься, что MSP override-канал чистый (моторы спокойны на локе,
#      газ корректно возвращается после AUX OFF);
#   2) потом включаешь по ОДНОЙ оси и смотришь, какая именно вызывает
#      «спул моторов на локе» — обычно это PID-windup FC по неправильной
#      команде угла, лечится не у нас, а в Betaflight (см. README ниже).
# --- РЕЖИМ НАБЛЮДЕНИЯ ---
# Трекер захватывает цель, ведёт её и всё пишет, но В УПРАВЛЕНИЕ НЕ ЛЕЗЕТ.
# Нужен для сбора данных: заходы выполняет пилот руками, а мы смотрим и
# записываем, чтобы потом вывести из его действий закон наведения.
#
# ЭТО НЕ ПРОСТО ФЛАГИ OVERRIDE_*. Их недостаточно: override_active
# выставлялся при слежении БЕЗУСЛОВНО, и на полётнике включался MSP OVERRIDE.
# А пока он включён, MSP_RC возвращает НАШИ ЖЕ значения вместо стиков пилота —
# в логе оказалось бы эхо трекера вместо действий человека, и выглядело бы это
# совершенно правдоподобно. Вся кампания налётов ушла бы впустую.
#
# Здесь оверрайд не включается вовсе. Заодно это гарантия безопасности: машина
# физически не может вмешаться в управление, пока пилот заходит на цель.
OBSERVE_ONLY = False

OVERRIDE_ROLL = True
OVERRIDE_PITCH = True
OVERRIDE_YAW = True
OVERRIDE_THROTTLE = True        # True = динамика газа по dy, иначе живой стик

# Знак pitch. Признак неправильного знака: задние моторы греются,
# на низком стике моторы раскручиваются.
# -1 = стандартный Betaflight (PWM<1500 = нос вниз).
# +1 = инвертированный (как было в старом iNav-сетапе).
PITCH_SIGN = -1
ROLL_SIGN = +1
YAW_SIGN = +1

# Максимальное отклонение каждой оси от 1500 (в PWM).
# На стенде раньше стояло 120 ради подстраховки от runaway_takeoff_prevention
# при отсутствии аэродинамики. В реальном полёте этого мало:
# при P_GAIN_ROLL=11 потолок 120 достигается уже на adx=11 — авторитета не хватает
# для агрессивных манёвров на терминальной фазе.
# Сейчас выставлено 400 / 400 / 300 = 80% / 80% / 60% полного стика.
# Это даёт квадрату полную скорость вращения по rate-профилю Betaflight,
# но всё ещё оставляет запас «до края». Если хочешь полный авторитет — ставь 500.
MAX_ROLL_DEFLECT = 400
MAX_PITCH_DEFLECT = 400
MAX_YAW_DEFLECT = 300

# --- ГЭЙНЫ ---
P_GAIN_YAW = 2.5
P_GAIN_ROLL = 11.0
D_GAIN_ROLL = 6.0
P_GAIN_PITCH = 3.5
D_GAIN_PITCH = 1.2

# I-компоненты для прицеливания: добивают остаточную ошибку P+D,
# чтобы крестик стоял в центре рамки, а не у её границы.
# Затухание 0.985 за кадр = половина за ~1.5 сек при 30 FPS — медленно тянет к нулю,
# но быстро отпускает, если цель ушла.
# Anti-windup встроен в хелпер: I не накапливается, если выход уже саттурирован
# в том же направлении.
I_GAIN_ROLL = 0.10
I_GAIN_PITCH = 0.08
I_GAIN_YAW = 0.05
ROLL_INTEGRAL_MAX = 40.0
PITCH_INTEGRAL_MAX = 40.0
YAW_INTEGRAL_MAX = 30.0
ROLL_INTEGRAL_DECAY = 0.985
PITCH_INTEGRAL_DECAY = 0.985
YAW_INTEGRAL_DECAY = 0.985

DEADBAND_X = 1
DEADBAND_Y = 1
AIM_OFFSET_X = 0
AIM_OFFSET_Y = 10                # ТОЛЬКО для pitch (статический), для газа не применяется

# --- КОМПЕНСАЦИЯ ТАНГАЖА ОТ MSP_ATTITUDE ---
# В моменте разгона квад завален носом вниз, цель уезжает вверх в кадре.
# Если этого не учитывать, control пытается «выровнять» нос на цель,
# квад теряет горизонтальное ускорение и тормозит. С компенсацией прицельная
# точка автоматически сдвигается так, чтобы стационарный наклонный полёт
# к цели не вызывал отработки pitch.
PITCH_ATTITUDE_COMP_ENABLED = True
# IMX219 в 640×480 (биннинг до 1640×1232, потом scale): VFOV ≈ 41° → 11.7 px/°.
# Подбери под свой реальный масштаб, если разрешение / crop другой.
PIXELS_PER_PITCH_DEG = 11.7
# Знак компенсации. ЗАМЕРЕНО по заходу 141912, три захвата, регрессия по
# уровню (не по разностям):
#
#   захват   цель в кадре   компенсация   ПРИЦЕЛ dy_aim
#      1      -6.01 px/°     -0.50 px/°     -6.90 px/°
#      2     -12.24 px/°     -4.30 px/°    -17.38 px/°
#      3      -8.80 px/°     -7.64 px/°    -16.78 px/°
#
# Компенсация двигалась В ТУ ЖЕ сторону, что и цель, и прицельная ошибка
# СКЛАДЫВАЛАСЬ вместо того, чтобы гаситься: dy_aim выходил примерно вдвое
# круче самой цели вместо нуля.
#
# Этот вывод не зависит ни от знака тангажа в прошивке, ни от того,
# перевёрнута камера или нет. Что бы там ни было, для гашения компенсация
# ОБЯЗАНА идти против наблюдаемого смещения цели — а она шла вместе с ним.
#
# Совпадает с журналом: строка 'pitch-comp outweighs real error' стоит почти
# в каждом VERDICT.
PITCH_COMP_SIGN = +1
# Раз в столько кадров слежения писать в журнал, ГАСИТ ли компенсация наклон.
# Знак здесь зависит от физической установки камеры, а она может смениться —
# поэтому правка проверяет себя сама на каждом заходе, а не один раз мной.
PITCH_COMP_SELFCHECK_FRAMES = 300
# Не даём компенсации улететь на полкадра при дёргании квада.
MAX_PITCH_COMP_PX = 100.0
# Низкочастотный фильтр на fc_pitch_deg — без него aim-точка прыгает на каждом твике.
PITCH_COMP_ALPHA = 0.30
# Если данные с FC старше этого порога — компенсация не применяется.
FC_PITCH_TIMEOUT = 0.20

# --- УПРЕЖДЕНИЕ ПО СКОРОСТИ ЦЕЛИ (LEAD / PREDICTIVE AIM) ---
# Считаем скорость центра коробки в пикселях/кадр, экстраполируем позицию
# цели на LEAD_FRAMES кадров вперёд и целимся в неё, а не в текущее положение.
# Это компенсирует суммарную задержку петли управления (~150-200 мс):
# трекинг → MSP → FC → моторы → инерция квада → следующий кадр камеры.
LEAD_AIM_ENABLED = True
# Кадров упреждения. 0 = выключено. 3-4 консервативно, 5-7 агрессивно.
# При FPS≈30 и реальной задержке петли ~150-200 мс «честное» упреждение
# должно быть 4-6 кадров; чуть выше = упреждение по реальной скорости + запас на разворот.
LEAD_FRAMES = 4
# Низкочастотный фильтр на скорость цели. Без него прицел прыгает от пиксельных
# шумов трекера (особенно от субпиксельной интерполяции на покоящейся цели).
LEAD_VEL_ALPHA = 0.25
# Если межкадровая скорость больше этого порога (px/кадр) — кадр считается
# глитчем (re-lock / occlusion) и не идёт в фильтр.
LEAD_MAX_VEL_JUMP = 25.0 * TRACK_SCALE
# Сколько кадров после первого LOCK игнорируем упреждение — даём фильтру скорости
# набрать корректное значение, иначе на первом кадре прицел улетит в сторону.
LEAD_MIN_STABLE_FRAMES = 5
# Жёсткий потолок на величину упреждения по каждой оси (PX). Без него
# при шумном видении (например, дождь) можно получить смещение на полкадра.
LEAD_MAX_PX = 80.0 * TRACK_SCALE

# --- VELOCITY FEEDFORWARD ---
# Прямой проактивный вклад скорости цели в PWM-команду, поверх PID по позиции.
# Лечит ту же системную задержку, что и LEAD, но действует по-другому:
# LEAD сдвигает ЦЕЛЬ (предсказанную позицию), FF сдвигает выход PWM
# (мотор начинает работать ДО появления позиционной ошибки).
# Работает в паре с LEAD — они не конкурируют, а дополняют друг друга.
# Подбор: 1.5-3.0 для roll, в полёте калибровать на пересекающей цели.
FF_GAIN_ROLL = 2.0      # PWM на (px/кадр) скорости цели по X
FF_GAIN_PITCH = 1.5     # PWM на (px/кадр) скорости цели по Y
FF_GAIN_YAW = 1.0       # PWM на (px/кадр) скорости цели по X (для yaw тоже X)

# --- ТЕРМИНАЛЬНЫЙ РЕЖИМ ---
# Когда коробка занимает заметную часть кадра — мы в финальной фазе.
# Времени на интеграл нет, нужны рефлексы: повышаем P, поджимаем I.
# Триггер: площадь коробки относительно всего кадра.
TERMINAL_MODE_ENABLED = True
TERMINAL_BOX_FRAC_THRESHOLD = 0.18   # 18% площади кадра = «уже близко»
TERMINAL_P_MULTIPLIER = 1.6          # P-гэйны умножаем на это в терминале
TERMINAL_I_MULTIPLIER = 0.3          # I-гэйны срезаем (нет времени интегрировать)
TERMINAL_FF_MULTIPLIER = 1.3         # FF тоже приподнимаем — реакция должна быть резче

# --- АДАПТИВНЫЙ SEARCH_MARGIN ---
# При неподвижной цели бессмысленно искать в большом окне — больше шансов
# уцепиться за фоновый паттерн. При быстрой — наоборот нужно расширить,
# иначе цель может выскочить за окно за один кадр.
ADAPTIVE_SEARCH_MARGIN = True
SEARCH_MARGIN_MIN = 14 * TRACK_SCALE               # при неподвижной цели
SEARCH_MARGIN_MAX = 36 * TRACK_SCALE               # при цели на полной скорости трекера
SEARCH_MARGIN_VEL_REF = 12.0 * TRACK_SCALE         # flow-motion (px/кадр) для перехода к MAX

# --- АДАПТАЦИЯ РАЗМЕРА КОРОБКИ ---
# Раз в N кадров при высоком матч-скоре заново оцениваем связную компоненту
# под текущим центром лока и сдвигаем lock_w/lock_h в её сторону.
# Это решает «дрейф зацепом за край» при сближении — коробка растёт вместе
# с целью, и шаблон-матч продолжает якориться по центру, а не по краю.
# --- РАЗМЕР ПО МАСШТАБУ СОВПАДЕНИЯ ---
# Прежний способ мерил размер сегментацией: порог по яркости вокруг центра и
# связная компонента. ПРОВЕРЕНО на загромождённой сцене — способ негоден в
# принципе, а не по настройкам:
#     цель  20 px -> намерил 120   (слился с соседним предметом)
#     цель  38 px -> намерил  80
#     цель  64 px -> намерил 120
# Он либо упирается в край области, либо сливает цель с соседями и ВРЁТ. На
# борту это и наблюдалось: размер менялся только когда предмет подносили на
# 10-20 см, то есть когда он занимал почти весь кадр и соседей рядом не
# оставалось.
#
# Здесь размер меряется тем же, чем ведётся слежение, — совпадением с
# эталоном. Эталон примеряется в трёх масштабах, и побеждает тот, что
# совпадает лучше. Сегментация не нужна вовсе, а загромождение не мешает:
# эталон и так умеет отличать цель от фона, иначе слежение бы не работало.
#
# Цена замерена: одно сравнение с эталоном 58x58 стоит на малине 5.6 мс, два
# лишних масштаба раз в 4 кадра дают 2.8 мс на кадр при бюджете 38 мс.
# --- ЭТАЛОН БЕЗ ПРИЗНАКОВ ---
# Разобран случай оператора: чёрная точка на белом фоне, при приближении рамка
# уезжает с цели. Промоделировано пошагово, вот что происходит:
#
#     точка   коробка  эталон   разброс яркости в эталоне
#      18       18     36x36        85.2
#      40       18     36x36        64.4
#      50       18     36x36         6.0
#      62       18     36x36         0.0   <- эталон ЦЕЛИКОМ ВНУТРИ точки
#     120       18     36x36         0.0
#
# Когда предмет вырастает больше эталона, эталон оказывается ВНУТРИ него и
# становится ровным квадратом без единого признака. Совпадать с ним одинаково
# хорошо будет любое ровное место кадра — рамка и уезжает куда угодно.
#
# И это замкнутый круг: примерка масштабов на таком эталоне тоже даёт ровно
# 1.0 (все масштабы одинаково безлики), коробка не растёт, эталон навсегда
# остаётся внутри предмета.
#
# Чёрная точка на белом — не редкий случай, а ХУДШИЙ: у однородного предмета
# нет внутренних признаков вовсе, и держаться можно только за его КРАЙ. Значит
# край обязан попадать в эталон, а это возможно, только если эталон шире
# предмета.
#
# Круг размыкается так: разброс яркости в эталоне уже считается (template_std),
# и если он упал — эталон расширяется, пока край не вернётся в кадр.
TEMPLATE_STARVED_STD = 10.0   # ниже этого эталон считается безликим
TEMPLATE_STARVED_GROW = 1.30  # во столько раз растим коробку за одну проверку
SIZE_BY_SCALE_ENABLED = True
# Доля измеренного изменения масштаба, применяемая за одну проверку. Была
# заодно с SIZE_ADAPT_ALPHA = 0.45 — слишком резко для величины, которая
# ПЕРЕМНОЖАЕТСЯ, а не складывается.
SIZE_SCALE_ALPHA = 0.30
# Примерку масштабов считаем на уменьшенной вдвое копии. Масштаб — величина
# грубая, полное разрешение для неё не нужно, а стоит она вчетверо дешевле.
SIZE_SCALE_DOWNSAMPLE = 2
# С какого размера эталона включать уменьшение. Мелкий эталон уменьшать
# нельзя: он теряет детали и масштаб перестаёт различаться.
SIZE_SCALE_DS_MIN = 64
SIZE_SCALE_STEP = 1.18        # во сколько раз примеряем крупнее и мельче
SIZE_SCALE_MIN_LEAD = 0.012   # насколько сосед должен обойти текущий масштаб
SIZE_ADAPT_ENABLED = True
# ПОСЧИТАНО по заходу 152533 (383 с слежения, оператор водил цель на метр
# туда-обратно, жалоба: «когда цель маленькая, sz вообще не меняется»):
#
#   проверок размера       ~410 (раз в 10 кадров при 26 fps)
#   применено                 7%
#   'измерить не удалось'    63%
#   'score ниже порога'      28%
#
# То есть удачная поправка случалась примерно раз в 14 секунд, а каждая
# двигала коробку лишь на 20% пути. Постоянная времени выходит около 70
# СЕКУНД. Цель за это время успевает приблизиться и удалиться десяток раз —
# коробка физически не может за ней следовать. Жалоба объясняется этим
# полностью, безо всяких догадок про алгоритм.
#
# Правка бьёт по обоим множителям сразу и только по ним:
#   период  10 -> 4 кадра   (цена замерена: 5.5 мс на малине за проверку,
#                            то есть 1.4 мс на кадр при бюджете 38 мс)
#   шаг   0.20 -> 0.45      (при удачной поправке раз в ~2 с это ~4 с
#                            постоянной времени вместо 70)
#
# Порог score НЕ трогаю: это отдельный множитель, и мешать две правки в один
# замер нельзя. Сначала посмотрим, что скажет новая диагностика size_why.
# Период проверки размера. Был 4, то есть шесть раз в секунду. По расчёту
# роста это избыточно: при заходе длиной 20-30 с цель растёт на 3-5% в
# СЕКУНДУ, а различаем мы шаг 18%. Чаще двух раз в секунду спрашивать нечего,
# зато цена платится каждый раз. Замерено: при крупном эталоне примерка
# съедала 9.3 мс на кадр.
SIZE_ADAPT_EVERY_FRAMES = 8          # период проверки
SIZE_ADAPT_MIN_SCORE = 0.55          # минимальный score для доверия размеру
SIZE_ADAPT_ALPHA = 0.45              # доля нового размера в старом (per update)
SIZE_ADAPT_MIN_W = 5                 # нижний предел осмысленного размера
# Был 55 при LOCK_MAX_W = 38, и комментарий гласил «больше LOCK_MAX». После
# подъёма предела коробки до 120 он стал НИЖЕ него и молча превратился в новый
# потолок: измеренный размер крупнее 55 отбрасывался как «вне диапазона» (8
# раз за заход 155721). Держим его выше предела коробки, как и задумывалось.
SIZE_ADAPT_MAX_W = 150 * TRACK_SCALE
# Нижний предел НЕ масштабируется, как и остальные пороги размера: в них
# состоит выигрыш по дальности. Верхний масштабируется обязательно — иначе
# при 640x480 он оказался бы МЕНЬШЕ LOCK_MAX_W, коробка упиралась бы в
# потолок вдвое раньше и переставала расти вслед за целью.

# --- УМНОЕ ВОССТАНОВЛЕНИЕ ПОСЛЕ LOST ---
# Без него после потери цели нужно отщёлкнуть AUX4 и заново лочить. Это
# безопасно, но в реальном бою лишний жест. Если в течение нескольких десятых
# секунды после LOST шаблон находится в расширенной зоне с уверенным скором,
# автоматически возвращаемся в TRACKED.
AUTO_REACQ_ENABLED = True
AUTO_REACQ_FRAMES = 30               # окно поиска после LOST (1 сек при 30 FPS)
AUTO_REACQ_SEARCH_MARGIN = 60        # расширенное окно поиска
AUTO_REACQ_MIN_SCORE = 0.50          # выше обычного MATCH_GOOD_SCORE — нужна высокая уверенность

# --- LAUNCH BOOST (ускорение после захвата) ---
# Когда цель захвачена почти по курсу и pitch-ошибка мала, чистый PID не даст
# квадру значимого разгона — он просто будет висеть, целясь правильно.
# Launch добавляет фиксированное pitch-вниз смещение поверх PID на несколько
# секунд после первого LOCK. PID при этом продолжает работать — курсовая
# коррекция активна, но физика разгоняет квад вперёд за счёт постоянного
# наклона носа. После RAMP_DOWN всё возвращается в обычное наведение.
# КАК ЭТО РАБОТАЕТ И ПОЧЕМУ ИМЕННО ТАК.
#
# Разгон из виса даёт наклон носа вниз: горизонтальная составляющая тяги и
# есть ускорение вперёд. Значит нужен НАКЛОН НА УГОЛ и удержание этого угла.
#
# Прежняя реализация добавляла постоянное смещение стика (-80 PWM) на 2
# секунды, считая, что это задаёт угол. Но квад летит в ACRO, где стик задаёт
# УГЛОВУЮ СКОРОСТЬ, а не угол. Постоянное смещение = непрерывное вращение:
# по логам борта суммарно выходило -150 от центра, удерживаемых 2 с, то есть
# сотни градусов вращения. Квад проворачивался за вертикаль, трекер терял
# цель, аппарат расшатывало — ровно то, что наблюдалось в полёте.
#
# Здесь launch задаёт ЦЕЛЕВОЙ УГОЛ и замыкает по нему контур через реальный
# тангаж из MSP_ATTITUDE: пока угол не достигнут — команда на вращение есть,
# угол достигнут — команда уходит в ноль, и квад ДЕРЖИТ наклон, а не крутится
# дальше. Это маленький угловой контур поверх acro; прицельный PID при этом
# продолжает работать как раньше.
LAUNCH_ENABLED = True
# Целевой наклон носом вниз на разгоне, градусы. 15-25 даёт заметное
# ускорение, оставаясь далеко от опасных углов.
LAUNCH_TARGET_PITCH_DEG = 20.0
# Коэффициент углового контура: PWM на градус ошибки. При 20° ошибки даёт
# 20*8 = 160 PWM — быстрый выход на угол без рывка.
LAUNCH_ANGLE_P = 8.0
# Демпфирование по скорости изменения угла: гасит перелёт через целевой угол.
LAUNCH_ANGLE_D = 2.0
# Потолок вклада углового контура. Ограничивает и скорость выхода на угол.
LAUNCH_MAX_PWM = 180.0
# Если тангаж от FC старше этого, угловой контур молчит: без обратной связи
# он выродился бы в то самое разомкнутое смещение, которое мы и убираем.
LAUNCH_ATT_TIMEOUT = 0.30
# Знак связи «PWM тангажа -> угол, который сообщает FC».
# +1 означает: уменьшение PWM опускает нос, и fc_pitch_deg при этом убывает.
#
# Это ОТДЕЛЬНАЯ константа, а не PITCH_SIGN. PITCH_SIGN описывает связь
# «ошибка в ПИКСЕЛЯХ -> PWM» и потому зависит ещё и от ориентации камеры.
# Здесь ошибка измеряется в ГРАДУСАХ от самого полётника, камера ни при чём.
# Смешать их — значит поймать разгон в обратную сторону при первой же смене
# крепления камеры.
PITCH_PWM_TO_FC_ANGLE_SIGN = +1
# Структура манёвра: 0.5 сек плавного нарастания → 2 сек полной тяги → 1 сек спада.
# В кадрах при 30 FPS:
LAUNCH_RAMP_UP_FRAMES = 15
LAUNCH_HOLD_FRAMES = 60
LAUNCH_RAMP_DOWN_FRAMES = 30
# Дополнительный газ во время launch (в % от текущего стика). Применяется
# ТОЛЬКО если OVERRIDE_THROTTLE=True; иначе газ остаётся под управлением пилота.
# При наклоне носа квад на низком газе трейдит высоту на скорость
# (дайвит и разгоняется), что для камикадзе нормально. Если хочешь сохранять
# высоту во время launch — включай boost.
LAUNCH_THR_BOOST_PCT = 10.0

# --- CRUISE PITCH (постоянная тяга вперёд) ---
# После завершения launch квад теряет тягу вперёд, если aim-ошибка мала
# (компенсация тангажа от FC именно это и обеспечивает: «всё правильно, не
# меняй атaku»). Cruise оставляет небольшой постоянный нос-вниз — квад
# поддерживает крейсерскую скорость.
# По умолчанию ВЫКЛЮЧЕН — включай если после launch квад заметно замедляется.
# Работает в паре с pitch_attitude_compensation: aim-точка сама учитывает
# наклон, лишних корректировок не возникает.
CRUISE_ENABLED = False
# Крейсерский наклон — тоже УГОЛ, а не смещение стика, по той же причине.
CRUISE_TARGET_PITCH_DEG = 8.0

YAW_FILTER_ALPHA = 0.05
YAW_ROLL_CROSSOVER = 25
YAW_ROLL_BLEND_RANGE = 35

# --- ДИНАМИЧЕСКИЙ ГАЗ (работает только если OVERRIDE_THROTTLE=True) ---
THROTTLE_MIN_PWM = 1000
THROTTLE_MAX_PWM = 2000
THROTTLE_PERCENT = 15.0          # макс отклонение от живого стика, %
THROTTLE_DEADBAND = 4
THROTTLE_OUT_ALPHA = 0.25

DY_THROTTLE_GAIN = 1.0
DY_THROTTLE_D_GAIN = 2.0
DY_INTEGRAL_RATE = 0.04
DY_INTEGRAL_MAX = 60.0
DY_INTEGRAL_DECAY = 0.985

# --- ОЦЕНКА СБЛИЖЕНИЯ (пока только измерения, в управление НЕ подаётся) ---
# Одна камера даёт направление на цель, но не дальность — поэтому «перелёт/
# недолёт» сейчас нечем измерить. Две величины ниже это закрывают, и обе
# считаются из того, что уже есть на борту.
#
# 1. ВРЕМЯ ДО КОНТАКТА из скорости роста коробки:
#       tau = размер / (скорость роста размера)
#    Реальный размер цели знать НЕ нужно — он сокращается в отношении.
#
# 2. ДАЛЬНОСТЬ по наземной цели из высоты и угла визирования:
#       дальность = высота / tg(угол снижения)
#    Точность растёт при сближении, то есть там, где она и нужна.
RANGE_ESTIMATE_ENABLED = True
# Показывать дальность и время до контакта текстом у рамки цели. Только
# показ: в управление эти величины по-прежнему не подаются.
RANGE_READOUT_ENABLED = True
# --- ПУТЕВАЯ СКОРОСТЬ ПО БЕГУ ЗЕМЛИ (работает без GPS) ---
# Точка на земле уходит назад тем быстрее, чем быстрее летим и чем ниже. Зная
# высоту и угол, под которым точка видна, получаем дальность до неё, а из неё
# и скорость. Нужно затем, что закон точки прицеливания зависит от скорости.
GROUND_SPEED_ENABLED = True
GROUND_BAND_TOP = 0.72        # с какой доли кадра начинается полоса земли
GROUND_MIN_POINTS = 6
GROUND_MAX_POINTS = 40
GROUND_MIN_DEPRESSION_DEG = 8.0   # ближе к горизонту дальность до земли врёт
GROUND_SPEED_ALPHA = 0.20
# Вертикальный угол обзора IMX219 в этом режиме, градусы.
CAMERA_VFOV_DEG = 41.4
# Наклон камеры на раме, градусы (вверх положительный). 0 = смотрит вперёд.
# Наклон камеры ВВЕРХ относительно рамы, градусы. Не ноль на реальном борту:
# камеру почти никогда не ставят строго по оси.
#
# ЗАМЕРЕНО оператором и подтверждено логом 144450. Дрон стоял на столе —
# тангаж -0.6°, то есть FC откалиброван верно. Затем оператор навёл его на
# цель, стоящую напротив, и в 620 кадрах с целью В ЦЕНТРЕ кадра тангаж
# держался +4.1°. То есть чтобы поставить цель, находящуюся НА ОДНОМ УРОВНЕ,
# в центр кадра, нос приходится опускать на 4.1° — ровно на столько камера
# смотрит выше оси.
#
# Оператор увидел на экране +6: там усреднялись все кадры, а цель в среднем
# была на 13 px ниже центра, что добавляет ещё 1.1°. Чистая цифра — 4.1°.
#
# КАК ОТКАЛИБРОВАТЬ ТОЧНО (пять минут, без полёта):
#   1. Поставить дрон на ровный стол, не держать в руках.
#   2. Поставить предмет ровно на высоте объектива, в нескольких метрах.
#   3. Захватить его и подвести рамку в центр кадра.
#   4. Что покажет строка dep — то и есть наклон камеры. Вписать сюда.
# После этого при взгляде по горизонту dep обязан показывать около нуля.
#
# ИЗМЕРЕНО ОПЕРАТОРОМ по этой процедуре: дрон на столе, цель напротив —
# цель оказывается НИЖЕ прицела, значит камера смотрит вверх. Наклон дрона
# вперёд до совмещения прицела с целью даёт dep +6.8...7.0°. Это и есть
# наклон камеры вверх относительно рамы.
#
# Прежняя прикидка с рук давала 4.1° — она была занижена, потому что дрон
# держали в руках и цель не была строго на высоте объектива. Замер со стола
# точнее, берём его.
#
# ЧУВСТВИТЕЛЬНОСТЬ: разница высот цели и объектива входит в замер целиком.
# 10 см на 3 м — это 1.9°. Чем дальше цель при калибровке, тем точнее число:
# те же 10 см на 10 м дают уже 0.6°. Если захочется уточнить — повторить
# процедуру на большем расстоянии.
CAMERA_TILT_DEG = 6.9
# Ниже этого угла снижения дальность не считаем: tg около нуля, и оценка
# улетает в бесконечность от любого шума.
RANGE_MIN_DEPRESSION_DEG = 4.0
# Годность высоты для дальности. ЗАМЕРЕНО на неподвижном столе: сигма
# барометра 10.1 см, показания гуляли от -2 до 40 см, а тангаж при этом стоял
# как вкопанный (сигма 0.04°). То есть слабое звено — высота, а не угол.
# Прежний порог 30 см был всего тремя сигмами: шум его переходил, и на экране
# появлялись уверенные «3.6 м», собранные из дрожания датчика.
RANGE_ALT_SIGMAS = 5.0          # ~20% по дальности, т.к. dR/R = dH/H
RANGE_MIN_ALT_FLOOR_M = 0.5     # ниже этого дальность не считаем никогда
ALT_NOISE_WINDOW = 40           # отсчётов высотомера для оценки шума
ALT_NOISE_MIN_SAMPLES = 12
# Сглаживание скорости роста коробки: размер шумит, а мы его дифференцируем.
TAU_GROWTH_ALPHA = 0.10
# Ниже этой относительной скорости роста считаем, что сближения нет.
TAU_MIN_GROWTH = 0.002

# --- КАСКАДНЫЙ ГАЗ ПО ВАРИОМЕТРУ ---
# Между ручкой газа и тем, что регулятор измеряет, стоит цепочка:
#   газ -> тяга -> вертикальное ускорение -> скорость -> высота -> угол на
#   цель -> пиксель
# Это три-четыре интегрирования. Один ПИД по пикселям такую цепочку устойчиво
# не удержит — не хватает запаса по фазе, отсюда перелёт и раскачка. Свойство
# структуры, а не следствие плохих коэффициентов.
#
# Каскад разрывает цепочку пополам:
#   внешний контур: ошибка в кадре  -> ЖЕЛАЕМАЯ вертикальная скорость
#   внутренний:     вариометр от FC -> газ
# Каждый контур управляет объектом на одно интегрирование вместо четырёх, а
# демпфирование берётся с вариометра — сигнала намного более гладкого, чем
# производная пиксельной ошибки, которую сейчас усиливает D.
#
# ВЫКЛЮЧЕН ПО УМОЛЧАНИЮ: коэффициенты ниже — обоснованные прикидки, а не
# измеренные значения. Как барометр ведёт себя на пикировании этого аппарата,
# мы ещё не видели.
THROTTLE_CASCADE_ENABLED = False
# Внешний контур: см/с желаемой вертикальной скорости на пиксель ошибки.
CASCADE_OUTER_GAIN = 1.0
# Потолок желаемой вертикальной скорости, см/с — ограничивает агрессивность
# всего канала.
CASCADE_MAX_CLIMB_CMS = 300.0
# Внутренний контур: PWM на 1 см/с ошибки вертикальной скорости.
CASCADE_INNER_P = 0.5
CASCADE_INNER_I = 0.02
CASCADE_INNER_I_MAX = 80.0
# Вариометр старше этого — каскад отключается на лету, канал возвращается к
# прежнему закону. Без обратной связи каскад бессмыслен.
CASCADE_VARIO_TIMEOUT = 0.40

# --- ПРИВЯЗКА КОНТУРА КО ВРЕМЕНИ ---
# Вся математика управления исторически считалась «за кадр»: D — разница
# между соседними кадрами, I — накопление за кадр, упреждение — в пикселях
# за кадр. Но частота кадров плавает: камере разрешено 30-60 к/с, и реальный
# темп зависит от выдержки, то есть от освещённости. По логам борта разброс
# составил 1.1-60.5 к/с при медиане 47.9.
#
# Из-за этого тюнинг менялся сам собой: при 60 к/с относительно 30 к/с D
# слабее вдвое, I набегает вдвое быстрее, горизонт упреждения вдвое короче,
# постоянные времени фильтров вдвое меньше. Один и тот же коэффициент днём и
# вечером давал разное поведение.
#
# Ниже всё пересчитывается к НОМИНАЛЬНОМУ кадру. Смысл коэффициентов не
# меняется: при 30 к/с формулы дают в точности прежние числа (это закреплено
# тестом), а при других частотах поведение остаётся тем же по времени.
NOMINAL_FPS = 30.0
NOMINAL_DT = 1.0 / NOMINAL_FPS
# Границы на случай выбросов: подвисший кадр не должен разово провернуть
# интегратор на несколько секунд вперёд, а слишком мелкий dt — взорвать D.
DT_MIN = 1.0 / 120.0
DT_MAX = 0.25


def dt_ratio(dt):
    """Длительность кадра в единицах номинального кадра (1.0 при 30 к/с)."""
    if dt is None or dt <= 0.0:
        return 1.0
    return max(DT_MIN, min(DT_MAX, float(dt))) / NOMINAL_DT


def alpha_for_dt(alpha, k):
    """Пересчёт коэффициента сглаживания под фактическую длительность кадра.

    Фильтр вида x += alpha*(new-x) за k номинальных кадров сходится как
    1-(1-alpha)^k — это и есть эквивалентный однокадровый коэффициент.
    """
    if k == 1.0:
        return alpha
    return 1.0 - (1.0 - alpha) ** k


# --- ОТЛАДКА ---
MOTOR_DEBUG_ENABLED = True
MOTOR_DEBUG_PERIOD = 0.10
DEBUG_PERIOD = 0.50

# --- ПОЛЁТНОЕ ЛОГИРОВАНИЕ (аналитика донаведения) ---
# Пишет по строке на кадр в CSV + журнал событий + итоговый разбор.
# Цель: по логу однозначно ответить «шёл ли дрон в цель, и если нет — где
# порвалась цепочка»: видим цель -> считаем ошибку -> PID -> отдали в FC ->
# аппарат отработал -> ошибка падает и цель растёт.
#
# Zero 2W слабый, поэтому в камерном колбэке НЕ делается ни форматирования,
# ни записи на диск: там только сборка кортежа чисел (единицы микросекунд).
# Форматирование, запись и аналитика живут в фоновом потоке.
FLIGHT_LOG_ENABLED = True
FLIGHT_LOG_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "flight_logs")
FLIGHT_LOG_FLUSH_PERIOD = 1.0     # с, как часто фоновый поток сбрасывает на диск
FLIGHT_LOG_VERDICT_PERIOD = 2.0   # с, как часто писать промежуточный вердикт
FLIGHT_LOG_MAX_ROWS = 20000       # предохранитель очереди, если диск не успевает
# Окно (кадров) для оценки трендов: сходится ли ошибка, растёт ли цель.
FLIGHT_LOG_TREND_WINDOW = 45
# Дописывать ли данные на физический носитель (fsync), а не только отдавать
# ОС. Дрон часто заканчивает полёт обрывом питания, и всё, что осталось в
# кэше ОС, пропадает — а это последние секунды, ровно те, ради которых лог и
# ведётся. Ценой является лишняя нагрузка на SD-карту раз в секунду.
FLIGHT_LOG_FSYNC = True

# =========================================================
# 3b. ПОЛЁТНОЕ ЛОГИРОВАНИЕ / АНАЛИТИКА ДОНАВЕДЕНИЯ
# =========================================================
# Что именно нужно, чтобы понять «летит ли дрон в цель»: наведение — это
# цепочка, и обрыв на любом звене выглядит снаружи одинаково («не наводится»).
# Поэтому логируется КАЖДОЕ звено, чтобы виновника было видно, а не угадывать:
#
#   1. ВИЖУ      state / match_score / flow_ok / lost_frames  — есть ли захват
#   2. СЧИТАЮ    dx_raw,dy_raw + comp + lead -> dx_aim,dy_aim — из чего ошибка
#   3. РЕШАЮ     P/D/I/FF по осям + флаги насыщения           — что выдал PID
#   4. ОТДАЮ     cmd_* и реально ушедшие sent_*               — дошло ли до FC
#   5. ОТРАБОТАЛ fc_roll/pitch/yaw + моторы                   — послушался ли
#   6. СХОЖУСЬ   ошибка падает? box_frac растёт?              — идём ли в цель
#
# Пункт 2 разложен на слагаемые не случайно: если comp/lead окажутся больше
# самой ошибки, прицел уводит не цель, а собственные поправки — по одной лишь
# итоговой dy_aim этого не увидеть.

_FLIGHT_LOG_COLUMNS = (
    "t,frame,fps,state,controllable,aux4,override,launch_phase,launch_int,"
    "match_score,flow_ok,lost_frames,reacq,"
    "box_cx,box_cy,box_w,box_h,box_frac,"
    "dx_raw,dy_raw,pitch_comp_px,lead_x,lead_y,dx_aim,dy_aim,adx,ady,dy_alt,"
    "tgt_vx,tgt_vy,stable_frames,in_terminal,"
    "roll_p,roll_d,roll_i,roll_ff,roll_off,roll_sat,"
    "pitch_p,pitch_d,pitch_i,pitch_ff,pitch_off,pitch_sat,"
    "launch_pwm,cruise_pwm,pitch_comb,"
    "yaw_filt,yaw_weight,yaw_pd,yaw_ff,yaw_i,yaw_off,yaw_sat,"
    "base_thr,thr_adjust,thr_i,rc_fresh,"
    "cmd_roll,cmd_pitch,cmd_yaw,cmd_thr,"
    "sent_r,sent_p,sent_t,sent_y,"
    "fc_roll,fc_pitch,fc_yaw,att_age_ms,"
    "m1,m2,m3,m4,rc_r,rc_p,rc_y,rc_t,dt_ms,cb_ms,armed,"
    "launch_target_deg,launch_reached,k,match_psr,match_second,search_margin,"
    "match_flow_gap,size_est,size_skip,size_why,size_R,size_scale,motion_sep,motion_on,"
    "color_on,color_pen,color_best,chroma_sat,"
    "alt_cm,vario_cms,alt_age_ms,"
    "box_size_px,box_growth,tau_s,range_m,depression_deg,dy_alt_decoupled,"
    "alt_sigma_cm,range_min_alt_m,"
    "gyro_x,gyro_y,gyro_z,acc_z,"
    "gps_fix,gps_sats,gps_lat,gps_lon,gps_speed_ms,gps_course,"
    "gps_range_m,ground_speed_ms"
)

# Снимок внутренностей управления за текущий кадр. Заполняется в
# update_control_from_target()/fast_idle_update(), читается один раз в
# camera_callback. Обычный dict: ~3 мкс на кадр, на фоне 33 мс кадра — ничто.
_ctl_dbg = {}
# Слагаемые PID по осям, складывает _pid_axis_step.
_pid_dbg = {}
# Внутренности сопоставления шаблона за текущий кадр. Нужны, чтобы понять
# ПОЧЕМУ матч встал именно сюда, а не просто насколько он уверенный.
_match_dbg = {}


class FlightLogger:
    """CSV по кадрам + журнал событий + разбор.

    Раскладка по потокам продиктована Zero 2W: камерный колбэк только кладёт
    готовый кортеж в очередь (без форматирования и без диска), а фоновый поток
    форматирует, пишет и считает тренды. Иначе запись на SD-карту встанет
    прямо в тракте обработки кадра и просадит FPS — то есть логирование
    испортило бы ровно то, что измеряет.
    """

    def __init__(self, directory):
        self.dir = directory
        self.enabled = False
        self._rows = []
        self._events = []
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._thread = None
        self._csv = None
        self._evt = None
        self._written = 0
        self._dropped = 0
        self._session = None
        # Хвост для трендов; сюда кладём только то, что нужно для вердикта.
        self._trend = []
        self._prev_armed = None
        self._flight_index = 0
        self._drain_error_reported = False
        self._next_verdict = 0.0
        self._t0 = time.monotonic()
        # Агрегаты для разбора. Сбрасываются на каждом ARM, чтобы разбор
        # относился к одному вылету, а не к сумме всех за сессию.
        self._reset_agg()

    def _reset_agg(self):
        self._agg = {
            "frames": 0, "tracked": 0, "override": 0,
            "roll_sat": 0, "pitch_sat": 0, "yaw_sat": 0,
            "comp_dominant": 0, "att_stale": 0,
            "tau_seen": 0, "tau_sum": 0.0, "range_seen": 0, "range_sum": 0.0,
            "alt_seen": 0, "vario_min": None, "vario_max": None,
            "sum_abs_dx": 0.0, "sum_abs_dy": 0.0,
            "first_frac": None, "last_frac": None,
            "best_frac": 0.0, "states": {},
        }
        self._trend = []

    # ---------- жизненный цикл ----------
    def start(self):
        if not FLIGHT_LOG_ENABLED:
            return
        try:
            os.makedirs(self.dir, exist_ok=True)
            self._session = time.strftime("%Y%m%d_%H%M%S")
            base = os.path.join(self.dir, "flight_" + self._session)
            self._csv = open(base + ".csv", "w", buffering=1 << 16)
            self._csv.write(_FLIGHT_LOG_COLUMNS + "\n")
            self._evt = open(base + ".events.log", "w", buffering=1 << 14)
            self.enabled = True
            self.event("session start pid=%d" % os.getpid())
            # Штамп версии — вспомогательный, и он НЕ должен иметь права
            # отключить логирование: снаружи это выглядело бы как «логи не
            # пишутся» без всякой связи с настоящей причиной.
            try:
                version = _code_version()
                self.event("ВЕРСИЯ КОДА %s" % version)
                # Дублируем в stdout: службу смотрят через journalctl, и там
                # версия должна быть видна сразу, без раскопок в файлах.
                print("[tracker] ВЕРСИЯ КОДА %s" % version, flush=True)
            except Exception:
                self.event("ВЕРСИЯ КОДА не определена")
            # Снимок настроек — тоже вспомогательный. Любая опечатка в имени
            # константы здесь не должна оставлять вылет вообще без логов.
            try:
                self._log_config()
            except Exception:
                self.event("снимок настроек не записан")
            self._thread = threading.Thread(target=self._writer, daemon=True)
            self._thread.start()
        except Exception as exc:
            # Логирование не имеет права уронить полёт.
            self.enabled = False
            try:
                print("[flightlog] disabled: %s" % exc, flush=True)
            except Exception:
                pass

    def _log_config(self):
        """Снимок настроек: без него цифры из CSV нечем объяснить через месяц."""
        self.event("CONFIG override R=%s P=%s Y=%s T=%s | signs roll=%+d pitch=%+d yaw=%+d"
                   % (OVERRIDE_ROLL, OVERRIDE_PITCH, OVERRIDE_YAW, OVERRIDE_THROTTLE,
                      ROLL_SIGN, PITCH_SIGN, YAW_SIGN))
        self.event("CONFIG deflect roll=%d pitch=%d yaw=%d | gains P r=%.2f p=%.2f y=%.2f"
                   % (MAX_ROLL_DEFLECT, MAX_PITCH_DEFLECT, MAX_YAW_DEFLECT,
                      P_GAIN_ROLL, P_GAIN_PITCH, P_GAIN_YAW))
        self.event("CONFIG pitch_comp=%s px_per_deg=%.2f max_comp=%.0f | lead=%s frames=%d"
                   % (PITCH_ATTITUDE_COMP_ENABLED, PIXELS_PER_PITCH_DEG,
                      MAX_PITCH_COMP_PX, LEAD_AIM_ENABLED, LEAD_FRAMES))
        self.event("CONFIG launch=%s target=%.0fdeg P=%.1f D=%.1f max=%.0f "
                   "thr_boost=%.1f%% | cruise=%s target=%.0fdeg"
                   % (LAUNCH_ENABLED, LAUNCH_TARGET_PITCH_DEG, LAUNCH_ANGLE_P,
                      LAUNCH_ANGLE_D, LAUNCH_MAX_PWM, LAUNCH_THR_BOOST_PCT,
                      CRUISE_ENABLED, CRUISE_TARGET_PITCH_DEG))
        self.event("CONFIG camera %dx%d rot180=%s | center=(%d,%d)"
                   % (MAIN_W, MAIN_H, CAMERA_ROTATE_180, CENTER_X, CENTER_Y))

    def stop(self):
        if not self.enabled:
            return
        self._stop.set()
        try:
            if self._thread is not None:
                self._thread.join(timeout=2.0)
        except Exception:
            pass
        try:
            self._drain()
            if self._prev_armed:
                # Программу остановили, не дизармившись (или сняли питание в
                # воздухе) — разбора этого вылета ещё нет, дописываем.
                self._write_summary(tag="flight%d" % max(self._flight_index, 1))
            elif self._flight_index == 0:
                # Армирование ни разу не наблюдалось (нет связи с FC или
                # наземный прогон) — тогда полезен разбор всей сессии.
                self._write_summary()
        except Exception:
            pass
        for f in (self._csv, self._evt):
            try:
                if f is not None:
                    f.close()
            except Exception:
                pass
        self.enabled = False

    # ---------- горячий путь ----------
    def row(self, values):
        """Вызывается из камерного колбэка. Никакого I/O и форматирования."""
        if not self.enabled:
            return
        # Под замком: _drain() подменяет список целиком, и без замка строка,
        # добавленная ровно в момент подмены, потерялась бы. Захват незанятого
        # замка стоит доли микросекунды — на 30 кадрах/с это ничто.
        with self._lock:
            if len(self._rows) >= FLIGHT_LOG_MAX_ROWS:
                # Лучше потерять строки, чем расти в памяти на Zero 2W.
                self._dropped += 1
                return
            self._rows.append(values)

    def event(self, text):
        if not FLIGHT_LOG_ENABLED:
            return
        try:
            with self._lock:
                self._events.append(
                    "%8.3f  %s" % (time.monotonic() - self._t0, text))
        except Exception:
            pass

    # ---------- фоновый поток ----------
    def _writer(self):
        while not self._stop.is_set():
            self._stop.wait(FLIGHT_LOG_FLUSH_PERIOD)
            try:
                self._drain()
            except Exception:
                # Пишем ОДИН раз: молча глохнущий логгер выглядит как «лог
                # пустой» и съедает вылет, пока причина не найдена.
                if not self._drain_error_reported:
                    self._drain_error_reported = True
                    try:
                        import traceback
                        traceback.print_exc()
                        print("[flightlog] writer failed; log incomplete",
                              flush=True)
                    except Exception:
                        pass

    def _drain(self):
        with self._lock:
            rows, self._rows = self._rows, []
        out = []
        for r in rows:
            out.append(",".join(_fmt(v) for v in r))
            # Может добавить события (ARMED/DISARMED), поэтому события
            # забираем ПОСЛЕ разбора строк — иначе на последнем сбросе перед
            # выходом отметка о дизарме потерялась бы.
            self._accumulate(r)
        with self._lock:
            events, self._events = self._events, []
        if events and self._evt is not None:
            self._evt.write("\n".join(events) + "\n")
            self._evt.flush()
        if not rows:
            return
        self._csv.write("\n".join(out) + "\n")
        # Без flush строки лежат в 64-КБ буфере и теряются при обрыве питания —
        # то есть терялся бы именно хвост перед падением.
        self._csv.flush()
        if FLIGHT_LOG_FSYNC:
            try:
                os.fsync(self._csv.fileno())
                os.fsync(self._evt.fileno())
            except Exception:
                pass
        self._written += len(rows)
        now = time.monotonic()
        if now >= self._next_verdict:
            self._next_verdict = now + FLIGHT_LOG_VERDICT_PERIOD
            try:
                self._verdict()
            except Exception:
                pass

    # ---------- аналитика ----------
    def _accumulate(self, r):
        a = self._agg
        # Разбор вылета пишется по ДИЗАРМУ, а не только на выходе из
        # программы: питание с дрона обычно снимают позже (или вообще
        # дёргают), и ждать штатного завершения — значит часто не получить
        # разбор вовсе. Переход ловим здесь, в потоке записи, чтобы он был
        # согласован с потоком строк и не требовал ещё одной блокировки.
        armed = r[_C_ARMED]
        if armed is not None and armed != self._prev_armed:
            prev = self._prev_armed
            self._prev_armed = armed
            if armed:
                self._flight_index += 1
                self.event("ARMED -> вылет #%d, счётчики разбора сброшены"
                           % self._flight_index)
                self._reset_agg()
            elif prev is not None:
                self.event("DISARMED -> разбор вылета #%d записан"
                           % self._flight_index)
                try:
                    self._write_summary(tag="flight%d" % self._flight_index)
                except Exception:
                    pass

        # Считаем кадр ПОСЛЕ разбора перехода: иначе кадр, на котором пришёл
        # дизарм, попадал бы в статистику только что завершённого вылета.
        a = self._agg
        a["frames"] += 1
        st = r[_C_STATE]
        a["states"][st] = a["states"].get(st, 0) + 1
        if r[_C_OVERRIDE]:
            a["override"] += 1

        if st != "TRACKED":
            return
        a["tracked"] += 1
        a["sum_abs_dx"] += abs(r[_C_DX_AIM] or 0.0)
        a["sum_abs_dy"] += abs(r[_C_DY_AIM] or 0.0)
        if r[_C_ROLL_SAT]:
            a["roll_sat"] += 1
        if r[_C_PITCH_SAT]:
            a["pitch_sat"] += 1
        if r[_C_YAW_SAT]:
            a["yaw_sat"] += 1
        # Поправка перевешивает саму ошибку — прицел ведут не по цели.
        if abs(r[_C_COMP] or 0.0) > max(8.0, abs(r[_C_DY_RAW] or 0.0)):
            a["comp_dominant"] += 1
        if (r[_C_ATT_AGE] or 0.0) > 300.0:
            a["att_stale"] += 1
        # Новые измерения: копим, чтобы в разборе было видно, годятся ли они.
        if r[_C_TAU] is not None and r[_C_TAU] != "":
            a["tau_seen"] += 1
            a["tau_sum"] += float(r[_C_TAU])
        if r[_C_RANGE] is not None and r[_C_RANGE] != "":
            a["range_seen"] += 1
            a["range_sum"] += float(r[_C_RANGE])
        v = r[_C_VARIO]
        if v is not None and v != "":
            a["alt_seen"] += 1
            v = float(v)
            a["vario_min"] = v if a["vario_min"] is None else min(a["vario_min"], v)
            a["vario_max"] = v if a["vario_max"] is None else max(a["vario_max"], v)

        frac = r[_C_BOX_FRAC] or 0.0
        if a["first_frac"] is None:
            a["first_frac"] = frac
        a["last_frac"] = frac
        if frac > a["best_frac"]:
            a["best_frac"] = frac
        t = self._trend
        t.append((r[_C_DX_AIM] or 0.0, r[_C_DY_AIM] or 0.0, frac))
        if len(t) > FLIGHT_LOG_TREND_WINDOW:
            del t[:-FLIGHT_LOG_TREND_WINDOW]

    def _verdict(self):
        """Промежуточный ответ на вопрос «идём ли в цель» + почему нет."""
        t = self._trend
        if len(t) < 10:
            return
        half = len(t) // 2
        err0 = sum(abs(x) + abs(y) for x, y, _ in t[:half]) / half
        err1 = sum(abs(x) + abs(y) for x, y, _ in t[half:]) / (len(t) - half)
        frac0 = sum(f for _, _, f in t[:half]) / half
        frac1 = sum(f for _, _, f in t[half:]) / (len(t) - half)
        closing = frac1 > frac0 * 1.02
        converging = err1 < err0 * 0.95
        a = self._agg
        n = max(a["tracked"], 1)
        why = []
        if a["pitch_sat"] * 4 > n:
            why.append("pitch saturated %d%%" % (100 * a["pitch_sat"] // n))
        if a["roll_sat"] * 4 > n:
            why.append("roll saturated %d%%" % (100 * a["roll_sat"] // n))
        if a["comp_dominant"] * 4 > n:
            why.append("pitch-comp outweighs real error %d%%"
                       % (100 * a["comp_dominant"] // n))
        if a["att_stale"] * 4 > n:
            why.append("MSP attitude stale %d%%" % (100 * a["att_stale"] // n))
        if not a["override"]:
            why.append("override never active")
        verdict = "CLOSING" if (closing and converging) else (
            "closing-not-aiming" if closing else (
                "aiming-not-closing" if converging else "NOT CONVERGING"))
        self.event("VERDICT %s | aim_err %.1f->%.1f px | box %.4f->%.4f%s"
                   % (verdict, err0, err1, frac0, frac1,
                      (" | " + "; ".join(why)) if why else ""))

    def _write_summary(self, tag=None):
        a = self._agg
        if not a["frames"]:
            return
        n = max(a["tracked"], 1)
        name = "flight_%s.summary.txt" % self._session if tag is None \
            else "flight_%s.%s.summary.txt" % (self._session, tag)
        path = os.path.join(self.dir, name)
        with open(path, "w") as f:
            f.write("frames=%d  tracked=%d  override=%d  dropped=%d\n"
                    % (a["frames"], a["tracked"], a["override"], self._dropped))
            f.write("states: %s\n" % ", ".join(
                "%s=%d" % kv for kv in sorted(a["states"].items())))
            if a["tracked"]:
                f.write("mean|dx_aim|=%.1f px  mean|dy_aim|=%.1f px\n"
                        % (a["sum_abs_dx"] / n, a["sum_abs_dy"] / n))
                f.write("box_frac first=%.5f last=%.5f best=%.5f  (растёт = подходим)\n"
                        % (a["first_frac"] or 0.0, a["last_frac"] or 0.0, a["best_frac"]))
                f.write("saturation: roll=%d%% pitch=%d%% yaw=%d%%\n"
                        % (100 * a["roll_sat"] // n, 100 * a["pitch_sat"] // n,
                           100 * a["yaw_sat"] // n))
                f.write("pitch-comp сильнее реальной ошибки: %d%% кадров\n"
                        % (100 * a["comp_dominant"] // n))
                f.write("MSP attitude протухал: %d%% кадров\n"
                        % (100 * a["att_stale"] // n))
                f.write("\n-- оценка сближения (пока не управляет полётом) --\n")
                if a["tau_seen"]:
                    f.write("время до контакта: оценено на %d%% кадров, "
                            "среднее %.1f с\n"
                            % (100 * a["tau_seen"] // n,
                               a["tau_sum"] / a["tau_seen"]))
                else:
                    f.write("время до контакта: НЕ оценено ни разу "
                            "(коробка не росла = сближения не было)\n")
                if a["alt_seen"]:
                    f.write("высотомер: данные есть, вертикальная скорость "
                            "от %.0f до %.0f см/с\n"
                            % (a["vario_min"], a["vario_max"]))
                    if a["range_seen"]:
                        f.write("дальность: оценена на %d%% кадров, "
                                "средняя %.0f м\n"
                                % (100 * a["range_seen"] // n,
                                   a["range_sum"] / a["range_seen"]))
                    else:
                        f.write("дальность: НЕ оценена (угол снижения меньше "
                                "порога либо высота слишком мала)\n")
                else:
                    f.write("высотомер: данных НЕТ — барометра нет или "
                            "выключен\n")
        try:
            print("[flightlog] %d rows -> %s" % (self._written, self.dir), flush=True)
        except Exception:
            pass


def _code_version():
    """Какой именно код сейчас в воздухе.

    Без этого после `git pull` невозможно доказать, что служба перезапущена и
    летит новая версия, а не та, что была загружена в память час назад. Берём
    три независимых признака:
      * коммит — что лежит в репозитории;
      * пометка "изменён" — правили ли файл поверх коммита;
      * md5 самого файла — единственное, что нельзя подделать перезаписью
        репозитория: он считается по тому файлу, который реально запущен.
    """
    try:
        me = os.path.abspath(__file__)
    except NameError:
        return "версия неизвестна (нет __file__)"
    here = os.path.dirname(me)
    commit, dirty, branch = "нет-git", "", "?"
    try:
        commit = subprocess.check_output(
            ["git", "-C", here, "rev-parse", "--short", "HEAD"],
            stderr=subprocess.DEVNULL, timeout=5).decode().strip()
        # Ветка в лог: по хешу её каждый раз приходилось искать вручную, а
        # ветка — это и есть то, что оператор держит в голове во время прогона.
        branch = subprocess.check_output(
            ["git", "-C", here, "rev-parse", "--abbrev-ref", "HEAD"],
            stderr=subprocess.DEVNULL, timeout=5).decode().strip() or "?"
        changed = subprocess.check_output(
            ["git", "-C", here, "status", "--porcelain", "--", __file__],
            stderr=subprocess.DEVNULL, timeout=5).decode().strip()
        dirty = " ИЗМЕНЁН-ПОВЕРХ-КОММИТА" if changed else ""
    except Exception:
        pass
    digest = "?"
    try:
        with open(me, "rb") as f:
            digest = hashlib.md5(f.read()).hexdigest()[:12]
    except Exception:
        pass
    return "ветка=%s commit=%s%s md5=%s file=%s" % (
        branch, commit, dirty, digest, me)


def _fmt(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "1" if v else "0"
    if isinstance(v, float):
        return "%.3f" % v
    return str(v)


# Индексы колонок для аналитики вычисляются ИЗ ЗАГОЛОВКА по именам.
#
# Раньше они были записаны числами, и вставка колонки в середину списка
# молча сдвигала часть из них: аналитика начинала читать соседнее поле и
# делать выводы по чужим данным. Ошибка тихая — ничего не падает, просто
# разбор врёт. Теперь такое невозможно по построению.
_COLS = [c.strip() for c in _FLIGHT_LOG_COLUMNS.split(",") if c.strip()]
_C_STATE = _COLS.index("state")
_C_OVERRIDE = _COLS.index("override")
_C_BOX_FRAC = _COLS.index("box_frac")
_C_DY_RAW = _COLS.index("dy_raw")
_C_COMP = _COLS.index("pitch_comp_px")
_C_DX_AIM = _COLS.index("dx_aim")
_C_DY_AIM = _COLS.index("dy_aim")
_C_ROLL_SAT = _COLS.index("roll_sat")
_C_PITCH_SAT = _COLS.index("pitch_sat")
_C_YAW_SAT = _COLS.index("yaw_sat")
_C_ATT_AGE = _COLS.index("att_age_ms")
_C_ARMED = _COLS.index("armed")
_C_VARIO = _COLS.index("vario_cms")
_C_TAU = _COLS.index("tau_s")
_C_RANGE = _COLS.index("range_m")

flight_log = FlightLogger(FLIGHT_LOG_DIR)

class LockLogger:
    """Отдельная папка на КАЖДЫЙ захват.

    Зачем отдельно от общего журнала. Кампания по сбору данных — это сотня
    заходов, и разбирать их надо ПОШТУЧНО: один заход — одна выборка, со своей
    высотой, дистанцией и манерой. В общем файле они слиплись бы, а резать его
    потом по времени — лишний повод ошибиться.

    В папке захвата лежит:
        строки.csv   те же величины, что в общем журнале, но только этот заход
        события.log  что происходило именно здесь
        итог.txt     сводка: сколько длился, чем кончился, что было доступно

    Пишется тем же способом, что и общий журнал: в камерном потоке только
    укладка в очередь, диск — в отдельном потоке.
    """

    def __init__(self, directory):
        self.dir = directory
        self.active = False
        self.n = 0
        self.at_lock = {}
        self._csv = None
        self._evt = None
        self._path = None
        self._t0 = 0.0
        self._rows = 0

    def _snapshot(self):
        """Условия в момент захвата: чем определяется эта выборка."""
        try:
            with state_lock:
                d = {
                    "высота_см": app_state.get("alt_cm"),
                    "тангаж": app_state.get("fc_pitch_deg"),
                    "крен": app_state.get("fc_roll_deg"),
                    "широта": app_state.get("gps_lat"),
                    "долгота": app_state.get("gps_lon"),
                    "скорость_GPS_мс": (
                        None if app_state.get("gps_speed_cms") is None
                        else app_state["gps_speed_cms"] / 100.0),
                    "спутников": app_state.get("gps_sats"),
                }
            d["скорость_по_земле_мс"] = ground_speed_mps
            d["дальность_по_высоте_м"] = _ctl_dbg.get("range_m")
            d["угол_снижения"] = _ctl_dbg.get("depression_deg")
            d["время_до_цели_с"] = _ctl_dbg.get("tau_s")
            # Истинная дальность — если известны и наши координаты, и цели.
            d["дальность_GPS_м"] = None
            if (d["широта"] is not None and TARGET_LAT is not None
                    and TARGET_LON is not None):
                try:
                    dlat = math.radians(TARGET_LAT - d["широта"])
                    dlon = math.radians(TARGET_LON - d["долгота"])
                    d["дальность_GPS_м"] = 6371000.0 * math.hypot(
                        dlat, dlon * math.cos(math.radians(d["широта"])))
                except Exception:
                    pass
            return d
        except Exception:
            return {}

    def begin(self, seq):
        if not LOCK_LOG_ENABLED or self.active:
            return
        try:
            # УСЛОВИЯ ЗАХОДА снимаются В МОМЕНТ ЛОКА, а не на взлёте. Каждый
            # лок — отдельная выборка, и «точка старта» для неё это та точка,
            # где оператор указал цель. Она в воздухе, и именно её высота,
            # дальность и угол определяют, к какой связке относится заход.
            self.at_lock = self._snapshot()
            stamp = time.strftime("%Y%m%d_%H%M%S")
            self.n += 1
            self._path = os.path.join(self.dir, LOCK_LOG_DIR,
                                      "%s_zahvat%02d" % (stamp, self.n))
            os.makedirs(self._path, exist_ok=True)
            self._csv = open(os.path.join(self._path, "строки.csv"), "w",
                             buffering=1 << 16)
            self._csv.write(_FLIGHT_LOG_COLUMNS + "\n")
            self._evt = open(os.path.join(self._path, "события.log"), "w",
                             buffering=1 << 12)
            self._t0 = time.monotonic()
            self._rows = 0
            self.active = True
        except Exception as exc:
            self.active = False
            flight_log.event("ПАПКА ЗАХВАТА не создалась: %s" % exc)

    def row(self, line):
        if not self.active:
            return
        try:
            self._csv.write(line + "\n")
            self._rows += 1
        except Exception:
            pass

    def event(self, text):
        if not self.active:
            return
        try:
            self._evt.write("%8.3f  %s\n" % (time.monotonic() - self._t0, text))
        except Exception:
            pass

    def end(self, why=""):
        if not self.active:
            return
        self.active = False
        dur = time.monotonic() - self._t0
        try:
            with state_lock:
                # Признак тот же, что и в снимке условий, иначе итог и
                # снимок противоречили бы.
                gps_fix = _gps_zhivoy(app_state)
                gps_sats = app_state.get("gps_sats")
                imu = app_state.get("imu_seen")
                alt = app_state.get("alt_seen")
            with open(os.path.join(self._path, "итог.txt"), "w",
                      encoding="utf-8") as f:
                f.write("УСЛОВИЯ ЗАХОДА (в момент захвата, не на взлёте)\n")
                for k, v in self.at_lock.items():
                    if v is None:
                        f.write("  %-24s нет\n" % k)
                    elif isinstance(v, float):
                        f.write("  %-24s %.4f\n" % (k, v))
                    else:
                        f.write("  %-24s %s\n" % (k, v))
                f.write("\n")
                f.write("длительность: %.1f с, строк %d\n" % (dur, self._rows))
                f.write("окончен: %s\n" % (why or "не указано"))
                f.write("режим наблюдения: %s\n"
                        % ("ДА, управление не трогали" if OBSERVE_ONLY
                           else "нет — трекер вмешивался в управление"))
                f.write("\nчто было доступно:\n")
                f.write("  высотомер: %s\n" % ("да" if alt else "НЕТ"))
                f.write("  гироскоп:  %s\n" % ("да" if imu else "НЕТ"))
                f.write("  GPS:       %s\n"
                        % ("да, спутников %s" % gps_sats if gps_fix
                           else "НЕТ — разбор пойдёт по высоте и бегу земли"))
                f.write("  код: %s\n" % _code_version())
        except Exception:
            pass
        for h in (self._csv, self._evt):
            try:
                h.close()
            except Exception:
                pass
        self._csv = self._evt = None


lock_log = LockLogger(FLIGHT_LOG_DIR)



