def msp_request(cmd):
    if fc is None:
        return None
    try:
        # Чистим вход. ACK от SET_RAW_RC иначе копятся и парсер ловит их
        # как ответ на MSP_RC (cmd=200 vs ожидаемые 105/108).
        try:
            fc.reset_input_buffer()
        except Exception:
            pass
        packet = b'$M<' + struct.pack('<BBB', 0, cmd, cmd)
        fc.write(packet)

        sync = b''
        for _ in range(64):
            b = fc.read(1)
            if not b:
                return None
            sync += b
            if sync.endswith(b'$M>'):
                break
        else:
            return None

        size_b = fc.read(1)
        cmd_b = fc.read(1)
        if not size_b or not cmd_b:
            return None
        size_ = size_b[0]
        resp_cmd = cmd_b[0]
        data_ = fc.read(size_)
        crc_b = fc.read(1)
        if resp_cmd != cmd or len(data_) != size_ or len(crc_b) != 1:
            return None
        checksum = size_ ^ resp_cmd
        for b in data_:
            checksum ^= b
        if checksum != crc_b[0]:
            return None
        return data_
    except Exception:
        return None


def send_msp_set_raw_rc(channels):
    if fc is None:
        return
    try:
        channels = (list(channels) + [1500] * 8)[:8]
        channels = [max(885, min(2115, int(x))) for x in channels]
        data = struct.pack('<8H', *channels)
        size = len(data)
        cmd = 200  # MSP_SET_RAW_RC
        checksum = size ^ cmd
        for b in data:
            checksum ^= b
        packet = b'$M<' + struct.pack('<BB', size, cmd) + data + struct.pack('<B', checksum)
        fc.write(packet)
    except Exception:
        pass


def build_output_channels(receiver, r_cmd, p_cmd, y_cmd, t_cmd, apply_ov):
    """Собрать 8 каналов для MSP_SET_RAW_RC.

    receiver — значения С ПРИЁМНИКА (внутренний порядок Betaflight RPYT+AUX),
    а не то, что вернул MSP_RC при активном оверрайде.
    apply_ov — трекер сейчас управляет (TRACKED и AUX4 подняты).

    Ось подменяется только если оверрайд применяется И включён её флаг
    OVERRIDE_*; иначе уходит значение приёмника. Возвращает список из 8.
    """
    live_roll  = int(receiver[0]) if len(receiver) > 0 else 1500
    live_pitch = int(receiver[1]) if len(receiver) > 1 else 1500
    live_yaw   = int(receiver[2]) if len(receiver) > 2 else 1500
    live_thr   = int(receiver[3]) if len(receiver) > 3 else 1000

    out_roll  = int(r_cmd) if (apply_ov and OVERRIDE_ROLL)     else live_roll
    out_pitch = int(p_cmd) if (apply_ov and OVERRIDE_PITCH)    else live_pitch
    out_yaw   = int(y_cmd) if (apply_ov and OVERRIDE_YAW)      else live_yaw
    out_thr   = int(t_cmd) if (apply_ov and OVERRIDE_THROTTLE) else live_thr

    # MSP_SET_RAW_RC ждёт rcmap external (default AETR): ch0=R, ch1=P,
    # ch2=T, ch3=Y — порядок отличается от того, в котором пришёл receiver.
    channels = (list(receiver) + [1500] * 8)[:8]
    channels[0] = out_roll
    channels[1] = out_pitch
    channels[2] = out_thr
    channels[3] = out_yaw
    return channels


def fc_io_loop():
    """Read: MSP_RC возвращает RPYT (внутренний порядок Betaflight) →
       ch[0]=Roll, ch[1]=Pitch, ch[2]=Yaw, ch[3]=Throttle.
       Write: MSP_SET_RAW_RC ждёт rcmap-порядок (default AETR) →
       channels[0]=Roll, [1]=Pitch, [2]=Throttle, [3]=Yaw.
    """
    global aux4_state
    next_t = time.monotonic()
    next_motor_t = 0.0
    next_status_t = 0.0
    next_boxids_t = 0.0
    next_alt_t = 0.0
    next_imu_t = 0.0
    next_gps_t = 0.0
    alt_warned = False
    loop_started = time.monotonic()

    while not io_thread_stop.is_set():
        _gps_arm_note = None
        if fc is None:
            time.sleep(0.1)
            continue

        try:
            rc_data = msp_request(105)  # MSP_RC
            if rc_data is not None and len(rc_data) >= 16:
                ch = struct.unpack('<' + 'H' * (len(rc_data) // 2), rc_data)
                if len(ch) >= 8:
                    now_rc = time.monotonic()
                    with state_lock:
                        app_state["rc_channels"] = list(ch[:8])
                        # Признак ЖИВОЙ связи с FC. Обновляется всегда, в том
                        # числе при активном оверрайде. Отделён от возраста
                        # кэша приёмника намеренно: кэш во время оверрайда
                        # законно замирает, и если завязать на него отправку
                        # MSP-кадров, поток прервётся прямо посреди лока —
                        # а Betaflight ждёт его непрерывно.
                        app_state["rc_link_ts"] = now_rc
                        # AUX-каналы в маску оверрайда не входят, поэтому
                        # приходят с приёмника всегда — читать их можно и при
                        # активном оверрайде.
                        aux4_state = ch[7] > 1500
                        fc_ovr = app_state.get("fc_override_on", False)
                        fc_ovr_ts = app_state.get("fc_override_ts", 0.0)
                        # Пока неизвестно, активен ли оверрайд на FC (первые
                        # мгновения после старта или режим не настроен),
                        # считаем данные чистыми: до подъёма AUX4 оверрайд
                        # физически не может быть включён.
                        stale_ovr = (now_rc - fc_ovr_ts) > 1.0
                        if not fc_ovr or stale_ovr:
                            app_state["receiver_channels"] = list(ch[:8])
                            app_state["receiver_ts"] = now_rc
                            app_state["rc_throttle"] = ch[3]
                            app_state["rc_throttle_ts"] = now_rc

            att_data = msp_request(108)  # MSP_ATTITUDE
            if att_data is not None and len(att_data) >= 6:
                roll_t, pitch_t, heading_t = struct.unpack('<3h', att_data[:6])
                with state_lock:
                    app_state["fc_pitch_deg"] = pitch_t / 10.0
                    app_state["fc_pitch_ts"] = time.monotonic()
                    # Крен и курс приходят в том же пакете и ничего не стоят,
                    # а без них не проверить, отработал ли аппарат команду:
                    # «PID просил крен, аппарат не накренился» — это диагноз.
                    app_state["fc_roll_deg"] = roll_t / 10.0
                    app_state["fc_yaw_deg"] = float(heading_t)

            now = time.monotonic()

            # Один раз узнаём, в каких битах живут нужные нам режимы.
            if not _box_bits and now >= next_boxids_t:
                next_boxids_t = now + 2.0
                box_data = msp_request(119)  # MSP_BOXIDS
                if box_data:
                    for pid, name in ((ARM_BOX_PERMANENT_ID, "ARM"),
                                      (MSP_OVERRIDE_BOX_PERMANENT_ID,
                                       "MSP OVERRIDE")):
                        pos = box_data.find(pid)
                        if pos >= 0:
                            _box_bits[pid] = pos
                            flight_log.event(
                                "MSP_BOXIDS: %s в бите %d (боксов %d)"
                                % (name, pos, len(box_data)))
                        else:
                            flight_log.event(
                                "MSP_BOXIDS: %s НЕ НАСТРОЕН на этом FC" % name)

            if _box_bits and now >= next_status_t:
                next_status_t = now + MSP_STATUS_PERIOD
                st_data = msp_request(101)  # MSP_STATUS
                if st_data is not None and len(st_data) >= 10:
                    if not app_state.get("sensors_logged"):
                        app_state["sensors_logged"] = True
                        sensor_mask = struct.unpack_from('<H', st_data, 4)[0]
                        have = [n for b, n in SENSOR_BITS if sensor_mask & (1 << b)]
                        with state_lock:
                            app_state["has_baro"] = bool(sensor_mask & (1 << 1))
                        flight_log.event("ДАТЧИКИ НА ПЛАТЕ: %s"
                                         % (", ".join(have) or "нет данных"))
                        if not (sensor_mask & (1 << 1)):
                            flight_log.event(
                                "БАРОМЕТРА НЕТ -> оценка дальности недоступна, "
                                "останется только время до контакта")
                    mode_flags = struct.unpack_from('<I', st_data, 6)[0]
                    arm_bit = _box_bits.get(ARM_BOX_PERMANENT_ID)
                    ovr_bit = _box_bits.get(MSP_OVERRIDE_BOX_PERMANENT_ID)
                    with state_lock:
                        if arm_bit is not None:
                            _armed_now = bool(mode_flags & (1 << arm_bit))
                            # АРМ ОБНУЛЯЕТ БАРОМЕТР. Замерено по логам: под
                            # армом высота держится около нуля (среднее 2.8,
                            # 2.5, 3.5, -0.4 см в разных заходах), без арма
                            # уползает до +61 и -44 см. То есть Betaflight
                            # заново берёт уровень земли при арме, и в этот
                            # миг показание СКАЧЕТ. Скачок внутри окна оценки
                            # шума дал бы огромную ложную сигму и запретил бы
                            # дальность на десятки кадров — поэтому историю
                            # шума на переходе арма начинаем заново.
                            if _armed_now != app_state.get("armed"):
                                _alt_hist.clear()
                                app_state["alt_sigma_cm"] = None
                                # Состояние GPS именно НА МОМЕНТ АРМА.
                                # Проверка готовности идёт на восьмой секунде,
                                # когда захвата не бывает никогда: спутники
                                # подтягиваются десятками секунд. Без этой
                                # записи в разборе не отличить «GPS не было»
                                # от «не дождались».
                                if _armed_now and (GPS_EXPECTED or
                                                   app_state.get("gps_sats_max")):
                                    _gps_arm_note = (
                                        "GPS НА АРМЕ: %s, спутников %s"
                                        % ("захват есть"
                                           if _gps_zhivoy(app_state)
                                           else "ЗАХВАТА НЕТ",
                                           app_state.get("gps_sats")))
                                else:
                                    _gps_arm_note = None
                            else:
                                _gps_arm_note = None
                            app_state["armed"] = _armed_now
                            app_state["armed_ts"] = now
                        # Активен ли MSP OVERRIDE на самом FC. Знать это
                        # обязательно: пока он активен, MSP_RC отдаёт НАШИ же
                        # присланные значения, а не стики (см. ниже).
                        if ovr_bit is not None:
                            app_state["fc_override_on"] = bool(
                                mode_flags & (1 << ovr_bit))
                            app_state["fc_override_ts"] = now

            if _gps_arm_note:
                flight_log.event(_gps_arm_note)

            if not _gotovnost_done and now - loop_started > STARTUP_CHECK_AFTER_S:
                _startup_sensor_check()
                _gotovnost_k_sboru()

            if (not alt_warned and now - loop_started > 8.0
                    and not app_state.get("alt_seen")):
                alt_warned = True
                flight_log.event(
                    "ВЫСОТОМЕР не отвечает: барометра на плате нет либо он "
                    "не включён. Оценка дальности работать не будет.")

            # ГИРОСКОП И АКСЕЛЕРОМЕТР. Нужны, чтобы связать команду пилота с
            # откликом аппарата: стик задаёт угловую скорость, а не угол.
            if now >= next_imu_t:
                next_imu_t = now + MSP_IMU_PERIOD
                imu = msp_request(102)  # MSP_RAW_IMU
                if imu is not None and len(imu) >= 18:
                    ax, ay, az, gx, gy, gz = struct.unpack('<6h', imu[:12])
                    with state_lock:
                        app_state["gyro"] = (gx, gy, gz)
                        app_state["acc"] = (ax, ay, az)
                        app_state["imu_ts"] = now
                        if not app_state.get("imu_seen"):
                            app_state["imu_seen"] = True
                            flight_log.event("ГИРОСКОП отвечает")

            # GPS. Может не быть вовсе — тогда просто молчит, а сбор данных
            # идёт по высоте, углу и скорости роста цели.
            if MSP_GPS_ENABLED and now >= next_gps_t:
                next_gps_t = now + MSP_GPS_PERIOD
                g = msp_request(106)  # MSP_RAW_GPS
                if g is not None and len(g) >= 16:
                    fix, numsat, lat, lon, alt_m, speed, course = \
                        struct.unpack('<BBiihhh', g[:16])
                    with state_lock:
                        app_state["gps_fix"] = int(fix)
                        app_state["gps_sats"] = int(numsat)
                        # Максимум за полёт: если спутники хоть раз были,
                        # модуль на борту есть — и индикатор нужен, даже
                        # когда захват сейчас потерян.
                        if int(numsat) > (app_state.get("gps_sats_max") or 0):
                            app_state["gps_sats_max"] = int(numsat)
                        app_state["gps_lat"] = lat / 1e7
                        app_state["gps_lon"] = lon / 1e7
                        app_state["gps_alt_m"] = int(alt_m)
                        app_state["gps_speed_cms"] = int(speed)
                        app_state["gps_course"] = course / 10.0
                        app_state["gps_ts"] = now
                        if fix and not app_state.get("gps_seen"):
                            app_state["gps_seen"] = True
                            flight_log.event(
                                "GPS отвечает: спутников %d" % numsat)

            if now >= next_alt_t:
                next_alt_t = now + MSP_ALTITUDE_PERIOD
                alt_data = msp_request(109)  # MSP_ALTITUDE
                if alt_data is not None and len(alt_data) >= 6:
                    # u32 высота в см + i16 вертикальная скорость в см/с.
                    alt_cm, vario_cms = struct.unpack('<ih', alt_data[:6])
                    # Шум барометра меряем на живых данных. Порог годности
                    # высоты нельзя задать числом раз и навсегда: он зависит
                    # от самого датчика и от погоды, а ошибка дальности прямо
                    # пропорциональна ошибке высоты (R = H/tg, значит
                    # dR/R = dH/H).
                    _alt_hist.append(int(alt_cm))
                    with state_lock:
                        app_state["alt_cm"] = int(alt_cm)
                        app_state["vario_cms"] = int(vario_cms)
                        app_state["alt_ts"] = now
                        app_state["alt_sigma_cm"] = _alt_sigma_cm()
                        if not app_state.get("alt_seen"):
                            app_state["alt_seen"] = True
                            flight_log.event(
                                "ВЫСОТОМЕР отвечает: alt=%d см vario=%d см/с"
                                % (alt_cm, vario_cms))

            if MOTOR_DEBUG_ENABLED and now >= next_motor_t:
                mot_data = msp_request(104)  # MSP_MOTOR
                if mot_data is not None and len(mot_data) >= 2:
                    vals = struct.unpack('<' + 'H' * (len(mot_data) // 2), mot_data)
                    with state_lock:
                        app_state["motors"] = list(vals)
                        app_state["motors_ts"] = now
                next_motor_t = now + MOTOR_DEBUG_PERIOD

            with state_lock:
                ov = override_active
                aux_now = aux4_state
                # ИСТОЧНИК PASSTHROUGH — кэш приёмника, а НЕ MSP_RC.
                #
                # Пока на FC активен MSP OVERRIDE, MSP_RC отдаёт по маскируемым
                # каналам то, что прислали мы сами (Betaflight,
                # rxMspOverrideReadRawRc). Если брать passthrough оттуда, то в
                # фазах ACQ/HOLD/LOST — когда трекер НЕ управляет, но AUX4
                # поднят — мы возвращали бы на FC собственную последнюю
                # команду вместо стика. Стики переставали отвечать, а квад
                # держал последний манёвр до опускания AUX4.
                live = list(app_state.get("receiver_channels", [1500] * 8))
                rc_ts = app_state.get("rc_link_ts", 0.0)
                r_cmd = global_roll_cmd
                p_cmd = global_pitch_cmd
                y_cmd = global_yaw_cmd
                t_cmd = global_throttle_cmd

            # ВСЕГДА шлём поток MSP override, как только пришёл хотя бы один
            # успешный MSP_RC. Это лечит «после AUX OFF тротл не возвращается»:
            # Betaflight с включённым msp_override_channels_mask ожидает
            # непрерывный поток MSP-кадров. Если мы вдруг перестаём слать,
            # он держит последние значения / уходит в failsafe.
            #
            # Passthrough идёт из кэша приёмника. Оси подменяются только
            # когда AUX4 поднят И трекер в TRACKED (override_active=True).
            have_fresh_rc = (time.monotonic() - rc_ts) <= RC_FRESH_WINDOW
            if have_fresh_rc:
                apply_ov = ov and aux_now
                channels = build_output_channels(
                    live, r_cmd, p_cmd, y_cmd, t_cmd, apply_ov)
                with state_lock:
                    app_state["last_sent_channels"] = list(channels[:8])
                send_msp_set_raw_rc(channels)
            # Без связи с FC вообще ничего не шлём — иначе он получит
            # стартовое «среднее» из app_state.
        except Exception:
            pass

        next_t += MSP_RC_PERIOD
        sleep_for = next_t - time.monotonic()
        if sleep_for > 0:
            time.sleep(sleep_for)
        else:
            next_t = time.monotonic()

# =========================================================
# 7. ГЕОМЕТРИЯ
# =========================================================
def clamp(v, lo, hi):
    return max(lo, min(hi, v))


def clamp_rect_center(cx, cy, w, h, max_w, max_h):
    w = max(2, int(round(w)))
    h = max(2, int(round(h)))
    x1 = int(round(cx - w / 2))
    y1 = int(round(cy - h / 2))
    x1 = clamp(x1, 0, max_w - w)
    y1 = clamp(y1, 0, max_h - h)
    return x1, y1, x1 + w, y1 + h


def crop_center(gray, cx, cy, w, h):
    x1, y1, x2, y2 = clamp_rect_center(cx, cy, w, h, gray.shape[1], gray.shape[0])
    return gray[y1:y2, x1:x2].copy(), (x1, y1, x2, y2)


def subpixel_peak(score_map, mx, my):
    """3-точечная параболическая интерполяция пика в score_map вокруг (mx, my).
    Возвращает (dx, dy) — субпиксельный сдвиг истинного пика относительно (mx, my),
    в диапазоне примерно [-0.5, 0.5]. Если пик на границе или в плоской зоне —
    возвращает (0, 0).
    Стоимость: 6 индексаций + 2 деления, в районе микросекунды.
    """
    h, w = score_map.shape[:2]
    dx = 0.0
    dy = 0.0
    if 0 < mx < w - 1:
        l = float(score_map[my, mx - 1])
        c = float(score_map[my, mx])
        r = float(score_map[my, mx + 1])
        denom = l - 2.0 * c + r
        if abs(denom) > 1e-6:
            dx = 0.5 * (l - r) / denom
            if dx < -0.5:
                dx = -0.5
            elif dx > 0.5:
                dx = 0.5
    if 0 < my < h - 1:
        t = float(score_map[my - 1, mx])
        c = float(score_map[my, mx])
        b = float(score_map[my + 1, mx])
        denom = t - 2.0 * c + b
        if abs(denom) > 1e-6:
            dy = 0.5 * (t - b) / denom
            if dy < -0.5:
                dy = -0.5
            elif dy > 0.5:
                dy = 0.5
    return dx, dy


def lores_box_to_main(cx, cy, w, h):
    sx = MAIN_W / LORES_W
    sy = MAIN_H / LORES_H
    x1 = int(round((cx - w / 2) * sx))
    y1 = int(round((cy - h / 2) * sy))
    x2 = int(round((cx + w / 2) * sx))
    y2 = int(round((cy + h / 2) * sy))
    x1 = clamp(x1, 0, MAIN_W - 1)
    y1 = clamp(y1, 0, MAIN_H - 1)
    x2 = clamp(x2, x1 + 1, MAIN_W)
    y2 = clamp(y2, y1 + 1, MAIN_H)
    return x1, y1, x2, y2


def refresh_flow_points(gray, cx, cy, w, h):
    patch, (x1, y1, x2, y2) = crop_center(gray, cx, cy, max(w * 2.2, 12), max(h * 2.2, 12))
    if patch.size == 0:
        return None
    pts = cv2.goodFeaturesToTrack(
        patch, maxCorners=25, qualityLevel=0.004, minDistance=2, blockSize=3
    )
    if pts is not None:
        pts = pts.astype(np.float32)
        pts[:, 0, 0] += x1
        pts[:, 0, 1] += y1
    return pts


def flow_predict(prev_g, cur_g, pts, cx, cy):
    if prev_g is None or pts is None or len(pts) < FLOW_MIN_POINTS:
        return False, cx, cy
    try:
        # Поток считаем по ОКНУ вокруг точек, а не по всему кадру.
        #
        # calcOpticalFlowPyrLK строит пирамиду по всей переданной картинке, и
        # это стоит пропорционально её ПЛОЩАДИ — независимо от того, что точек
        # всего два десятка. При переходе на 640x480 полный кадр обошёлся бы
        # вчетверо дороже каждый кадр, а Zero 2W упирается именно в процессор.
        #
        # Окно берём по границам точек плюс запас на их смещение. Точки
        # переводим в координаты окна, а результат возвращаем обратно —
        # снаружи функции ничего не меняется.
        #
        # ЗАПАС СЧИТАЕТСЯ ОТ САМИХ ТОЧЕК, а не берётся числом. Прежде стояло
        # фиксированное 72 — с запасом на самую крупную цель, то есть впустую
        # почти всегда: у мелкой цели точки лежат кучно, и три четверти окна
        # обрабатывались зря. А стоит поток пропорционально ПЛОЩАДИ окна.
        #
        # Просто уменьшить число нельзя: тест оконного потока поймал, что при
        # 40 точки крупной цели вылезают за край и результат расходится с
        # полнокадровым на 5 px. Поэтому запас нужен именно переменный:
        # половина окна поиска LK плюс место на смещение за кадр.
        pad = int(min(FLOW_WINDOW_PAD,
                      max(FLOW_WINDOW_PAD_MIN, FLOW_WIN + FLOW_MAX_STEP)))
        h_img, w_img = cur_g.shape[:2]
        use_window = FLOW_WINDOW_ENABLED
        xs, ys = pts[:, 0, 0], pts[:, 0, 1]
        wx1 = max(0, int(xs.min()) - pad)
        wy1 = max(0, int(ys.min()) - pad)
        wx2 = min(w_img, int(xs.max()) + pad + 1)
        wy2 = min(h_img, int(ys.max()) + pad + 1)
        # Слишком узкое окно пирамиде не годится — тогда работаем по кадру.
        if not use_window or (wx2 - wx1) < 32 or (wy2 - wy1) < 32:
            wx1, wy1, wx2, wy2 = 0, 0, w_img, h_img
        prev_win = prev_g[wy1:wy2, wx1:wx2]
        cur_win = cur_g[wy1:wy2, wx1:wx2]
        pts_win = pts.copy()
        pts_win[:, 0, 0] -= wx1
        pts_win[:, 0, 1] -= wy1

        nxt, st, err = cv2.calcOpticalFlowPyrLK(
            prev_win, cur_win, pts_win, None,
            winSize=(FLOW_WIN, FLOW_WIN), maxLevel=FLOW_LEVELS,
            criteria=(cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT,
                      FLOW_ITERS, 0.03),
        )
        if nxt is not None:
            nxt = nxt.copy()
            nxt[:, 0, 0] += wx1
            nxt[:, 0, 1] += wy1
        if nxt is None or st is None:
            return False, cx, cy
        st = st.reshape(-1).astype(bool)
        old = pts[st].reshape(-1, 2)
        new = nxt[st].reshape(-1, 2)
        if err is not None:
            keep = err[st].reshape(-1) < FLOW_ERR_MAX
            old, new = old[keep], new[keep]
        if len(new) < FLOW_MIN_POINTS:
            return False, cx, cy
        dx = float(np.median(new[:, 0] - old[:, 0]))
        dy = float(np.median(new[:, 1] - old[:, 1]))
        if math.hypot(dx, dy) > FLOW_MAX_STEP:
            return False, cx, cy
        return True, cx + dx, cy + dy
    except Exception:
        return False, cx, cy


# Почему оценка размера не удалась. Кодов два, и они требуют РАЗНОГО лечения:
# 1 — в центре нет пятна (слабый контраст или рамка не на цели),
# 2 — пятно залило область поиска (цель крупнее области).
# Без этого различия 'измерить не удалось' занимало 63% проверок и не
# говорило ничего.
_size_fail = {"why": 0, "R": 0, "w": 0, "roi": None, "mask": None,
              "box": None}
# Во сколько раз расширить область поиска после отказа «залило область».
# Растёт только на этом отказе и сбрасывается, как только размер измерился.
_size_R_boost = 1.0


def estimate_size_at_position(gray, cx, cy, cur_w=None):
    """Оценка размера цели вокруг точки (cx, cy) по связной компоненте.

    Возвращает (lw, lh) либо (None, None), если ИЗМЕРИТЬ НЕ УДАЛОСЬ.

    Различие принципиальное. Раньше при неудаче возвращался размер по
    умолчанию (8 px) — то есть САМОЕ МАЛЕНЬКОЕ значение. А неудача происходит
    ровно тогда, когда цель КРУПНАЯ и не помещается в область поиска: связная
    компонента получалась шире R*1.6 и отвергалась. Адаптация это значение
    применяла, и коробка каждые 10 кадров возвращалась к минимуму. По логам
    борта она стояла на 16 px (в координатах кадра) в 76%% кадров.

    Следствие для крупного объекта: трекер вёл участок 8x8 его текстуры, а
    такой участок неотличим от участка фактурного фона — отсюда и «на крупном
    фактурном объекте фон перебивает».

    Теперь «не смог измерить» и «размер равен минимуму» — разные ответы, и
    вызывающая сторона сама решает, что делать.

    cur_w — текущий размер коробки. Область поиска растягивается под него,
    иначе крупная цель заведомо не помещается и измерить её невозможно.
    """
    global _size_R_boost
    R = ACQ_SIZE_SEARCH_RADIUS
    if cur_w:
        # Область должна вмещать цель с запасом, иначе компонента упрётся в
        # её границы и будет отвергнута как «слишком большая».
        R = int(max(R, min(SIZE_SEARCH_RADIUS_MAX,
                           cur_w * 1.6 * _size_R_boost)))
    cxi = int(round(cx))
    cyi = int(round(cy))
    x1 = max(0, cxi - R)
    y1 = max(0, cyi - R)
    x2 = min(gray.shape[1], cxi + R + 1)
    y2 = min(gray.shape[0], cyi + R + 1)
    _size_fail["why"] = 0
    _size_fail["R"] = R
    _size_fail["roi"] = None
    _size_fail["mask"] = None
    _size_fail["box"] = None
    roi = gray[y1:y2, x1:x2]
    if roi.size == 0:
        _size_fail["why"] = 3
        return None, None

    roi_f = roi.astype(np.float32)
    med = float(np.median(roi_f))
    std = float(np.std(roi_f))

    diff = np.abs(roi_f - med).astype(np.uint8)
    thr = int(max(3, min(30, std * 0.55 + 2)))
    _, mask = cv2.threshold(diff, thr, 255, cv2.THRESH_BINARY)
    kernel = np.ones((2, 2), np.uint8)
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel)
    if ACQ_DEBUG_DUMP:
        _size_fail["roi"] = roi.copy()
        _size_fail["mask"] = mask.copy()

    cx_local = cxi - x1
    cy_local = cyi - y1

    def blob_at_centre(m):
        """Найти пятно под центром коробки. Ищем по расширяющемуся кольцу:
        центр может попасть ровно на границу внутри объекта."""
        n_lab, lab_img, st, _ = cv2.connectedComponentsWithStats(m, connectivity=8)
        for r_search in (0, 1, 2):
            for dy in range(-r_search, r_search + 1):
                for dx in range(-r_search, r_search + 1):
                    if abs(dx) != r_search and abs(dy) != r_search and r_search != 0:
                        continue
                    ny = cy_local + dy
                    nx = cx_local + dx
                    if 0 <= ny < lab_img.shape[0] and 0 <= nx < lab_img.shape[1]:
                        l = int(lab_img[ny, nx])
                        if l > 0:
                            return l, n_lab, st
        return 0, n_lab, st

    label, num_labels, stats = blob_at_centre(mask)
    if label == 0:
        # Центр не попал ни в одно пятно. Это бывает не только когда цель
        # слаба по контрасту, но и когда область ЦЕЛИКОМ ЛЕЖИТ НА ОБЪЕКТЕ:
        # тогда медианой становится сам объект, отклоняться от неё нечему, и
        # в маске остаётся лишь тонкая кайма фона по краю.
        #
        # Проверено: цель 60 px при области 65 px давала ровно это — отказ
        # приходил как «нет пятна», хотя цель занимала почти всю область.
        # Поэтому пробуем ОБРАТНУЮ маску: там центр попадёт во внутренность
        # объекта, пятно окажется во всю область, сработает признак «залило
        # область» — и он расширит поиск, вместо того чтобы молча сдаться.
        label, num_labels, stats = blob_at_centre(255 - mask)

    if label == 0 or label >= num_labels:
        _size_fail["why"] = 1
        if std < SIZE_UNIFORM_STD:
            # Область ровная — мы внутри объекта, а не на слабой цели.
            _size_fail["why"] = 4
            _size_R_boost = min(SIZE_R_BOOST_MAX,
                                _size_R_boost * SIZE_R_BOOST_STEP)
        return None, None

    x, y, w, h, area = stats[label]
    if ACQ_DEBUG_DUMP:
        _size_fail["box"] = (int(x), int(y), int(w), int(h))
    if area < 1:
        return None, None
    # Компонента упёрлась в границы области — значит цель как минимум такая,
    # но измерить её здесь нельзя. Отвечаем «не знаю», а НЕ минимальным
    # размером: подмена этих смыслов и ужимала коробку на крупных целях.
    # Признак «измерить нельзя» — пятно КАСАЕТСЯ КРАЯ области. Тогда мы видим
    # не весь объект, а лишь ту часть, что попала в область.
    #
    # Раньше здесь стояло w > R * 1.6, то есть «пятно шире области во столько-
    # то раз». Это грубая замена, и она отвергала ЗАКОННЫЕ замеры: пятно могло
    # целиком помещаться в области с запасом по краям и всё равно не проходить
    # порог. Проверено на модели: цель 90 px при области 109 px отвергалась,
    # хотя со всех сторон оставался зазор в десяток пикселей.
    #
    # Касание края — признак точный: если пятно нигде не дошло до границы,
    # значит объект увиден целиком и мерить его можно. А в реальной сцене
    # разлившаяся по всему кадру маска край заденет обязательно, так что
    # защита от неё сохраняется.
    if (x <= 0 or y <= 0
            or x + w >= roi.shape[1] or y + h >= roi.shape[0]):
        _size_fail["why"] = 2
        _size_fail["w"] = int(w)
        # Размыкаем замок: в следующий раз посмотрим шире.
        _size_R_boost = min(SIZE_R_BOOST_MAX, _size_R_boost * SIZE_R_BOOST_STEP)
        return None, None

    # Измерилось — расширение больше не нужно, возвращаемся к дешёвой области.
    _size_R_boost = 1.0
    lw = clamp(max(float(w) * LOCK_PAD, LOCK_MIN_W), LOCK_MIN_W, LOCK_MAX_W)
    lh = clamp(max(float(h) * LOCK_PAD, LOCK_MIN_H), LOCK_MIN_H, LOCK_MAX_H)
    return float(lw), float(lh)


def _acq_debug_dump(gray, results):
    """Сохранить на диск то, что трекер видит в момент захвата.

    Пишутся: кадр целиком, и на каждую пробованную область — сама область,
    маска порога и найденное пятно. По числам это разобрать не удалось, а
    глазами видно сразу: берётся весь предмет или крупица его фактуры.
    """
    global _acq_debug_n
    if not ACQ_DEBUG_DUMP or _acq_debug_n >= ACQ_DEBUG_MAX:
        return
    try:
        d = os.path.join(FLIGHT_LOG_DIR, ACQ_DEBUG_DIR)
        os.makedirs(d, exist_ok=True)
        _acq_debug_n += 1
        tag = "%s_lock%02d" % (
            getattr(flight_log, "_session", "no_session"), _acq_debug_n)
        cx, cy = int(CENTER_X_LORES), int(CENTER_Y_LORES)
        full = cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
        cv2.drawMarker(full, (cx, cy), (0, 0, 255), cv2.MARKER_CROSS, 20, 1)
        cv2.imwrite(os.path.join(d, tag + "_00_frame.png"), full)

        lines = []
        for radius, roi, mask, box, val in results:
            R = int(radius)
            vis = cv2.cvtColor(roi, cv2.COLOR_GRAY2BGR)
            if box is not None:
                x, y, w, h = box
                cv2.rectangle(vis, (x, y), (x + w, y + h), (0, 255, 0), 1)
            k = 4 if R <= 30 else 2
            cv2.imwrite(os.path.join(d, "%s_R%03d_roi.png" % (tag, R)),
                        cv2.resize(vis, None, fx=k, fy=k,
                                   interpolation=cv2.INTER_NEAREST))
            cv2.imwrite(os.path.join(d, "%s_R%03d_mask.png" % (tag, R)),
                        cv2.resize(mask, None, fx=k, fy=k,
                                   interpolation=cv2.INTER_NEAREST))
            lines.append("область %3d: пятно %s, размер %s"
                         % (R, box, "нет" if val is None else "%.1f" % val))
        with open(os.path.join(d, tag + "_итог.txt"), "w",
                  encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
        flight_log.event("СНИМОК ЗАХВАТА: %s (%d проб)" % (tag, len(results)))
    except Exception as exc:
        flight_log.event("СНИМОК ЗАХВАТА не удался: %s" % exc)


def estimate_size_at_crosshair(gray):
    """Размер цели под прицелом в момент захвата.

    ЗДЕСЬ БЫЛ ПЕРВЫЙ КАМЕНЬ ВСЕЙ ЦЕПОЧКИ. Раньше вызывалось одно измерение с
    областью по умолчанию — радиус 12, то есть окошко 25x25. Цель крупнее
    этого окошка касается его края, измерение отказывает, и подставляется
    размер по умолчанию 8. Оператор видел это как «sz = 16 и не меняется»:
    16 в координатах кадра — это ровно те самые 8, значение по умолчанию, а
    не измерение.

    Дальше рушилось всё остальное. Эталон брался вдвое больше коробки, то
    есть 16x16 — крошечный кусок предмета. Он цеплялся не за предмет, а за
    случайный участок его фактуры, и уезжал на край, где контраст выше.
    Примерка масштабов на таком эталоне тоже ничего не давала: кусок фактуры
    при увеличении предмета выглядит почти так же.

    Захват случается редко, поэтому здесь можно позволить себе несколько
    попыток с разной областью и взять первую, где предмет уместился целиком.
    """
    got = []
    shots = []
    for radius in SIZE_ACQ_RADII:
        lw, lh = estimate_size_at_position(
            gray, CENTER_X_LORES, CENTER_Y_LORES, cur_w=radius / 1.6)
        if ACQ_DEBUG_DUMP and _size_fail["roi"] is not None:
            shots.append((_size_fail["R"], _size_fail["roi"],
                          _size_fail["mask"], _size_fail["box"], lw))
        if lw is not None and lh is not None:
            got.append((lw, lh))
    if shots:
        _acq_debug_dump(gray, shots)
    if not got:
        return None, None

    # Берём не первое и не самое крупное измерение, а ТО, ЧТО ПОВТОРЯЕТСЯ.
    # Настоящий размер предмета не зависит от того, какой областью смотреть,
    # поэтому он и держится при разных областях. А случайные ответы —
    # пятнышко фактуры внутри предмета при маленькой области или слипание с
    # соседом при большой — держатся ровно по одному разу.
    #
    # Измерено на модели: цель 19 px давала 5 при области 12 и затем 37 при
    # 20, 32, 50 и 80. Взять первое значило взять 5, то есть крупицу фактуры.
    best, best_n = got[0], 0
    for cand in got:
        n = sum(1 for other in got
                if abs(other[0] - cand[0]) <= cand[0] * SIZE_ACQ_AGREE_TOL)
        if n > best_n or (n == best_n and cand[0] > best[0]):
            best, best_n = cand, n
    return best


def estimate_initial_target(gray):
    if ACQ_LOCK_AT_CROSSHAIR_EXACTLY:
        lw = lh = None
        if ACQ_SIZE_BY_SEGMENTATION:
            lw, lh = estimate_size_at_crosshair(gray)
        elif ACQ_DEBUG_DUMP:
            # Мерить не мерим, но снимок захвата всё равно снимаем: по нему
            # видно, что вообще было под прицелом.
            estimate_size_at_crosshair(gray)
        # При захвате «не измерили» означает «берём размер по умолчанию»:
        # цель ещё неизвестна, и начать с чего-то надо.
        if lw is None or lh is None:
            lw, lh = float(ACQ_DEFAULT_LOCK_W), float(ACQ_DEFAULT_LOCK_H)
        return float(CENTER_X_LORES), float(CENTER_Y_LORES), float(lw), float(lh), True
    return (float(CENTER_X_LORES), float(CENTER_Y_LORES),
            float(ACQ_DEFAULT_LOCK_W), float(ACQ_DEFAULT_LOCK_H), True)


def extract_chroma(yuv, w=None, h=None):
    """Достать плоскости U и V из буфера YUV420.

    Раскладка: сначала LORES_H строк яркости, затем по LORES_H/4 строк на U и
    на V — каждая строка шириной LORES_W содержит две строки по LORES_W/2.
    Цветность вдвое грубее яркости по обеим осям.
    """
    global chroma_fail_reason
    try:
        h = LORES_H if h is None else h
        w = LORES_W if w is None else w
        q = h // 4
        # ВАЖНО: строки буфера могут быть ШИРЕ кадра (выравнивание, stride).
        # На это прямо намекает то, что яркость берётся как [:H, :W], а не
        # целиком. Раньше цветность бралась строками ЦЕЛИКОМ, и на выравненном
        # буфере reshape падал, исключение проглатывалось — цвет молча не
        # работал, различимость всегда выходила ровно 0.0.
        u = yuv[h:h + q, :w].reshape(h // 2, w // 2)
        v = yuv[h + q:h + 2 * q, :w].reshape(h // 2, w // 2)
        chroma_fail_reason = ""
        return u, v
    except Exception as exc:
        chroma_fail_reason = "разбор буфера: %s (форма %s)" % (
            exc, getattr(yuv, "shape", "?"))
        return None, None


def measure_color_separation(cx, cy, box_w, box_h):
    """Различает ли цвет цель и её окружение. Вызывается один раз при захвате.

    Сравнивается средняя цветность ЦЕЛИ со средней цветностью кольца вокруг
    неё. Если они близки — цвет информации не несёт (серое на сером), и его
    использование только добавило бы шума в решение. Тогда отсев по цвету
    остаётся выключенным до конца захвата, и поведение прежнее.

    Возвращает (подпись_цели, различимость).
    """
    global chroma_fail_reason, chroma_debug
    if chroma_u is None or chroma_v is None:
        chroma_fail_reason = chroma_fail_reason or "цветность не прочитана"
        return None, 0.0
    ccx, ccy = int(cx) // 2, int(cy) // 2
    rw, rh = max(2, int(box_w) // 4), max(2, int(box_h) // 4)
    if rw < COLOR_MIN_TARGET_CHROMA_PX or rh < COLOR_MIN_TARGET_CHROMA_PX:
        chroma_fail_reason = ("цель мала: %dx%d px, радиус в цветности %d при "
                              "пороге %d" % (box_w, box_h, rw,
                                             COLOR_MIN_TARGET_CHROMA_PX))
        return None, 0.0
    H, W = chroma_u.shape
    def box_sum(arr, x0, y0, x1, y1):
        x0, y0 = max(0, x0), max(0, y0)
        x1, y1 = min(W, x1), min(H, y1)
        if x1 <= x0 or y1 <= y0:
            return 0.0, 0
        sub = arr[y0:y1, x0:x1]
        return float(sub.sum()), int(sub.size)

    def mean_box(arr, x0, y0, x1, y1):
        x0, y0 = max(0, x0), max(0, y0)
        x1, y1 = min(W, x1), min(H, y1)
        if x1 <= x0 or y1 <= y0:
            return None
        return float(arr[y0:y1, x0:x1].mean())
    tu = mean_box(chroma_u, ccx - rw, ccy - rh, ccx + rw, ccy + rh)
    tv = mean_box(chroma_v, ccx - rw, ccy - rh, ccx + rw, ccy + rh)

    # ФОН берётся НАСТОЯЩИМ КОЛЬЦОМ — внешняя область МИНУС область цели.
    #
    # Раньше это был просто квадрат втрое шире, ВКЛЮЧАВШИЙ саму цель. Из-за
    # этого он сравнивался частично сам с собой, а если объект крупнее
    # коробки — целиком лежал на объекте, и различимость выходила около нуля.
    # На борту оранжевый предмет на коричневом фоне давал 2.9-5.7, тогда как
    # по цветовой геометрии эта пара обязана давать 50-108.
    #
    # Внешний радиус увеличен с 3 до 4: кольцо должно доставать до фона даже
    # когда коробка занижает размер объекта.
    K = 4
    def ring_mean(arr):
        outer_sum, outer_n = box_sum(arr, ccx - K * rw, ccy - K * rh,
                                     ccx + K * rw, ccy + K * rh)
        inner_sum, inner_n = box_sum(arr, ccx - rw, ccy - rh,
                                     ccx + rw, ccy + rh)
        n = outer_n - inner_n
        if n <= 0:
            return None
        return (outer_sum - inner_sum) / float(n)

    ou = ring_mean(chroma_u)
    ov = ring_mean(chroma_v)
    if None in (tu, tv, ou, ov):
        chroma_fail_reason = "область за границей кадра"
        return None, 0.0
    chroma_fail_reason = ""
    sep = abs(tu - ou) + abs(tv - ov)
    # Значения в журнал: без них «различимость мала» неотличимо от «меряем не
    # то», а на этом мы уже обожглись.
    chroma_debug = "цель U=%.0f V=%.0f | фон U=%.0f V=%.0f" % (tu, tv, ou, ov)
    return (tu, tv), sep


def motion_penalty_map(prev_g, cur_g, sx1, sy1, sx2, sy2, tw, th, shape,
                       tgt_dx, tgt_dy):
    """Штраф кандидатам, которые движутся ВМЕСТЕ С ФОНОМ.

    Метод: оценить движение фона, скомпенсировать его сдвигом предыдущего
    кадра и взять разность с текущим. Всё, что двигалось иначе фона, даёт
    остаточный отклик; фон гасится.

    Почему не оптический поток по точкам. Он измеряет смещение по градиентам в
    окне 15x15 и принципиально не справляется с МЕЛКОЙ целью: при смещении
    цели на её собственный размер она уходит из окна целиком, и измерять
    нечего. Проверено: цель 6 px, сместившаяся на 6 px, давала 1.0 вместо 6.0
    при любом размере окна. А мелкая цель — ровно тот случай, ради которого
    признак и нужен. Разность кадров этим не ограничена: для цели 10-16 px
    отклик выше фонового в 40-50 раз.

    Признак НЕ ЗАВИСИТ ОТ РАЗМЕРА ЦЕЛИ, и этим ценен: когда цель мельче
    деталей фона, сравнивать по виду уже нечего, а движение различает.

    Возвращает (карта_штрафа, движение_фона, различимость) либо
    (None, None, 0.0), если посчитать нельзя.
    """
    if prev_g is None or cur_g is None:
        return None, None, 0.0
    try:
        # --- 1. движение фона ---
        # Считается потоком по редкой сетке: фон крупный и фактурный, для него
        # поток надёжен. Медиана описывает именно фон — он занимает большую
        # часть площади окна.
        step = max(6, int(MOTION_GRID_STEP))
        xs = np.arange(sx1 + step // 2, sx2 - 1, step, dtype=np.float32)
        ys = np.arange(sy1 + step // 2, sy2 - 1, step, dtype=np.float32)
        if len(xs) < 3 or len(ys) < 3:
            return None, None, 0.0
        gx, gy = np.meshgrid(xs, ys)
        pts = np.stack([gx.ravel(), gy.ravel()], axis=1).reshape(-1, 1, 2)
        # Поток считаем по ОКНУ, а не по всему кадру: пирамида строится по
        # всей переданной картинке, и полный кадр обходится вчетверо дороже
        # без всякой пользы — точки всё равно лежат в окне поиска.
        # Запас вокруг окна для пирамиды потока. 72 давало окно почти во весь
        # кадр — дорого и без пользы: движение фона оценивается и по меньшей
        # области.
        gpad = 40
        gx1 = max(0, int(sx1) - gpad); gy1 = max(0, int(sy1) - gpad)
        gx2 = min(cur_g.shape[1], int(sx2) + gpad)
        gy2 = min(cur_g.shape[0], int(sy2) + gpad)
        pw = pts.copy()
        pw[:, 0, 0] -= gx1
        pw[:, 0, 1] -= gy1
        nxt, st, _ = cv2.calcOpticalFlowPyrLK(
            prev_g[gy1:gy2, gx1:gx2], cur_g[gy1:gy2, gx1:gx2], pw, None,
            # Одного уровня пирамиды достаточно: оценивается движение ФОНА,
            # а оно между соседними кадрами невелико. Второй уровень удваивал
            # цену ради запаса, который здесь не нужен.
            winSize=(15, 15), maxLevel=1,
            criteria=(cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT, 10, 0.03))
        if nxt is not None:
            nxt = nxt.copy()
            nxt[:, 0, 0] += gx1
            nxt[:, 0, 1] += gy1
            pts = pw.copy()
            pts[:, 0, 0] += gx1
            pts[:, 0, 1] += gy1
        if nxt is None or st is None:
            return None, None, 0.0
        ok = st.reshape(-1).astype(bool)
        if ok.sum() < 6:
            return None, None, 0.0
        d = (nxt - pts).reshape(-1, 2)
        bg = np.array([float(np.median(d[ok, 0])), float(np.median(d[ok, 1]))])

        # Если цель движется почти как фон, признак ничего не различает.
        # Так бывает, когда цель стоит — и так будет в реальном применении,
        # где дрон летит на НЕПОДВИЖНУЮ наземную цель. Тогда молчим.
        sep = float(math.hypot(tgt_dx - bg[0], tgt_dy - bg[1]))
        if sep < MOTION_MIN_SEPARATION:
            return None, bg, sep

        # --- 2. компенсация движения фона и разность ---
        pad = 24
        wx1 = max(0, int(sx1) - pad)
        wy1 = max(0, int(sy1) - pad)
        wx2 = min(cur_g.shape[1], int(sx2) + pad)
        wy2 = min(cur_g.shape[0], int(sy2) + pad)
        if wx2 - wx1 < 8 or wy2 - wy1 < 8:
            return None, bg, sep
        # Считаем разность в ПОЛОВИННОМ разрешении. Мы всё равно усредняем её
        # по площади цели, поэтому полное разрешение здесь пропадает впустую, а
        # стоит вчетверо дороже.
        pa = prev_g[wy1:wy2, wx1:wx2]
        ca = cur_g[wy1:wy2, wx1:wx2]
        hw, hh = (wx2 - wx1) // 2, (wy2 - wy1) // 2
        if hw < 8 or hh < 8:
            return None, bg, sep
        pa = cv2.resize(pa, (hw, hh), interpolation=cv2.INTER_AREA)
        ca = cv2.resize(ca, (hw, hh), interpolation=cv2.INTER_AREA)
        M = np.float32([[1, 0, float(bg[0]) / 2.0], [0, 1, float(bg[1]) / 2.0]])
        warped = cv2.warpAffine(pa, M, (hw, hh), flags=cv2.INTER_LINEAR,
                                borderMode=cv2.BORDER_REPLICATE)
        diff = cv2.absdiff(ca, warped).astype(np.float32)
        # Усредняем по площади цели: одиночный пиксель разности слишком шумен.
        k = max(3, int(tw / max(TEMPLATE_SCALE, 1.0) / 2.0) | 1)
        diff = cv2.blur(diff, (k, k))

        # --- 3. штраф там, где отклика НЕТ (значит движется как фон) ---
        # Нормировка УСТОЙЧИВАЯ, а не по максимуму. Максимум задаётся редким
        # выбросом (край, блик), и деление на него топит слабый сигнал: у цели
        # 6 px той же текстуры отклик около 0.6 при выбросах в десятки —
        # различие есть, но после деления исчезает.
        # Опорой берём медиану (это уровень фона), а масштабом — фиксированную
        # величину в единицах яркости.
        base = float(np.median(diff))
        resp = np.clip((diff - base) / MOTION_DIFF_REF, 0.0, 1.0)
        if float(resp.max()) < 0.05:
            return None, bg, sep          # ничего не движется, различать нечем
        pen = 1.0 - resp
        # Вырезаем часть, соответствующую ЦЕНТРАМ кандидатов.
        # Кандидат (i, j) ставит шаблон углом в (sx1+j, sy1+i), значит центр
        # цели у него в (sx1+j+tw/2, sy1+i+th/2). Раньше вырез брался от угла
        # и растягивался — из-за этого он уезжал мимо цели тем сильнее, чем
        # крупнее шаблон, и штраф ложился не туда.
        # Карта в половинном разрешении, поэтому смещения тоже вдвое меньше.
        rh, rw = shape
        ox = (int(sx1) - wx1 + int(tw) // 2) // 2
        oy = (int(sy1) - wy1 + int(th) // 2) // 2
        sw, sh = (rw + 1) // 2, (rh + 1) // 2
        if ox < 0 or oy < 0 or ox + sw > pen.shape[1] or oy + sh > pen.shape[0]:
            return None, bg, sep
        sub = pen[oy:oy + sh, ox:ox + sw]
        return cv2.resize(sub, (rw, rh), interpolation=cv2.INTER_LINEAR), bg, sep
    except Exception:
        return None, None, 0.0


def color_penalty_map(sx1, sy1, tw, th, shape):
    """Штраф за несовпадение цвета для каждой позиции кандидата.

    Для каждой позиции берётся средняя цветность области размером с цель и
    сравнивается с подписью, снятой при захвате. Считается на разрешении
    цветности (вдвое меньше) и растягивается до размера карты откликов.
    """
    if not color_active or target_uv is None or chroma_u is None:
        return None
    try:
        rh, rw = shape
        tu, tv = target_uv
        # Область цветности, покрывающая все центры кандидатов.
        cx0 = max(0, (sx1 + tw // 2) // 2 - 1)
        cy0 = max(0, (sy1 + th // 2) // 2 - 1)
        cx1 = min(chroma_u.shape[1], cx0 + rw // 2 + 3)
        cy1 = min(chroma_u.shape[0], cy0 + rh // 2 + 3)
        if cx1 - cx0 < 2 or cy1 - cy0 < 2:
            return None
        u = chroma_u[cy0:cy1, cx0:cx1].astype(np.float32)
        v = chroma_v[cy0:cy1, cx0:cx1].astype(np.float32)
        # Усредняем по площади цели: одиночный пиксель цветности слишком шумен.
        k = max(1, min(int(tw) // 4, min(u.shape) ))
        if k > 1:
            u = cv2.blur(u, (k, k))
            v = cv2.blur(v, (k, k))
        d = np.abs(u - tu) + np.abs(v - tv)
        d = np.clip(d / COLOR_REF_DIST, 0.0, 1.0)
        # Растягиваем до размера карты откликов (цветность вдвое грубее).
        return cv2.resize(d, (rw, rh), interpolation=cv2.INTER_LINEAR)
    except Exception:
        return None


def measure_scale_change(gray, cx, cy):
    """Во сколько раз цель изменилась в размере. Возвращает множитель или None.

    Эталон примеряется в трёх масштабах — мельче, как есть, крупнее — и
    побеждает тот, что совпадает лучше. Никакой сегментации: используется ровно
    тот же признак, которым ведётся слежение, поэтому загромождённая сцена
    мешает не больше, чем самому слежению.

    Множитель возвращается только когда соседний масштаб обходит текущий
    ЗАМЕТНО. Иначе шум масштабировал бы коробку на каждом кадре.
    """
    if template_gray is None or template_gray.size == 0:
        return None
    try:
        # Считаем на уменьшенной копии. Масштаб — величина грубая, полное
        # разрешение для неё не нужно, а стоит она пропорционально ПЛОЩАДИ:
        # уменьшение вдвое даёт вчетверо дешевле. Замерено на малине:
        # эталон 110 стоил 9.3 мс на кадр, на половинном разрешении — 2.4.
        ds = max(1, int(SIZE_SCALE_DOWNSAMPLE))
        # Уменьшаем ТОЛЬКО крупный эталон. Мелкий и так дёшев, а на
        # половинном разрешении он теряет детали и масштаб перестаёт
        # различаться вовсе — проверено, коробка переставала расти.
        if ds > 1 and min(template_gray.shape[:2]) >= SIZE_SCALE_DS_MIN:
            tmpl_src = cv2.resize(
                template_gray,
                (template_gray.shape[1] // ds, template_gray.shape[0] // ds),
                interpolation=cv2.INTER_AREA)
        else:
            ds = 1
            tmpl_src = template_gray
        th, tw = tmpl_src.shape[:2]
        # Область должна вмещать самый крупный из примеряемых эталонов.
        big = int(max(tw, th) * SIZE_SCALE_STEP)
        margin = int(SEARCH_MARGIN_MIN)
        sw = (big + margin * 2) * ds
        search, _rect = crop_center(gray, cx, cy, sw, sw)
        if ds > 1:
            search = cv2.resize(
                search, (search.shape[1] // ds, search.shape[0] // ds),
                interpolation=cv2.INTER_AREA)
        if search.shape[0] < big + 2 or search.shape[1] < big + 2:
            return None

        best_s, best_v = 1.0, None
        base_v = None
        for s_ in (1.0 / SIZE_SCALE_STEP, 1.0, SIZE_SCALE_STEP):
            w_ = int(round(tw * s_))
            h_ = int(round(th * s_))
            if w_ < 8 or h_ < 8:
                continue
            if w_ >= search.shape[1] or h_ >= search.shape[0]:
                continue
            # ОДИНАКОВАЯ интерполяция для обеих сторон: разная давала бы
            # перекос сама по себе, независимо от того, что в кадре.
            tm = (tmpl_src if s_ == 1.0 else
                  cv2.resize(tmpl_src, (w_, h_),
                             interpolation=cv2.INTER_LINEAR))
            res = cv2.matchTemplate(search, tm, cv2.TM_CCOEFF_NORMED)
            v = float(res.max()) if res.size else -1.0
            if s_ == 1.0:
                base_v = v
            if best_v is None or v > best_v:
                best_v, best_s = v, s_
        if base_v is None or best_v is None:
            return None
        if best_s == 1.0 or (best_v - base_v) < SIZE_SCALE_MIN_LEAD:
            return 1.0
        return best_s
    except Exception:
        return None


def _adapt_template_base(gray):
    """Подмешать текущий вид цели в ИСХОДНЫЙ эталон.

    Зачем отдельно. Эталон нужного масштаба получается пересчётом из
    исходного — только так удаётся не размывать его накопленными
    интерполяциями. Но такой пересчёт каждый раз отбрасывает накопленную
    адаптацию к свету и ракурсу, и эталон остаётся таким, каким был при
    захвате. На однотонном фоне это сходит с рук, на фактурном устаревший
    эталон начинает совпадать с фоном — качество слежения падает.

    Здесь свежий кусок кадра приводится к размеру исходного эталона и
    подмешивается в него. Интерполяция всегда одна и всегда по СВЕЖИМ данным:
    исходный эталон не пересчитывается сам из себя, поэтому не мутнеет.
    """
    global template_base
    if template_base is None:
        return
    try:
        bh, bw = template_base.shape[:2]
        fresh, _rect = crop_center(gray, lock_cx, lock_cy,
                                   int(bw * template_scale_acc),
                                   int(bh * template_scale_acc))
        if fresh.size == 0:
            return
        if fresh.shape[:2] != (bh, bw):
            fresh = cv2.resize(fresh, (bw, bh), interpolation=cv2.INTER_AREA)
        template_base = cv2.addWeighted(
            template_base, 1.0 - TEMPLATE_BASE_ALPHA,
            fresh, TEMPLATE_BASE_ALPHA, 0)
    except Exception:
        pass


def measure_color_axis(gray, cx, cy, box_w, box_h):
    """Направление в цветности, по которому цель отличается от фона.

    Возвращает (du, dv, ou, ov, выигрыш) либо None. Выигрыш — во сколько раз
    цветовой контраст цель/фон превосходит яркостный. Считается один раз при
    захвате: направление снимается с той цели, которую указал оператор.
    """
    if chroma_u is None or chroma_v is None:
        return None
    try:
        rw = max(2, int(box_w / 4)); rh = max(2, int(box_h / 4))
        ccx, ccy = int(cx / 2), int(cy / 2)
        K = 4

        def s_n(a, x0, y0, x1, y1):
            x0 = max(0, x0); y0 = max(0, y0)
            x1 = min(a.shape[1], x1); y1 = min(a.shape[0], y1)
            if x1 <= x0 or y1 <= y0:
                return 0.0, 0
            p = a[y0:y1, x0:x1]
            return float(p.sum()), int(p.size)

        def ring(a):
            so, no = s_n(a, ccx - K * rw, ccy - K * rh, ccx + K * rw, ccy + K * rh)
            si, ni = s_n(a, ccx - rw, ccy - rh, ccx + rw, ccy + rh)
            if no - ni <= 0 or ni <= 0:
                return None, None
            return si / ni, (so - si) / (no - ni)

        tu, ou = ring(chroma_u.astype(np.float32))
        tv, ov = ring(chroma_v.astype(np.float32))
        if tu is None or tv is None:
            return None
        du, dv = tu - ou, tv - ov
        sep = math.hypot(du, dv)
        if sep < TRACK_ON_COLOR_MIN_SEP:
            return None

        # Яркостный контраст той же пары областей — с чем сравниваем.
        gt, gb = None, None
        try:
            bw2 = max(3, int(box_w)); bh2 = max(3, int(box_h))
            si, ni = s_n(gray, int(cx - bw2 / 2), int(cy - bh2 / 2),
                         int(cx + bw2 / 2), int(cy + bh2 / 2))
            so, no = s_n(gray, int(cx - 2 * bw2), int(cy - 2 * bh2),
                         int(cx + 2 * bw2), int(cy + 2 * bh2))
            if ni > 0 and no - ni > 0:
                gt = si / ni
                gb = (so - si) / (no - ni)
        except Exception:
            pass
        y_contrast = abs(gt - gb) if (gt is not None and gb is not None) else 0.0
        gain = sep / max(y_contrast, 1e-3)
        # В оси хранится и САМ ЦВЕТ ЦЕЛИ: он нужен, чтобы потом
        # пересчитывать фон, не трогая цель.
        return du / sep, dv / sep, ou, ov, gain, tu, tv
    except Exception:
        return None


def refresh_color_axis(cx, cy, box_w, box_h):
    """Пересчитать ФОН в оси цвета, оставив цвет цели прежним.

    Ось строится как «цвет цели минус цвет фона». Цвет цели — её признак, он
    снят при захвате и не меняется: иначе, стоит рамке чуть сползти, мы начнём
    считать целью фон. А вот ФОН по ходу захода меняется по-настоящему —
    оранжевая машина уходит с серого асфальта на жёлтое поле, — и ось со старым
    фоном становится неверной.

    Если цель и фон сравнялись по цвету, возвращаем False: вести по проекции
    больше нельзя, направление оси стало шумом.
    """
    global color_axis
    if color_axis is None or chroma_u is None or chroma_v is None:
        return False
    try:
        _du0, _dv0, _ou0, _ov0, gain, tu, tv = color_axis

        rw = max(2, int(box_w / 4)); rh = max(2, int(box_h / 4))
        ccx, ccy = int(cx / 2), int(cy / 2)
        K = 4

        def s_n(a, x0, y0, x1, y1):
            x0 = max(0, x0); y0 = max(0, y0)
            x1 = min(a.shape[1], x1); y1 = min(a.shape[0], y1)
            if x1 <= x0 or y1 <= y0:
                return 0.0, 0
            p = a[y0:y1, x0:x1]
            return float(p.sum()), int(p.size)

        def ring_bg(a):
            so, no = s_n(a, ccx - K * rw, ccy - K * rh, ccx + K * rw, ccy + K * rh)
            si, ni = s_n(a, ccx - rw, ccy - rh, ccx + rw, ccy + rh)
            if no - ni <= 0:
                return None
            return (so - si) / (no - ni)

        ou = ring_bg(chroma_u.astype(np.float32))
        ov = ring_bg(chroma_v.astype(np.float32))
        if ou is None or ov is None:
            return True                      # не смогли — оставляем как было
        du, dv = tu - ou, tv - ov
        sep = math.hypot(du, dv)
        if sep < TRACK_ON_COLOR_DROP_SEP:
            flight_log.event(
                "ЦВЕТ БОЛЬШЕ НЕ РАЗЛИЧАЕТ: цель и фон сошлись (%.1f), "
                "возвращаемся на яркость" % sep)
            color_axis = None
            return False
        color_axis = (du / sep, dv / sep, ou, ov, gain, tu, tv)
        return True
    except Exception:
        return True


def color_projection(shape):
    """Кадр, в котором цветовое отличие цели превращено в яркостное.

    Фактура фона при этом схлопывается: она отличается яркостью, а не цветом.
    Именно поэтому перфорированная стена, на которую срывался трекер, в этой
    картинке пропадает.
    """
    if color_axis is None or chroma_u is None or chroma_v is None:
        return None
    try:
        _du, _dv, _ou, _ov, _g, tu, tv = color_axis
        # БЛИЗОСТЬ К ЦВЕТУ ЦЕЛИ, а не проекция вдоль оси «цель минус фон».
        #
        # Проекция была ОДНОМЕРНОЙ и мерила «насколько далеко от фона». Из-за
        # этого всё, что отличается от фона в ту же сторону, выглядело как
        # цель. Случай оператора — ярко-зелёная цель на ярко-синем фоне:
        #
        #     цель 255, СЕРЫЙ СТЕНД 251 — неотличимы
        #
        # и трекер честно уходил на стену. Близость к цвету цели этого не
        # даёт: там и синий фон, и серый стенд одинаково темны (0 и 90), а
        # ярче всех только сама цель.
        #
        # Считается по |dU| + |dV| вместо корня из суммы квадратов: разница
        # для нас несущественна, а стоит заметно дешевле. Всё — одним
        # действием и на МАЛОЙ картинке: цветность вчетверо меньше кадра.
        k = TRACK_ON_COLOR_SCALE
        du_img = cv2.absdiff(chroma_u, int(round(max(0, min(255, tu)))))
        dv_img = cv2.absdiff(chroma_v, int(round(max(0, min(255, tv)))))
        p = cv2.addWeighted(du_img, -k, dv_img, -k, 255.0, dtype=cv2.CV_8U)
        return cv2.resize(p, (shape[1], shape[0]),
                          interpolation=cv2.INTER_LINEAR)
    except Exception:
        return None


def estimate_ground_speed(gray, now_mono):
    """Путевая скорость по бегу земли в кадре. Работает БЕЗ GPS.

    Смысл простой. Точка на земле в нижней части кадра уходит назад тем
    быстрее, чем быстрее летит аппарат и чем он ниже. Угловая скорость этой
    точки равна v / R, где R — наклонная дальность до неё. Дальность берём из
    высоты и угла, под которым эта точка видна, — то есть тем же способом, что
    и дальность до цели.

    Отсюда  v = (угловая скорость) * R.

    Зачем это нужно. Закон точки прицеливания зависит от скорости, и без неё
    он вышел бы усреднённым. GPS даёт скорость напрямую, но GPS может не быть,
    а высота и камера есть всегда.

    Считается по нижней полосе кадра: там земля, а не небо и не цель. Берём
    СЕРЕДИННОЕ смещение, а не среднее: одиночный движущийся предмет в кадре
    середину не сдвинет.
    """
    global _gs_prev_gray, _gs_prev_pts, _gs_prev_t, ground_speed_mps
    try:
        h, w = gray.shape[:2]
        y0 = int(h * GROUND_BAND_TOP)
        band = gray[y0:h, :]
        if _gs_prev_gray is None or _gs_prev_gray.shape != band.shape:
            _gs_prev_gray = band.copy()
            _gs_prev_pts = None
            _gs_prev_t = now_mono
            return None
        dt = now_mono - _gs_prev_t
        if dt <= 1e-3:
            return None
        if _gs_prev_pts is None or len(_gs_prev_pts) < GROUND_MIN_POINTS:
            _gs_prev_pts = cv2.goodFeaturesToTrack(
                _gs_prev_gray, maxCorners=GROUND_MAX_POINTS,
                qualityLevel=0.01, minDistance=8, blockSize=5)
        if _gs_prev_pts is None or len(_gs_prev_pts) < GROUND_MIN_POINTS:
            _gs_prev_gray = band.copy()
            _gs_prev_t = now_mono
            return None
        nxt, st, _err = cv2.calcOpticalFlowPyrLK(
            _gs_prev_gray, band, _gs_prev_pts.astype(np.float32), None,
            winSize=(FLOW_WIN, FLOW_WIN), maxLevel=FLOW_LEVELS,
            criteria=(cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT,
                      FLOW_ITERS, 0.03))
        speed = None
        if nxt is not None and st is not None:
            ok = st.reshape(-1).astype(bool)
            if ok.sum() >= GROUND_MIN_POINTS:
                p0 = _gs_prev_pts.reshape(-1, 2)[ok]
                p1 = nxt.reshape(-1, 2)[ok]
                dy_px = np.median(p1[:, 1] - p0[:, 1])      # земля уходит ВНИЗ
                dx_px = np.median(p1[:, 0] - p0[:, 0])
                shift = float(math.hypot(dx_px, dy_px))
                with state_lock:
                    alt_cm = app_state.get("alt_cm")
                    fc_pitch = app_state.get("fc_pitch_deg")
                    armed = app_state.get("armed")
                if armed and alt_cm is not None and fc_pitch is not None:
                    alt_m = alt_cm / 100.0
                    # Угол, под которым видна середина полосы, ниже горизонта.
                    deg_per_px = CAMERA_VFOV_DEG / float(MAIN_H)
                    band_mid = (y0 + h) / 2.0
                    off_deg = (band_mid * 2.0 - CENTER_Y) * deg_per_px
                    dep = float(fc_pitch) - CAMERA_TILT_DEG + off_deg
                    if dep >= GROUND_MIN_DEPRESSION_DEG and alt_m > 0.5:
                        slant = alt_m / math.sin(math.radians(dep))
                        ang_rate = math.radians(shift * 2.0 * deg_per_px) / dt
                        speed = ang_rate * slant
        _gs_prev_gray = band.copy()
        _gs_prev_pts = None if nxt is None else nxt
        _gs_prev_t = now_mono
        if speed is not None and 0.0 <= speed < 120.0:
            a = alpha_for_dt(GROUND_SPEED_ALPHA, 1.0)
            if ground_speed_mps is None:
                ground_speed_mps = speed
            else:
                ground_speed_mps += a * (speed - ground_speed_mps)
        return ground_speed_mps
    except Exception:
        return None


def build_template(gray, cx, cy, box_w, box_h):
    global tmpl_w, tmpl_h, template_std
    tw = clamp(max(box_w * TEMPLATE_SCALE, TEMPLATE_MIN), TEMPLATE_MIN, TEMPLATE_MAX)
    th = clamp(max(box_h * TEMPLATE_SCALE, TEMPLATE_MIN), TEMPLATE_MIN, TEMPLATE_MAX)
    tmpl, rect = crop_center(gray, cx, cy, tw, th)
    template_std = float(np.std(tmpl)) if tmpl.size else 0.0
    tmpl_w = tmpl.shape[1]
    tmpl_h = tmpl.shape[0]
    return tmpl


def template_match_locked(gray, pred_cx, pred_cy, flow_motion=0.0,
                          tgt_dx=0.0, tgt_dy=0.0):
    """Темплейт-матч с distance-penalty + субпиксельная интерполяция пика.

    flow_motion: модуль смещения flow-предсказания за кадр (px). Используется
    для адаптивного выбора SEARCH_MARGIN: на медленной цели окно меньше
    (быстрее матч, меньше шансов уцепиться за фон), на быстрой — больше.
    """
    global template_gray, tmpl_w, tmpl_h
    global motion_bg, motion_active, motion_separation
    # РАЗМЕР БЕРЁМ У САМОГО ЭТАЛОНА, а не из глобалов. Глобалы расходились с
    # ним, и это уводило рамку с цели.
    #
    # Как расходились. build_template ВСЕГДА записывает новый размер в tmpl_w
    # и tmpl_h — даже когда вызывающая сторона его результат ВЫБРАСЫВАЕТ. А
    # выбрасывала она его каждый раз, когда размер коробки изменился:
    # обновление эталона идёт только при совпадении форм, а ветка пересчёта
    # выключена флагом TEMPLATE_RESCALE_ON_SIZE_CHANGE = False.
    #
    # Дальше центр совпадения считается как sx1 + mx + tmpl_w / 2. Если
    # tmpl_w говорит 80, а эталон на самом деле 40 — центр смещается ровно на
    # (80 - 40) / 2 = 20 пикселей. Систематически, в одну сторону, каждый
    # кадр. Это и есть 'рамка уезжает на край'.
    #
    # Раньше это почти не проявлялось: размер коробки менялся редко. Примерка
    # масштабов стала менять его постоянно — 96 раз за заход 165310 — и
    # ошибка вылезла в полный рост.
    if template_gray is not None:
        tmpl_h, tmpl_w = template_gray.shape[:2]
    if template_gray is None or tmpl_w is None or tmpl_h is None:
        return False, pred_cx, pred_cy, 0.0

    # Адаптивный margin по скорости движения цели.
    if ADAPTIVE_SEARCH_MARGIN:
        vel_norm = flow_motion / SEARCH_MARGIN_VEL_REF
        if vel_norm > 1.0:
            vel_norm = 1.0
        margin = int(round(SEARCH_MARGIN_MIN + (SEARCH_MARGIN_MAX - SEARCH_MARGIN_MIN) * vel_norm))
    else:
        margin = SEARCH_MARGIN

    sw = int(tmpl_w + margin * 2)
    sh = int(tmpl_h + margin * 2)
    search, (sx1, sy1, sx2, sy2) = crop_center(gray, pred_cx, pred_cy, sw, sh)
    if search.shape[0] < tmpl_h or search.shape[1] < tmpl_w:
        return False, pred_cx, pred_cy, 0.0

    try:
        if template_std < 3.0:
            res = cv2.matchTemplate(search, template_gray, cv2.TM_SQDIFF_NORMED)
            score_map = 1.0 - res
        else:
            score_map = cv2.matchTemplate(search, template_gray, cv2.TM_CCOEFF_NORMED)
    except Exception:
        return False, pred_cx, pred_cy, 0.0

    if score_map.size == 0:
        return False, pred_cx, pred_cy, 0.0

    rh, rw = score_map.shape[:2]
    yy, xx = np.mgrid[0:rh, 0:rw]
    centers_x = sx1 + xx + tmpl_w / 2.0
    centers_y = sy1 + yy + tmpl_h / 2.0
    dist = np.sqrt((centers_x - pred_cx) ** 2 + (centers_y - pred_cy) ** 2)
    # Нормируем штраф по фактическому margin, не по константе.
    norm = max(margin, 1)
    penalized = score_map - DIST_PENALTY * (dist / norm) ** 2
    # Цветовой отсев. Добавляется к тому же штрафу, что и расстояние, поэтому
    # выбор пика учитывает цвет, но сама величина score остаётся чисто
    # яркостной — сравнимой с прежними логами.
    cmap = color_penalty_map(sx1, sy1, tmpl_w, tmpl_h, score_map.shape)
    _match_dbg["color_on"] = 1 if cmap is not None else 0
    if cmap is not None:
        penalized = penalized - COLOR_PENALTY * cmap

    # Отсев по движению. Не зависит от размера цели, поэтому работает там, где
    # сравнение по виду упирается в потолок: мелкая цель на фактурном фоне.
    if MOTION_GUARD_ENABLED:
        mmap, bg, sep = motion_penalty_map(
            prev_gray, gray, sx1, sy1, sx2, sy2, tmpl_w, tmpl_h,
            score_map.shape, tgt_dx, tgt_dy)
        motion_bg = bg
        motion_separation = sep
        motion_active = mmap is not None
        if mmap is not None:
            penalized = penalized - MOTION_PENALTY * mmap
        _match_dbg["motion_sep"] = sep
        _match_dbg["motion_on"] = 1 if motion_active else 0

    _, max_val, _, max_loc = cv2.minMaxLoc(penalized.astype(np.float32))
    mx, my = max_loc
    raw_score = float(score_map[my, mx])

    # Единственное измерение, которое отвечает на вопрос «работает ли цвет».
    # color_pen — насколько выбранная точка НЕ похожа по цвету на цель (0 —
    # цвет цели, 1 — совсем чужой). color_best — был ли в окне вообще хоть
    # один кандидат нужного цвета. Их пара различает три разных исхода,
    # которые снаружи выглядят одинаково как «цвет не помог»:
    #   pen~0            — рамка стоит на нужном цвете, виновато что-то другое;
    #   pen высок, best~0— цвет нашёл цель, но его перевесили: мал COLOR_PENALTY;
    #   pen и best высоки— цели нужного цвета в окне нет, цвет тут бессилен.
    if cmap is not None:
        _match_dbg["color_pen"] = float(cmap[my, mx])
        _match_dbg["color_best"] = float(cmap.min())
    else:
        _match_dbg["color_pen"] = None
        _match_dbg["color_best"] = None

    # Насколько пик ОДИНОК. Если рядом есть почти такой же по силе кандидат,
    # матч неоднозначен: на фактурном фоне таких кандидатов много, и матчер
    # уверенно садится не на ту деталь, сохраняя приличный score. Обычная
    # уверенность этого не показывает — нужен именно контраст пика с фоном
    # карты откликов (это классический peak-to-sidelobe ratio).
    try:
        sm = score_map.astype(np.float32)
        mask = np.ones(sm.shape, dtype=bool)
        # ПОДОЗРЕНИЕ (проверять отдельным опытом): радиус исключения
        # привязан к размеру КАРТЫ ОТКЛИКОВ, а карта растёт вместе с окном
        # поиска. Считая для реальных величин:
        #     медленная цель, окно 14 -> карта ~29 px -> радиус 4
        #     быстрая цель,   окно 29 -> карта ~59 px -> радиус 8
        # Если собственный пик шире 4 px, то на медленных кадрах в «лучшего
        # конкурента» попадает ПЛЕЧО ТОГО ЖЕ ПИКА, а не другой кандидат.
        # Это объяснило бы, почему защита срабатывает на 45% медленных кадров
        # и лишь на 9% быстрых — и почему уменьшение фона в шаблоне (проба
        # TEMPLATE_SCALE=1.3) на эту долю никак не повлияло.
        # Правильнее привязывать радиус к размеру ШАБЛОНА, а не карты.
        r = max(2, int(min(sm.shape) * 0.15))
        y0, y1 = max(0, my - r), min(sm.shape[0], my + r + 1)
        x0, x1 = max(0, mx - r), min(sm.shape[1], mx + r + 1)
        mask[y0:y1, x0:x1] = False           # исключаем окрестность пика
        side = sm[mask]
        if side.size > 8:
            sd = float(side.std())
            psr = (raw_score - float(side.mean())) / sd if sd > 1e-6 else 0.0
            second = float(side.max())
        else:
            psr, second = 0.0, 0.0
        _match_dbg["psr"] = psr
        _match_dbg["second"] = second
        _match_dbg["margin"] = float(margin)
    except Exception:
        _match_dbg["psr"] = None
        _match_dbg["second"] = None
        _match_dbg["margin"] = float(margin)

    # Субпиксельное уточнение пика: убирает пиксельную квантовку матчера
    # (точность теперь ~0.1 px вместо ±0.5 px), особенно важно с маленьким
    # DEADBAND_X/Y — снимает «дребезг» крестика на покоящейся цели.
    sub_dx, sub_dy = subpixel_peak(score_map, mx, my)
    new_cx = sx1 + mx + sub_dx + tmpl_w / 2.0
    new_cy = sy1 + my + sub_dy + tmpl_h / 2.0

    if raw_score < MATCH_MIN_SCORE:
        return False, pred_cx, pred_cy, raw_score
    if math.hypot(new_cx - pred_cx, new_cy - pred_cy) > MAX_LOCK_STEP:
        return False, pred_cx, pred_cy, raw_score
    return True, float(new_cx), float(new_cy), raw_score


def reset_tracking(to_acq=False):
    global track_state, target_visible, target_controllable, overlay_text, overlay_color, target_box_main
    global lock_cx, lock_cy, lock_w, lock_h, tmpl_w, tmpl_h, template_gray, template_std
    global template_base, target_uv, color_active, color_separation
    global color_axis
    global prev_gray, prev_pts, lost_frames, last_match_score, last_flow_ok
    global acq_wait_left
    global filtered_dx_yaw, prev_adx, prev_ady_ctrl
    global smooth_throttle_out, throttle_integral, prev_ady
    global roll_integral, pitch_integral, yaw_integral
    global smoothed_pitch_deg
    global prev_box_cx, prev_box_cy, target_vx_smoothed, target_vy_smoothed, stable_track_frames
    global launch_phase, launch_counter, prev_controllable_for_launch

    track_state = TRACK_STATE_ACQ if to_acq else TRACK_STATE_IDLE
    target_visible = False
    target_controllable = False
    overlay_text = "ACQ" if to_acq else "IDLE"
    overlay_color = COLOR_WHITE
    target_box_main = None

    lock_cx = lock_cy = lock_w = lock_h = None
    tmpl_w = tmpl_h = None
    # Ось цвета принадлежит КОНКРЕТНОМУ захвату: она снята с той цели, которую
    # указал оператор. Оставить её жить после потери лока — значит вести поиск
    # новой цели по проекции, снятой со старой, и вдобавок снимать следующую ось
    # с уже спроецированной картинки. Обе ошибки тихие.
    color_axis = None
    template_gray = None
    template_base = None
    target_uv = None
    color_active = False
    color_separation = 0.0
    template_std = 0.0
    prev_gray = None
    prev_pts = None
    lost_frames = 0
    last_match_score = 0.0
    last_flow_ok = False
    acq_wait_left = 0

    filtered_dx_yaw = 0.0
    prev_adx = 0.0
    prev_ady_ctrl = 0.0

    smooth_throttle_out = None
    throttle_integral = 0.0
    prev_ady = 0.0

    roll_integral = 0.0
    pitch_integral = 0.0
    yaw_integral = 0.0

    smoothed_pitch_deg = 0.0

    prev_box_cx = None
    prev_box_cy = None
    target_vx_smoothed = 0.0
    target_vy_smoothed = 0.0
    stable_track_frames = 0

    launch_phase = "NONE"
    launch_counter = 0
    prev_controllable_for_launch = False

# =========================================================
# 8. CONTROL — главные исправления здесь
# =========================================================
def _pid_axis_step(error, prev_error, integral, ff_value,
                   p_gain, d_gain, i_gain, ff_gain,
                   integral_max, integral_decay,
                   sign, max_deflect, dbg_key=None, k=1.0):
    """Один шаг PID+FF по одной оси с условным anti-windup.

    Anti-windup: I-компонент НЕ накапливается, если P+D+FF+I-выход уже
    саттурирован в том же направлении, в котором новая I-добавка его
    толкала бы дальше. Это предотвращает overshoot, когда цель наконец-то
    оказывается в зоне досягаемости.

    ff_value: упреждающий сигнал (обычно скорость цели в пикселях/кадр).
    ff_gain: коэффициент пересчёта ff_value в PWM-вклад.
    Если ff_gain=0 — FF выключен, ведёт себя как чистый PID.

    Возвращает (offset_clamped, new_prev_error, new_integral).
    """
    err_f = float(error)
    d_err = err_f - prev_error

    # D и FF делятся на k, I умножается: при удвоенной частоте кадров разница
    # между кадрами вдвое меньше (её надо вернуть к номиналу), а накоплений за
    # ту же секунду вдвое больше (каждое должно быть вдвое меньше).
    pd_part = err_f * p_gain + (d_err / k) * d_gain
    ff_part = (float(ff_value) / k) * ff_gain

    # Сначала смотрим, где бы оказался выход с ТЕКУЩИМ интегратором.
    total_unsat = sign * (pd_part + ff_part + integral)
    sat_pos = total_unsat >= max_deflect
    sat_neg = total_unsat <= -max_deflect
    # Знак, в котором новая I-добавка толкнула бы выход.
    i_dir = sign * err_f
    push_further = (sat_pos and i_dir > 0) or (sat_neg and i_dir < 0)

    if err_f != 0.0 and not push_further:
        integral += err_f * i_gain * k
        if integral > integral_max:
            integral = integral_max
        elif integral < -integral_max:
            integral = -integral_max
    integral *= integral_decay ** k

    out = sign * (pd_part + ff_part + integral)
    saturated = False
    if out > max_deflect:
        out = max_deflect
        saturated = True
    elif out < -max_deflect:
        out = -max_deflect
        saturated = True

    if dbg_key is not None:
        # Раздельно P, D, I и FF: по сумме не понять, кто именно увёл ось —
        # а это первый вопрос, когда наведение промахивается.
        _pid_dbg[dbg_key] = (err_f * p_gain, d_err * d_gain, integral,
                             ff_part, out, saturated)

    return out, err_f, integral


_alt_hist = collections.deque(maxlen=ALT_NOISE_WINDOW)


def _alt_sigma_cm():
    """Разброс показаний высотомера за последние секунды, см.

    ЗАМЕРЕНО на неподвижном столе: сигма 10.1 см, показания гуляли от -2 до
    40 см. Прежний порог годности 30 см — это всего три сигмы, и шум его
    регулярно переходил: трекер показывал уверенные «3.6 м» дальности,
    целиком собранные из дрожания барометра. Отсюда и берётся живая оценка.
    """
    n = len(_alt_hist)
    if n < ALT_NOISE_MIN_SAMPLES:
        return None
    m = sum(_alt_hist) / float(n)
    return math.sqrt(sum((v - m) ** 2 for v in _alt_hist) / float(n))


def _estimate_closure(box_w, box_h, box_cy, now_mono, k):
    """Оценка сближения с целью. Возвращает словарь измерений.

    tau_s     — время до контакта, с. Из скорости роста коробки; реальный
                размер цели не нужен, он сокращается в отношении.
    range_m   — дальность по земле до цели, м. Из высоты и угла визирования.
    depression_deg — угол снижения линии визирования ниже горизонта.

    Величина None означает «оценить нельзя», а не «ноль»: не сближаемся,
    нет высоты, слишком малый угол. Смешивать эти случаи с нулём нельзя —
    ноль дальности означал бы «мы в цели».
    """
    global prev_box_size_px, box_growth_smoothed
    out = {"size_px": None, "growth": None, "tau_s": None,
           "range_m": None, "depression_deg": None, "alt_min_m": None,
           "alt_reason": None}

    # --- время до контакта ---
    # Берём геометрическое среднее сторон: устойчивее к тому, что коробка
    # меняет пропорции при смене ракурса.
    size = math.sqrt(max(float(box_w), 1.0) * max(float(box_h), 1.0))
    out["size_px"] = size
    if prev_box_size_px is not None and prev_box_size_px > 0.0:
        # Относительный прирост за номинальный кадр.
        rel = ((size - prev_box_size_px) / prev_box_size_px) / k
        a = alpha_for_dt(TAU_GROWTH_ALPHA, k)
        box_growth_smoothed += a * (rel - box_growth_smoothed)
    prev_box_size_px = size
    out["growth"] = box_growth_smoothed
    if box_growth_smoothed > TAU_MIN_GROWTH:
        # Кадров до контакта -> секунд.
        out["tau_s"] = (1.0 / box_growth_smoothed) * NOMINAL_DT

    # --- дальность по наземной цели ---
    if not RANGE_ESTIMATE_ENABLED:
        return out
    with state_lock:
        alt_cm = app_state.get("alt_cm")
        alt_ts = app_state.get("alt_ts", 0.0)
        fc_pitch = app_state.get("fc_pitch_deg")
        armed = app_state.get("armed")
    if alt_cm is None or fc_pitch is None or (now_mono - alt_ts) > 1.0:
        return out
    # БЕЗ АРМА ВЫСОТЫ НЕТ ВОВСЕ. Опросник tools/baro_probe.py показал прямо:
    # без арма вариометр РОВНО ноль во всех отсчётах, а высота стоит на
    # -44/-52 см и не двигается. Оценщик высоты в Betaflight попросту не
    # работает до арма. Под армом он оживает: размах 199 см, вариометр до
    # 1.5 м/с.
    #
    # Раньше это спасало случайно: разброс замороженных значений мал, планка
    # годности упиралась в нижний предел 0.5 м, и отрицательная высота её не
    # проходила. Полагаться на такое совпадение нельзя — проверяем прямо.
    if not armed:
        out["alt_reason"] = "no arm"
        return out

    # Угол цели относительно оси камеры: пиксели -> градусы.
    deg_per_px = CAMERA_VFOV_DEG / float(MAIN_H)
    off_deg = (float(box_cy) - CENTER_Y) * deg_per_px   # вниз по кадру = вниз
    # ЗНАК ТАНГАЖА УСТАНОВЛЕН ПО ЗАМЕРУ, а не по догадке. Два независимых
    # факта сходятся:
    #   1. Оператор подтвердил: картинка, которую получает трекер, НЕ
    #      перевёрнута — небо сверху. Значит низ кадра это низ мира.
    #   2. Замерено по заходу 141912: цель в кадре смещается на -12.2 px на
    #      каждый +1° тангажа (r=-0.92). При неперевёрнутой картинке цель
    #      уезжает ВВЕРХ, когда нос идёт ВНИЗ.
    # Следовательно рост тангажа от FC = НОС ВНИЗ, и прежний комментарий
    # ('нос вниз приходит отрицательным') был неверен: угол снижения
    # считался зеркально, дальность вышла бы к цели ПОЗАДИ нас.
    #
    # Сходится и с самим заходом: оператор нёс дрон, наклонив к цели, тангаж
    # был +14°, а код объявлял это взглядом на 14° ВЫШЕ горизонта.
    depression = float(fc_pitch) - CAMERA_TILT_DEG + off_deg
    out["depression_deg"] = depression

    alt_m = alt_cm / 100.0
    # Годность высоты — от ИЗМЕРЕННОГО шума барометра, а не от круглого числа.
    # Ошибка дальности повторяет ошибку высоты один в один (dR/R = dH/H),
    # поэтому пять сигм дают около 20% по дальности. На столе это условие не
    # выполняется никогда — и правильно: там дальности нет.
    sigma = app_state.get("alt_sigma_cm")
    min_alt_m = RANGE_MIN_ALT_FLOOR_M
    if sigma is not None:
        min_alt_m = max(min_alt_m, RANGE_ALT_SIGMAS * sigma / 100.0)
    out["alt_min_m"] = min_alt_m
    if depression >= RANGE_MIN_DEPRESSION_DEG and alt_m > min_alt_m:
        out["range_m"] = alt_m / math.tan(math.radians(depression))
    return out


def _pitch_comp_selfcheck(fc_pitch, box_cy, dy_aim):
    """Проверка самой компенсации: гасит она наклон или складывается с ним.

    Считаем наклон зависимости прицела от тангажа. Если компенсация верна,
    dy_aim почти не зависит от тангажа — цель уезжает, а прицельная точка
    стоит. Если знак не тот, dy_aim выходит примерно вдвое круче цели.

    Считается по накоплению сумм, без хранения истории: ~1 мкс на кадр.
    """
    global _pcs_n, _pcs_sx, _pcs_sxx, _pcs_sy, _pcs_sxy, _pcs_sz, _pcs_sxz
    _pcs_n += 1
    _pcs_sx += fc_pitch
    _pcs_sxx += fc_pitch * fc_pitch
    _pcs_sy += box_cy
    _pcs_sxy += fc_pitch * box_cy
    _pcs_sz += dy_aim
    _pcs_sxz += fc_pitch * dy_aim
    if _pcs_n < PITCH_COMP_SELFCHECK_FRAMES:
        return
    den = _pcs_n * _pcs_sxx - _pcs_sx * _pcs_sx
    if den > 1e-6:
        k_tgt = (_pcs_n * _pcs_sxy - _pcs_sx * _pcs_sy) / den
        k_aim = (_pcs_n * _pcs_sxz - _pcs_sx * _pcs_sz) / den
        if abs(k_tgt) < 0.5:
            verdict = "наклона почти не было, судить не по чему"
        elif abs(k_aim) <= abs(k_tgt) * 0.5:
            verdict = "ГАСИТ"
        elif abs(k_aim) >= abs(k_tgt) * 1.5:
            verdict = "СКЛАДЫВАЕТСЯ — знак не тот"
        else:
            verdict = "гасит частично"
        flight_log.event(
            "КОМПЕНСАЦИЯ ТАНГАЖА: цель %+.2f px/°, прицел %+.2f px/° -> %s"
            % (k_tgt, k_aim, verdict))
    _pcs_n = 0
    _pcs_sx = _pcs_sxx = _pcs_sy = _pcs_sxy = _pcs_sz = _pcs_sxz = 0.0


def _pitch_angle_hold_pwm(target_deg, now_mono, k):
    """Команда тангажа, удерживающая ЗАДАННЫЙ УГОЛ наклона носа.

    Квад летит в ACRO: стик задаёт угловую СКОРОСТЬ. Чтобы получить угол,
    нужен внешний контур — он здесь и реализован, по реальному тангажу из
    MSP_ATTITUDE.

    Знак: нос вниз приходит от FC отрицательным (см. блок про MSP_ATTITUDE),
    поэтому цель тоже берётся отрицательной. К выходу применяется
    PITCH_PWM_TO_FC_ANGLE_SIGN, а НЕ PITCH_SIGN: последний описывает связь
    «пиксели -> PWM» и зависит от ориентации камеры, которая здесь ни при чём.

    Возвращает (pwm_offset, достигнут_ли_угол). Без свежего тангажа выдаёт 0:
    разомкнутый вариант — это ровно та ошибка, от которой уходим, и лучше не
    дать разгона совсем, чем крутить квад вслепую.
    """
    global prev_launch_pitch_deg
    with state_lock:
        fc_pitch = app_state.get("fc_pitch_deg")
        fc_ts = app_state.get("fc_pitch_ts", 0.0)

    if fc_pitch is None or (now_mono - fc_ts) > LAUNCH_ATT_TIMEOUT:
        prev_launch_pitch_deg = None
        return 0.0, False

    cur = float(fc_pitch)
    err = (-abs(target_deg)) - cur      # цель «нос вниз» в единицах FC

    d_term = 0.0
    if prev_launch_pitch_deg is not None:
        # Скорость изменения угла, приведённая к номинальному кадру.
        d_term = -((cur - prev_launch_pitch_deg) / k) * LAUNCH_ANGLE_D
    prev_launch_pitch_deg = cur

    out = PITCH_PWM_TO_FC_ANGLE_SIGN * (err * LAUNCH_ANGLE_P + d_term)
    if out > LAUNCH_MAX_PWM:
        out = LAUNCH_MAX_PWM
    elif out < -LAUNCH_MAX_PWM:
        out = -LAUNCH_MAX_PWM
    return out, abs(err) <= 2.0


def _compute_pitch_attitude_comp_px(now_mono, k=1.0):
    """Возвращает (compensation_px, обновлено?). Compensation добавляется
    к aim_y. Положительное значение = aim сдвигается ВНИЗ в кадре (бóльшая y),
    что соответствует ситуации «квад завален носом вниз → цель в кадре сверху,
    но это нормально для текущей траектории».

    Использует и обновляет глобал smoothed_pitch_deg.
    """
    global smoothed_pitch_deg
    if not PITCH_ATTITUDE_COMP_ENABLED:
        return 0.0

    with state_lock:
        fc_pitch = app_state.get("fc_pitch_deg")
        fc_pitch_ts = app_state.get("fc_pitch_ts", 0.0)

    if fc_pitch is None or (now_mono - fc_pitch_ts) > FC_PITCH_TIMEOUT:
        return 0.0

    smoothed_pitch_deg += alpha_for_dt(PITCH_COMP_ALPHA, k) * (
        float(fc_pitch) - smoothed_pitch_deg)
    comp_px = PITCH_COMP_SIGN * smoothed_pitch_deg * PIXELS_PER_PITCH_DEG
    if comp_px > MAX_PITCH_COMP_PX:
        comp_px = MAX_PITCH_COMP_PX
    elif comp_px < -MAX_PITCH_COMP_PX:
        comp_px = -MAX_PITCH_COMP_PX
    return comp_px


def update_control_from_target():
    """Roll/Pitch/Yaw — P+D+I через _pid_axis_step с anti-windup.
       Прицельная точка по pitch учитывает текущий тангаж квада (MSP_ATTITUDE).
       Throttle:
         - OVERRIDE_THROTTLE=False (default) → target_throttle = live стик.
         - OVERRIDE_THROTTLE=True            → P+I+D по dy ОТ ЦЕНТРА КОРОБКИ
           (без AIM_OFFSET_Y, иначе I унесёт газ к нулю).

       Реальная отправка на FC решается в fc_io_loop по флагам OVERRIDE_*.
    """
    global global_yaw_cmd, global_pitch_cmd, global_roll_cmd, global_throttle_cmd, override_active
    global filtered_dx_yaw, prev_adx, prev_ady_ctrl
    global smooth_throttle_out, throttle_integral, prev_ady
    global roll_integral, pitch_integral, yaw_integral
    global smoothed_pitch_deg
    global prev_box_cx, prev_box_cy, target_vx_smoothed, target_vy_smoothed, stable_track_frames
    global launch_phase, launch_counter, prev_controllable_for_launch
    global overlay_text, overlay_color, _ctl_dbg, prev_control_mono
    global prev_launch_pitch_deg, prev_box_size_px, box_growth_smoothed

    with state_lock:
        box = target_box_main
        controllable = target_controllable
        live_thr = app_state.get("rc_throttle", 1500)
        live_thr_ts = app_state.get("rc_throttle_ts", 0.0)

    now_mono = time.monotonic()
    # Фактическая длительность кадра в единицах номинального (k=1 при 30 к/с).
    k = dt_ratio(None if prev_control_mono is None
                 else now_mono - prev_control_mono)
    prev_control_mono = now_mono
    # ОПОРНЫЙ ГАЗ — это стик пилота, и только он.
    #
    # Раньше при неактуальном RC сюда подставлялся dyn_throttle, то есть
    # СОБСТВЕННЫЙ выход прошлого кадра: target = base + поправка, затем
    # dyn_throttle = target, а на следующем кадре base = dyn_throttle. Газ
    # накручивал сам себя и упирался в 2000 — на борту это выглядело как
    # «при локе газ уходит в 100%», причём даже при стике на минимуме и при
    # нулевой поправке регулятора (thr_adj=0 в логах).
    #
    # Во время оверрайда стик законно «замирает»: Betaflight не отдаёт сырой
    # приёмник по подменяемым каналам. Замерший стик пилота — корректная
    # опора, а вот собственный выход опорой быть не может никогда.
    rc_valid = (885 <= int(live_thr) <= 2115) and live_thr_ts > 0.0
    base_thr = int(live_thr) if rc_valid else THROTTLE_MIN_PWM
    rc_fresh = rc_valid and ((now_mono - live_thr_ts) <= RC_FRESH_WINDOW)
    if base_thr < THROTTLE_MIN_PWM:
        base_thr = THROTTLE_MIN_PWM
    elif base_thr > THROTTLE_MAX_PWM:
        base_thr = THROTTLE_MAX_PWM

    if not controllable or box is None:
        # Сбрасываем ВСЕ накопители, иначе windup из прошлой сессии вылезет
        # на следующем TRACKED-кадре как «моторы сами раскрутились».
        filtered_dx_yaw = 0.0
        prev_adx = 0.0
        prev_ady_ctrl = 0.0
        prev_ady = 0.0
        smooth_throttle_out = None
        throttle_integral = 0.0
        roll_integral = 0.0
        pitch_integral = 0.0
        yaw_integral = 0.0
        smoothed_pitch_deg = 0.0
        prev_control_mono = None
        prev_launch_pitch_deg = None
        # Оценку сближения тоже сбрасываем: размер коробки после нового
        # захвата не связан с прежним, и прирост между ними — мусор.
        prev_box_size_px = None
        box_growth_smoothed = 0.0
        prev_box_cx = None
        prev_box_cy = None
        target_vx_smoothed = 0.0
        target_vy_smoothed = 0.0
        stable_track_frames = 0
        # Launch тоже сбрасывается — следующее controllable=True переоткроет манёвр.
        launch_phase = "NONE"
        launch_counter = 0
        prev_controllable_for_launch = False
        with state_lock:
            app_state["dyn_throttle"] = base_thr
            override_active = False
            global_roll_cmd = 1500.0
            global_pitch_cmd = 1500.0
            global_yaw_cmd = 1500.0
            global_throttle_cmd = base_thr
        # Кадр без управления — тоже данные: по ним видно, сколько времени
        # наведение простояло и в каком состоянии, вместо дыры в логе.
        _ctl_dbg = {"active": False, "base_thr": base_thr}
        return

    # --- Геометрия. РАЗДЕЛЬНЫЕ dy для pitch и для газа. ---
    box_cx = (box[0] + box[2]) / 2.0
    box_cy = (box[1] + box[3]) / 2.0

    # --- Launch state machine ---
    # Триггер: первый кадр, в котором мы controllable, после серии не-controllable
    # кадров (новый LOCK / возобновление после LOST). Прогон по фазам идёт
    # каждый кадр, не привязан к содержимому коробки или к ошибкам.
    trigger_launch = LAUNCH_ENABLED and not prev_controllable_for_launch
    prev_controllable_for_launch = True

    if trigger_launch:
        launch_phase = "RAMP_UP"
        launch_counter = 0

    launch_intensity = 0.0
    if launch_phase == "RAMP_UP":
        launch_intensity = launch_counter / float(max(LAUNCH_RAMP_UP_FRAMES, 1))
        if launch_intensity > 1.0:
            launch_intensity = 1.0
        # Шаг счётчика — k, а не 1: иначе при 60 к/с фаза launch проходила бы
        # вдвое быстрее по времени, чем задано константами.
        launch_counter += k
        if launch_counter >= LAUNCH_RAMP_UP_FRAMES:
            launch_phase = "HOLD"
            launch_counter = 0
    elif launch_phase == "HOLD":
        launch_intensity = 1.0
        launch_counter += k
        if launch_counter >= LAUNCH_HOLD_FRAMES:
            launch_phase = "RAMP_DOWN"
            launch_counter = 0
    elif launch_phase == "RAMP_DOWN":
        launch_intensity = 1.0 - launch_counter / float(max(LAUNCH_RAMP_DOWN_FRAMES, 1))
        if launch_intensity < 0.0:
            launch_intensity = 0.0
        launch_counter += k
        if launch_counter >= LAUNCH_RAMP_DOWN_FRAMES:
            launch_phase = "NONE"
            launch_counter = 0
            launch_intensity = 0.0
    # else: NONE — launch_intensity остаётся 0

    # Целевой угол: launch_intensity плавно поднимает его от 0 до
    # LAUNCH_TARGET_PITCH_DEG и так же плавно возвращает. Плавность теперь
    # относится к УГЛУ, а не к скорости вращения — поэтому раньше «плавный»
    # разгон и возврат и получались рывками.
    launch_pitch_pwm = 0.0
    cruise_pitch_pwm = 0.0
    launch_angle_reached = False
    if launch_intensity > 0.0:
        launch_pitch_pwm, launch_angle_reached = _pitch_angle_hold_pwm(
            LAUNCH_TARGET_PITCH_DEG * launch_intensity, now_mono, k)
    elif CRUISE_ENABLED and launch_phase == "NONE":
        cruise_pitch_pwm, _ = _pitch_angle_hold_pwm(
            CRUISE_TARGET_PITCH_DEG, now_mono, k)

    # --- Упреждение по скорости цели ---
    # Считаем межкадровую скорость, прогоняем через фильтр, отбрасываем глитчи.
    # Применяется только после LEAD_MIN_STABLE_FRAMES — даём фильтру стабилизироваться.
    lead_x = 0.0
    lead_y = 0.0
    if prev_box_cx is not None and prev_box_cy is not None:
        inst_vx = box_cx - prev_box_cx
        inst_vy = box_cy - prev_box_cy
        # Глитч-фильтр: re-lock / occlusion даёт скачок сильно больше реальной скорости цели.
        if abs(inst_vx) < LEAD_MAX_VEL_JUMP and abs(inst_vy) < LEAD_MAX_VEL_JUMP:
            # Мгновенная скорость измерена в пикселях ЗА КАДР; приводим к
            # номинальному кадру, иначе при 60 к/с она вдвое меньше при той же
            # физической скорости цели.
            a_vel = alpha_for_dt(LEAD_VEL_ALPHA, k)
            target_vx_smoothed += a_vel * (inst_vx / k - target_vx_smoothed)
            target_vy_smoothed += a_vel * (inst_vy / k - target_vy_smoothed)
            stable_track_frames += k
        else:
            # Подозрительный скачок — сбрасываем счётчик стабильности.
            stable_track_frames = 0
    prev_box_cx = box_cx
    prev_box_cy = box_cy

    if LEAD_AIM_ENABLED and stable_track_frames >= LEAD_MIN_STABLE_FRAMES and LEAD_FRAMES > 0:
        # target_v* уже приведены к номинальному кадру, поэтому горизонт
        # LEAD_FRAMES тоже трактуется в номинальных кадрах = фиксированное
        # время (LEAD_FRAMES/30 с), независимо от текущего FPS.
        lead_x = target_vx_smoothed * float(LEAD_FRAMES)
        lead_y = target_vy_smoothed * float(LEAD_FRAMES)
        # Жёсткий потолок чтобы шумы по скорости не унесли прицел через полкадра.
        if lead_x > LEAD_MAX_PX:
            lead_x = LEAD_MAX_PX
        elif lead_x < -LEAD_MAX_PX:
            lead_x = -LEAD_MAX_PX
        if lead_y > LEAD_MAX_PX:
            lead_y = LEAD_MAX_PX
        elif lead_y < -LEAD_MAX_PX:
            lead_y = -LEAD_MAX_PX

    # Динамическая компенсация наклона квада.
    pitch_comp_px = _compute_pitch_attitude_comp_px(now_mono, k)

    # Прицельная точка: текущая позиция + статический оффсет + компенсация тангажа + упреждение.
    dx_aim = (box_cx + AIM_OFFSET_X + lead_x) - CENTER_X
    dy_aim = (box_cy + AIM_OFFSET_Y + pitch_comp_px + lead_y) - CENTER_Y

    with state_lock:
        _fcp = app_state.get("fc_pitch_deg")
    if _fcp is not None:
        _pitch_comp_selfcheck(float(_fcp), float(box_cy), float(dy_aim))

    # Для газа — чистая позиция коробки, БЕЗ AIM_OFFSET, БЕЗ компенсации, БЕЗ упреждения.
    # Высоту мы корректируем по реальному положению цели, а не по предсказанному.
    dy_alt = box_cy - CENTER_Y

    adx = 0.0 if abs(dx_aim) < DEADBAND_X else (dx_aim - DEADBAND_X if dx_aim > 0 else dx_aim + DEADBAND_X)
    ady = 0.0 if abs(dy_aim) < DEADBAND_Y else (dy_aim - DEADBAND_Y if dy_aim > 0 else dy_aim + DEADBAND_Y)

    # --- Терминальный режим: близко к цели — другие гэйны ---
    # Когда коробка занимает заметную часть кадра, мы в финальных секундах.
    # Поднимаем P (нужны рефлексы), срезаем I (нет времени интегрировать),
    # чуть повышаем FF (резче следуем за движением цели).
    box_w_main = box[2] - box[0]
    box_h_main = box[3] - box[1]
    box_frac = (box_w_main * box_h_main) / float(MAIN_W * MAIN_H)
    in_terminal = TERMINAL_MODE_ENABLED and box_frac >= TERMINAL_BOX_FRAC_THRESHOLD

    # Оценка сближения. Пока ТОЛЬКО измеряется и пишется в лог — в закон
    # управления не входит (см. блок про оценку сближения выше).
    closure = _estimate_closure(box_w_main, box_h_main, box_cy, now_mono, k)

    if in_terminal:
        p_roll_eff = P_GAIN_ROLL * TERMINAL_P_MULTIPLIER
        p_pitch_eff = P_GAIN_PITCH * TERMINAL_P_MULTIPLIER
        i_roll_eff = I_GAIN_ROLL * TERMINAL_I_MULTIPLIER
        i_pitch_eff = I_GAIN_PITCH * TERMINAL_I_MULTIPLIER
        ff_roll_eff = FF_GAIN_ROLL * TERMINAL_FF_MULTIPLIER
        ff_pitch_eff = FF_GAIN_PITCH * TERMINAL_FF_MULTIPLIER
        ff_yaw_eff = FF_GAIN_YAW * TERMINAL_FF_MULTIPLIER
    else:
        p_roll_eff = P_GAIN_ROLL
        p_pitch_eff = P_GAIN_PITCH
        i_roll_eff = I_GAIN_ROLL
        i_pitch_eff = I_GAIN_PITCH
        ff_roll_eff = FF_GAIN_ROLL
        ff_pitch_eff = FF_GAIN_PITCH
        ff_yaw_eff = FF_GAIN_YAW

    # --- ROLL: P+D+I+FF через хелпер с anti-windup ---
    roll_offset, prev_adx, roll_integral = _pid_axis_step(
        adx, prev_adx, roll_integral,
        target_vx_smoothed,
        p_roll_eff, D_GAIN_ROLL, i_roll_eff, ff_roll_eff,
        ROLL_INTEGRAL_MAX, ROLL_INTEGRAL_DECAY,
        ROLL_SIGN, MAX_ROLL_DEFLECT, dbg_key="roll", k=k,
    )
    target_roll = max(1000, min(2000, 1500 + roll_offset))

    # --- PITCH: P+D+I+FF через хелпер с anti-windup ---
    pitch_offset, prev_ady_ctrl, pitch_integral = _pid_axis_step(
        ady, prev_ady_ctrl, pitch_integral,
        target_vy_smoothed,
        p_pitch_eff, D_GAIN_PITCH, i_pitch_eff, ff_pitch_eff,
        PITCH_INTEGRAL_MAX, PITCH_INTEGRAL_DECAY,
        PITCH_SIGN, MAX_PITCH_DEFLECT, dbg_key="pitch", k=k,
    )
    # Поверх PID — launch boost и cruise. Они могут вытолкнуть target_pitch
    # за MAX_PITCH_DEFLECT, но финальный clamp 1000-2000 остаётся.
    combined_pitch = pitch_offset + launch_pitch_pwm + cruise_pitch_pwm
    target_pitch = max(1000, min(2000, 1500 + combined_pitch))

    # --- YAW: фильтр + ослабление при больших adx + I + FF с anti-windup ---
    # Yaw не использует хелпер потому что error — это filtered_dx_yaw × yaw_weight,
    # а I-добавка тоже взвешивается. Логика та же, но с весом.
    filtered_dx_yaw += alpha_for_dt(YAW_FILTER_ALPHA, k) * (float(adx) - filtered_dx_yaw)
    abs_adx = abs(adx)
    if abs_adx < YAW_ROLL_CROSSOVER:
        yaw_weight = 1.0
    else:
        yaw_weight = max(0.3, 1.0 - (abs_adx - YAW_ROLL_CROSSOVER) / max(YAW_ROLL_BLEND_RANGE, 1.0))

    yaw_error_weighted = filtered_dx_yaw * yaw_weight
    yaw_pd = yaw_error_weighted * P_GAIN_YAW
    yaw_ff = target_vx_smoothed * ff_yaw_eff * yaw_weight
    yaw_total_unsat = YAW_SIGN * (yaw_pd + yaw_ff + yaw_integral)
    yaw_sat_pos = yaw_total_unsat >= MAX_YAW_DEFLECT
    yaw_sat_neg = yaw_total_unsat <= -MAX_YAW_DEFLECT
    yaw_i_dir = YAW_SIGN * yaw_error_weighted
    yaw_push_further = (yaw_sat_pos and yaw_i_dir > 0) or (yaw_sat_neg and yaw_i_dir < 0)
    if adx != 0 and not yaw_push_further:
        yaw_integral += yaw_error_weighted * I_GAIN_YAW * k
        if yaw_integral > YAW_INTEGRAL_MAX:
            yaw_integral = YAW_INTEGRAL_MAX
        elif yaw_integral < -YAW_INTEGRAL_MAX:
            yaw_integral = -YAW_INTEGRAL_MAX
    yaw_integral *= YAW_INTEGRAL_DECAY ** k

    yaw_offset = YAW_SIGN * (yaw_pd + yaw_ff + yaw_integral)
    if yaw_offset > MAX_YAW_DEFLECT:
        yaw_offset = MAX_YAW_DEFLECT
    elif yaw_offset < -MAX_YAW_DEFLECT:
        yaw_offset = -MAX_YAW_DEFLECT
    target_yaw = max(1000, min(2000, 1500 + yaw_offset))

    # --- THROTTLE ---
    thr_adjust = 0.0
    if not OVERRIDE_THROTTLE:
        target_throttle = base_thr
        smooth_throttle_out = float(base_thr)
        throttle_integral = 0.0
        prev_ady = float(dy_alt)
    else:
        # Динамика по dy_alt (БЕЗ AIM_OFFSET).
        thr_adjust = 0.0
        if abs(dy_alt) > THROTTLE_DEADBAND:
            active_dy = float(dy_alt - THROTTLE_DEADBAND if dy_alt > 0 else dy_alt + THROTTLE_DEADBAND)
            thr_adjust += -active_dy * DY_THROTTLE_GAIN
            throttle_integral += -active_dy * DY_INTEGRAL_RATE * k
            throttle_integral = max(-DY_INTEGRAL_MAX, min(DY_INTEGRAL_MAX, throttle_integral))
        else:
            throttle_integral *= 0.85 ** k

        throttle_integral *= DY_INTEGRAL_DECAY ** k
        thr_adjust += throttle_integral

        d_dy = float(dy_alt) - prev_ady
        prev_ady = float(dy_alt)
        thr_adjust += (d_dy / k) * DY_THROTTLE_D_GAIN

        max_adj = max(30.0, base_thr * THROTTLE_PERCENT / 100.0)
        thr_adjust = max(-max_adj, min(max_adj, thr_adjust))

        raw_throttle = base_thr + thr_adjust
        raw_throttle = max(THROTTLE_MIN_PWM, min(THROTTLE_MAX_PWM, raw_throttle))

        if smooth_throttle_out is None:
            smooth_throttle_out = float(raw_throttle)
        else:
            smooth_throttle_out += alpha_for_dt(THROTTLE_OUT_ALPHA, k) * (
                raw_throttle - smooth_throttle_out)
        target_throttle = int(round(smooth_throttle_out))
        target_throttle = max(THROTTLE_MIN_PWM, min(THROTTLE_MAX_PWM, target_throttle))

    # Launch throttle boost — применяется ТОЛЬКО при OVERRIDE_THROTTLE=True,
    # чтобы не наступать на ручное управление пилота.
    if OVERRIDE_THROTTLE and launch_intensity > 0.0 and LAUNCH_THR_BOOST_PCT > 0.0:
        # Буст считается от опорного стика пилота. Пока base_thr брался из
        # собственного выхода, буст начислялся на уже забустованное значение —
        # это давало не прибавку в 10%, а экспоненциальный разгон до упора.
        boost = base_thr * (LAUNCH_THR_BOOST_PCT / 100.0) * launch_intensity
        boosted = target_throttle + boost
        if boosted > THROTTLE_MAX_PWM:
            boosted = THROTTLE_MAX_PWM
        elif boosted < THROTTLE_MIN_PWM:
            boosted = THROTTLE_MIN_PWM
        target_throttle = int(round(boosted))

    # Индикация фазы launch в overlay (имеет приоритет над TRACKED/LOCK).
    if launch_phase in ("RAMP_UP", "HOLD", "RAMP_DOWN"):
        with state_lock:
            overlay_text = "LAUNCH"
            overlay_color = COLOR_CYAN

    with state_lock:
        app_state["dyn_throttle"] = target_throttle
        # В режиме наблюдения оверрайд не включается НИКОГДА — см. пояснение
        # у OBSERVE_ONLY. Иначе MSP_RC вернёт наши же значения вместо стиков.
        override_active = not OBSERVE_ONLY
        global_roll_cmd = target_roll
        global_pitch_cmd = target_pitch
        global_yaw_cmd = target_yaw
        global_throttle_cmd = target_throttle

    # Снимок для лога. Собирается здесь, потому что это единственное место, где
    # видны все промежуточные величины сразу; снаружи их уже не восстановить.
    r_p, r_d, r_i, r_ff, r_off, r_sat = _pid_dbg.get("roll", (0.0,) * 5 + (False,))
    p_p, p_d, p_i, p_ff, p_off, p_sat = _pid_dbg.get("pitch", (0.0,) * 5 + (False,))
    _ctl_dbg = {
        "active": True,
        "box_cx": box_cx, "box_cy": box_cy,
        "box_w": box_w_main, "box_h": box_h_main, "box_frac": box_frac,
        "dx_raw": box_cx - CENTER_X, "dy_raw": box_cy - CENTER_Y,
        "comp": pitch_comp_px, "lead_x": lead_x, "lead_y": lead_y,
        "dx_aim": dx_aim, "dy_aim": dy_aim, "adx": adx, "ady": ady,
        "dy_alt": dy_alt,
        "tgt_vx": target_vx_smoothed, "tgt_vy": target_vy_smoothed,
        "stable": stable_track_frames, "terminal": in_terminal,
        "roll_p": r_p, "roll_d": r_d, "roll_i": r_i, "roll_ff": r_ff,
        "roll_off": r_off, "roll_sat": r_sat,
        "pitch_p": p_p, "pitch_d": p_d, "pitch_i": p_i, "pitch_ff": p_ff,
        "pitch_off": p_off, "pitch_sat": p_sat,
        "launch_pwm": launch_pitch_pwm, "cruise_pwm": cruise_pitch_pwm,
        "pitch_comb": combined_pitch,
        "yaw_filt": filtered_dx_yaw, "yaw_weight": yaw_weight,
        "yaw_pd": yaw_pd, "yaw_ff": yaw_ff, "yaw_i": yaw_integral,
        "yaw_off": yaw_offset,
        "yaw_sat": abs(yaw_offset) >= MAX_YAW_DEFLECT,
        "base_thr": base_thr, "thr_adjust": thr_adjust,
        "thr_i": throttle_integral, "rc_fresh": rc_fresh,
        "launch_phase": launch_phase, "launch_int": launch_intensity,
        # Целевой угол разгона и признак его достижения: по ним видно,
        # вышел ли квад на угол или контур всё ещё догоняет.
        "launch_target_deg": LAUNCH_TARGET_PITCH_DEG * launch_intensity,
        "launch_reached": launch_angle_reached,
        "k": k,
        "size_px": closure["size_px"], "growth": closure["growth"],
        "tau_s": closure["tau_s"], "range_m": closure["range_m"],
        "depression_deg": closure["depression_deg"],
        # Вертикальная ошибка газа, ОЧИЩЕННАЯ от собственного наклона.
        # Сейчас регулятор газа работает по сырому dy_alt, и наклон носа он
        # читает как «цель ушла вверх» — то есть разгон сам себе подкручивает
        # газ. Пишем очищенный вариант рядом, чтобы на живых заходах увидеть,
        # насколько это расходится, прежде чем менять закон управления.
        "dy_alt_decoupled": dy_alt + pitch_comp_px,
        "alt_min_m": closure["alt_min_m"],
        "alt_reason": closure["alt_reason"],
    }

# =========================================================
# 9. DRAWING
# =========================================================
def draw_crosshair(frame):
    cv2.line(frame, (CENTER_X-12, CENTER_Y), (CENTER_X-4, CENTER_Y), CROSS_COLOR, 1)
    cv2.line(frame, (CENTER_X+4, CENTER_Y), (CENTER_X+12, CENTER_Y), CROSS_COLOR, 1)
    cv2.line(frame, (CENTER_X, CENTER_Y-12), (CENTER_X, CENTER_Y-4), CROSS_COLOR, 1)
    cv2.line(frame, (CENTER_X, CENTER_Y+4), (CENTER_X, CENTER_Y+12), CROSS_COLOR, 1)
    cv2.circle(frame, (CENTER_X, CENTER_Y), 1, CROSS_COLOR, -1)


def draw_corners(frame, box, color, thickness=2):
    x1, y1, x2, y2 = box
    bcx, bcy = (x1 + x2) // 2, (y1 + y2) // 2
    DIAMOND_R = 14
    pts = np.array([
        [bcx, bcy - DIAMOND_R],
        [bcx + DIAMOND_R, bcy],
        [bcx, bcy + DIAMOND_R],
        [bcx - DIAMOND_R, bcy],
    ], dtype=np.int32).reshape((-1, 1, 2))
    cv2.polylines(frame, [pts], True, COLOR_WHITE, 2, cv2.LINE_8)


def draw_magnifier(frame, box=None):
    """Лупа в углу. Центрируется на РАМКЕ ЦЕЛИ, а не на прицеле.

    Смысл лупы — разглядеть цель. Пока лупа висела на прицеле, она была
    полезна ровно до тех пор, пока рамка с прицелом совпадают, — а нужнее
    всего она как раз в момент их расхождения, когда наведение не поспевает.
    Тогда она показывала пустое место рядом с целью.

    Прицел при этом не теряется: если он попадает в увеличенный участок, он
    рисуется отдельной меткой. Так в лупе сразу видно и цель, и куда наведён
    аппарат, то есть увеличенная ошибка прицеливания.
    """
    if not MAG_ENABLED:
        return
    h, w = frame.shape[:2]
    src = max(MAG_SRC_MIN_SIZE, int(round(MAG_SIZE / MAG_ZOOM)))
    if box is not None:
        cx = (box[0] + box[2]) // 2
        cy = (box[1] + box[3]) // 2
    else:
        cx, cy = CENTER_X, CENTER_Y
    sx1 = max(0, cx - src // 2)
    sy1 = max(0, cy - src // 2)
    sx2 = min(w, sx1 + src)
    sy2 = min(h, sy1 + src)
    sx1 = max(0, sx2 - src)
    sy1 = max(0, sy2 - src)
    roi = frame[sy1:sy2, sx1:sx2].copy()
    if roi.size == 0:
        return
    zoom = cv2.resize(roi, (MAG_SIZE, MAG_SIZE), interpolation=cv2.INTER_LINEAR)
    dx2 = w - MAG_MARGIN
    dy1 = MAG_MARGIN
    dx1 = dx2 - MAG_SIZE
    dy2 = dy1 + MAG_SIZE
    if dx1 >= 0 and dy2 <= h:
        frame[dy1:dy2, dx1:dx2] = zoom
        scale = MAG_SIZE / float(src)
        # Центр лупы — центр рамки (или прицел, если рамки нет).
        mx, my = (dx1 + dx2) // 2, (dy1 + dy2) // 2
        cv2.line(frame, (mx-4, my), (mx+4, my), COLOR_RED, 1)
        cv2.line(frame, (mx, my-4), (mx, my+4), COLOR_RED, 1)
        if box is not None:
            # Прицел внутри увеличенного участка — видно ошибку наведения.
            px = int(dx1 + (CENTER_X - sx1) * scale)
            py = int(dy1 + (CENTER_Y - sy1) * scale)
            if dx1 <= px < dx2 and dy1 <= py < dy2:
                cv2.line(frame, (px-6, py), (px+6, py), COLOR_WHITE, 1)
                cv2.line(frame, (px, py-6), (px, py+6), COLOR_WHITE, 1)


def _range_readout_lines():
    """Строки телеметрии сближения для показа у рамки.

    Подписи ЛАТИНИЦЕЙ намеренно: шрифты OpenCV (FONT_HERSHEY_*) кириллицы не
    знают и рисуют вместо неё знаки вопроса — проверено, «Дальность»
    получается как «??????????????????».

    Когда величину измерить нельзя, показывается ПРИЧИНА, а не прочерк.
    Разница между «далеко» и «нечем мерить» — именно то, ради чего эти
    величины и считаются; замазать её одинаковым прочерком значит потерять
    единственное, что здесь можно узнать.
    """
    c = _ctl_dbg
    lines = []

    rng = c.get("range_m")
    if rng is not None:
        lines.append(("R %.0fm" % rng, COLOR_GREEN))
    else:
        # Разбираем, чего именно не хватило: высоты, свежести высоты или угла.
        with state_lock:
            alt_cm = app_state.get("alt_cm")
            alt_ts = app_state.get("alt_ts", 0.0)
            fc_pitch = app_state.get("fc_pitch_deg")
        dep = c.get("depression_deg")
        if c.get("alt_reason") == "no arm":
            # Самая частая причина на стенде, и её надо называть прямо:
            # без арма высотомер в Betaflight не считает вовсе.
            why = "R no arm"
        elif alt_cm is None:
            why = "R no alt"
        elif fc_pitch is None:
            why = "R no att"
        elif alt_ts and (time.monotonic() - alt_ts) > 1.0:
            why = "R alt old"
        elif c.get("alt_min_m") is not None and alt_cm / 100.0 <= c["alt_min_m"]:
            # Показываем и высоту, и планку, до которой ей не хватило: без
            # планки «R low 15cm» выглядит поломкой, а это правильный ответ.
            why = "R alt %d<%dcm" % (int(alt_cm), int(c["alt_min_m"] * 100))
        elif dep is None:
            why = "R no ang"
        elif dep < RANGE_MIN_DEPRESSION_DEG:
            # Смотрим почти горизонтально: тангенс малого угла превращает
            # любую ошибку в километры.
            why = "R ang %.1f<%.0f" % (dep, RANGE_MIN_DEPRESSION_DEG)
        else:
            # Ни одна из известных причин не подошла. Раньше здесь молча
            # печаталось 'R ang', и строка врала: показывала угол 14 при
            # пороге 4, будто он мал. Пусть лучше честно скажет, что причина
            # неизвестна, чем назовёт неверную.
            why = "R ?"
        lines.append((why, COLOR_YELLOW))

    tau = c.get("tau_s")
    if tau is not None:
        lines.append(("T %.1fs" % tau, COLOR_GREEN))
    else:
        # Ноль здесь означал бы «мы в цели», поэтому пишем словом.
        lines.append(("T no close", COLOR_YELLOW))

    # Угол визирования — отдельной строкой ВСЕГДА. Это единственная часть
    # оценки дальности, которую можно проверить на столе: высоты там нет и не
    # будет, а угол считается из тангажа и положения цели в кадре, и его знак
    # проверяется руками. Наклонил нос к цели — обязан стать положительным.
    dep = c.get("depression_deg")
    if dep is not None:
        # Положительный = смотрим ВНИЗ, это рабочая сторона.
        lines.append(("dep %+.1f%s" % (dep, "" if dep >= 0 else " UP"),
                      COLOR_GREEN if dep >= RANGE_MIN_DEPRESSION_DEG else COLOR_YELLOW))

    # Разброс барометра рядом: он объясняет планку годности высоты, и по нему
    # сразу видно, датчик ли шумит или высоты просто нет.
    with state_lock:
        sig = app_state.get("alt_sigma_cm")
    if rng is None and sig is not None:
        lines.append(("baro +-%.0fcm" % sig, COLOR_WHITE))

    size = c.get("size_px")
    growth = c.get("growth")
    if size is not None:
        g = "" if growth is None else " %+.1f%%" % (growth * 100.0)
        lines.append(("sz %.0f%s" % (size, g), COLOR_WHITE))
    return lines


def draw_range_readout(frame, box):
    """Телеметрия сближения текстом рядом с рамкой цели."""
    if not RANGE_READOUT_ENABLED or box is None:
        return
    try:
        lines = _range_readout_lines()
        if not lines:
            return
        x1, y1, x2, y2 = box
        # Справа от рамки; если там край кадра — слева.
        w_est = 9 * max(len(t) for t, _ in lines)
        x = int(x2) + 10
        if x + w_est > frame.shape[1] - 4:
            x = max(4, int(x1) - 10 - w_est)
        y = int(clamp(y1 + 12, 14, frame.shape[0] - 14 * len(lines)))
        for i, (text, color) in enumerate(lines):
            yy = y + i * 14
            # Обводка чёрным: без неё текст пропадает на светлом фоне.
            # Сглаживание (LINE_AA) НЕ включаем — замерено, оно стоит 8.8 мс
            # на малине против 0.6 мс без него, при бюджете кадра 38 мс.
            cv2.putText(frame, text, (x, yy), cv2.FONT_HERSHEY_PLAIN,
                        1.0, COLOR_BLACK, 2)
            cv2.putText(frame, text, (x, yy), cv2.FONT_HERSHEY_PLAIN,
                        1.0, color, 1)
    except Exception:
        pass


def _startup_sensor_check():
    """Опросить датчики и подготовить надпись на экран.

    Смысл — увидеть молчащий датчик ДО взлёта, а не на разборе. Отсутствие
    отклика от гироскопа или высотомера обесценивает весь полётный день, и
    выяснять это постфактум слишком дорого.
    """
    global _startup_lines, _startup_ok, _startup_until
    with state_lock:
        imu = bool(app_state.get("imu_seen"))
        alt = bool(app_state.get("alt_seen"))
        # ВАЖНО: по самому наличию rc_channels судить нельзя — там лежит
        # значение по умолчанию, и RC выглядел бы отвечающим всегда. Смотрим
        # на признак ЖИВОЙ связи, который ставится только при реальном ответе.
        # Проверяем НАЛИЧИЕ отметки, а не только её возраст: на машине, где
        # монотонные часы начинаются с нуля, отсутствие ключа выглядело бы как
        # свежий ответ.
        _rc_ts = app_state.get("rc_link_ts")
        rc = _rc_ts is not None and (time.monotonic() - _rc_ts) < 2.0
        att = app_state.get("fc_pitch_deg") is not None
        gps = _gps_zhivoy(app_state)
    missing = []
    if not rc:
        missing.append("RC")
    if not att:
        missing.append("ATTITUDE")
    if not imu:
        missing.append("GYRO")
    if not alt:
        missing.append("BARO")

    if missing:
        _startup_ok = False
        _startup_lines = ["NO RESPONSE: " + ", ".join(missing)]
        # Высотомер до арма молчит по устройству прошивки — подскажем, чтобы
        # оператор не искал неисправность там, где её нет.
        if "BARO" in missing:
            _startup_lines.append("BARO needs ARM to report")
        _startup_until = None          # висит, пока не исправлено
    else:
        _startup_ok = True
        _startup_lines = ["SENSORS OK" + ("" if gps else "  (no GPS)")]
        _startup_until = time.monotonic() + STARTUP_OK_SHOW_S

    flight_log.event("ПРОВЕРКА ДАТЧИКОВ: %s" % (
        "все ответили" if not missing else "НЕ ОТВЕТИЛИ: " + ", ".join(missing)))


def draw_startup_check(frame):
    """Надпись о проверке датчиков поверх картинки.

    Строго по центру и с запасом от краёв. Замерено на борту: в углу кадра
    надпись уходит за пределы видимого — передатчик и очки съедают края
    (overscan), и края эти у каждого комплекта свои. Центр виден всегда.

    Размер подбирается под ширину кадра, а не задан числом: перечень молчащих
    датчиков бывает вчетверо длиннее короткого «всё в порядке», и обрезать
    надо не его, а шрифт. Обрезанное «NO RESPONSE: RC, ATTI...» — худший
    исход из возможных.
    """
    if not _startup_lines:
        return
    if _startup_until is not None and time.monotonic() > _startup_until:
        return
    try:
        h, w = frame.shape[0], frame.shape[1]
        safe = max(40.0, w * STARTUP_SAFE_FRAC)
        shirina = max(
            cv2.getTextSize(t, cv2.FONT_HERSHEY_PLAIN, STARTUP_FONT, 2)[0][0]
            for t in _startup_lines)
        mash = STARTUP_FONT
        if shirina > safe:
            mash = max(0.8, STARTUP_FONT * safe / float(shirina))
        tol = 2 if mash < 1.3 else 3
        shag = int(round(18 * mash))
        col = (90, 230, 90) if _startup_ok else (60, 60, 255)
        y = int(h * 0.5) - (shag * (len(_startup_lines) - 1)) // 2
        for text in _startup_lines:
            (tw, _), _ = cv2.getTextSize(text, cv2.FONT_HERSHEY_PLAIN, mash, tol)
            x = max(2, (w - tw) // 2)
            # Обводка чёрным: без неё текст пропадает на светлом фоне.
            cv2.putText(frame, text, (x, y), cv2.FONT_HERSHEY_PLAIN,
                        mash, COLOR_BLACK, tol + 2)
            cv2.putText(frame, text, (x, y), cv2.FONT_HERSHEY_PLAIN,
                        mash, col, tol)
            y += shag
    except Exception:
        pass


def _gps_prearm_stroka():
    """Живое состояние GPS до арма — или None, если показывать нечего.

    Одной проверки на старте мало: спутники подтягиваются десятками секунд,
    и на восьмой секунде захвата не бывает никогда. Пилоту нужно видеть, что
    происходит СЕЙЧАС, и решать, ждать ли ещё.

    После арма строка убирается: на заходе картинку загораживать нечем.
    """
    with state_lock:
        if app_state.get("armed"):
            return None
        fix = app_state.get("gps_fix")
        sats = app_state.get("gps_sats")
        zhivoy = _gps_zhivoy(app_state)
        videli = app_state.get("gps_sats_max") or 0
    # На боевом борту GPS не будет вовсе, и вечная надпись про его отсутствие
    # там только мешает. Показываем, если GPS ждут, — или если спутники уже
    # появлялись: это само по себе доказывает наличие модуля.
    if not (GPS_EXPECTED or videli > 0):
        return None
    n = int(sats or 0)
    if zhivoy and n >= GPS_SATS_ENOUGH:
        return ("GPS FIX  %d sats" % n, (90, 230, 90))
    if zhivoy:
        return ("GPS FIX  %d sats  (weak)" % n, (60, 200, 240))
    if n > 0:
        return ("GPS SEARCHING  %d sats" % n, (60, 200, 240))
    if fix is None:
        return ("GPS NO RESPONSE", (60, 60, 255))
    return ("GPS SEARCHING  no sats", (60, 60, 255))


def draw_gps_prearm(frame):
    """Строка состояния GPS до арма — по центру, ниже опроса датчиков."""
    try:
        got = _gps_prearm_stroka()
        if got is None:
            return
        text, col = got
        h, w = frame.shape[0], frame.shape[1]
        mash = 1.3
        (tw, _), _ = cv2.getTextSize(text, cv2.FONT_HERSHEY_PLAIN, mash, 2)
        safe = max(40.0, w * STARTUP_SAFE_FRAC)
        if tw > safe:
            mash = max(0.8, mash * safe / float(tw))
            (tw, _), _ = cv2.getTextSize(text, cv2.FONT_HERSHEY_PLAIN, mash, 2)
        x, y = max(2, (w - tw) // 2), int(h * 0.68)
        # Обводка чёрным: без неё текст пропадает на светлом фоне.
        cv2.putText(frame, text, (x, y), cv2.FONT_HERSHEY_PLAIN,
                    mash, COLOR_BLACK, 4)
        cv2.putText(frame, text, (x, y), cv2.FONT_HERSHEY_PLAIN, mash, col, 2)
    except Exception:
        pass


def draw_overlay_on_frame(frame):
    draw_crosshair(frame)
    draw_startup_check(frame)
    draw_gps_prearm(frame)
    with state_lock:
        box = target_box_main
        vis = target_visible
        aux_for_mag = aux4_state
    if vis and box is not None:
        draw_corners(frame, box, COLOR_WHITE, 2)
        draw_range_readout(frame, box)
    if MAG_ENABLED and ((not MAG_ONLY_WHEN_AUX) or aux_for_mag):
        draw_magnifier(frame, box if vis else None)

# =========================================================
# 10. TRACKING CORE (без изменений)
# =========================================================
def process_locked_tracker(gray):
    global track_state, target_visible, target_controllable, overlay_text, overlay_color, target_box_main
    global lock_cx, lock_cy, lock_w, lock_h, template_gray, prev_gray, prev_pts
    global template_base, target_uv, color_active, color_separation
    global lost_frames, frame_index, last_match_score, last_flow_ok
    global fps_t0, fps_frames, fps_current
    global prev_aux_on, acq_wait_left, lock_sequence
    global auto_reacq_attempts
    global template_scale_acc, color_axis

    frame_index += 1

    with state_lock:
        aux_on = aux4_state
        live_thr = app_state.get("rc_throttle", 1500)

    rising_aux = aux_on and not prev_aux_on
    falling_aux = (not aux_on) and prev_aux_on
    prev_aux_on = aux_on

    if not aux_on:
        if falling_aux or track_state != TRACK_STATE_IDLE:
            reset_tracking(to_acq=False)
        auto_reacq_attempts = 0
        with state_lock:
            global global_roll_cmd, global_pitch_cmd, global_yaw_cmd, global_throttle_cmd, override_active
            override_active = False
            global_roll_cmd = 1500.0
            global_pitch_cmd = 1500.0
            global_yaw_cmd = 1500.0
            global_throttle_cmd = live_thr
        return

    # ВЕДЁМ ПО ТОЙ КАРТИНКЕ, ПО КОТОРОЙ РЕШИЛИ ПРИ ЗАХВАТЕ. Если выбран цвет,
    # дальше вся обработка — поиск, поток, размер — идёт по цветовой проекции.
    # Подмена именно здесь, чтобы ни одна часть не работала по другой картинке,
    # чем та, из которой снят эталон.
    if color_axis is not None:
        _proj = color_projection(gray.shape)
        if _proj is not None:
            gray = _proj

    if rising_aux:
        reset_tracking(to_acq=True)
        acq_wait_left = ACQ_SETTLE_FRAMES
        lock_sequence += 1
        auto_reacq_attempts = 0

    if track_state == TRACK_STATE_IDLE:
        reset_tracking(to_acq=True)
        acq_wait_left = ACQ_SETTLE_FRAMES

    if acq_wait_left > 0:
        acq_wait_left -= 1
        with state_lock:
            track_state = TRACK_STATE_ACQ
            target_visible = False
            target_controllable = False
            target_box_main = None
            overlay_text = "ACQ"
            overlay_color = COLOR_WHITE
        update_control_from_target()
        return

    if track_state == TRACK_STATE_LOST and REQUIRE_AUX_TOGGLE_AFTER_LOST:
        # Авто-восстановление: в течение AUTO_REACQ_FRAMES после LOST
        # пробуем найти цель в расширенном окне с высоким порогом матча.
        # Если получилось — без снятия AUX возвращаемся в TRACKED.
        # Иначе остаёмся в LOST/TOGGLE и ждём явного действия оператора.
        if (AUTO_REACQ_ENABLED and template_gray is not None
                and lock_cx is not None and auto_reacq_attempts < AUTO_REACQ_FRAMES):
            auto_reacq_attempts += 1
            # Расширенный матч в окне AUTO_REACQ_SEARCH_MARGIN px вокруг последнего lock.
            # Используем flow_motion=AUTO_REACQ_SEARCH_MARGIN, чтобы template_match_locked
            # автоматически развернул search-окно до максимума.
            match_ok_r, mcx, mcy, score_r = template_match_locked(
                gray, lock_cx, lock_cy, flow_motion=float(AUTO_REACQ_SEARCH_MARGIN)
            )
            if match_ok_r and score_r >= AUTO_REACQ_MIN_SCORE:
                # Нашли с уверенностью — возвращаемся в TRACKED, переинициализируем flow.
                lock_cx = float(mcx)
                lock_cy = float(mcy)
                prev_gray = gray.copy()
                prev_pts = refresh_flow_points(gray, lock_cx, lock_cy, lock_w, lock_h)
                lost_frames = 0
                last_match_score = score_r
                last_flow_ok = False
                auto_reacq_attempts = 0
                box = lores_box_to_main(lock_cx, lock_cy, lock_w, lock_h)
                with state_lock:
                    track_state = TRACK_STATE_TRACKED
                    target_visible = True
                    target_controllable = True
                    target_box_main = box
                    overlay_text = "REACQ"
                    overlay_color = COLOR_RED
                update_control_from_target()
                return
            # Не нашли в этом кадре — продолжаем висеть в LOST, повторим в следующем.
            with state_lock:
                target_visible = False
                target_controllable = False
                target_box_main = None
                overlay_text = "REACQ?"
                overlay_color = COLOR_YELLOW
            update_control_from_target()
            return

        # Окно auto-reacq исчерпано или выключено — обычное поведение LOST/TOGGLE.
        with state_lock:
            target_visible = False
            target_controllable = False
            target_box_main = None
            overlay_text = "LOST/TOGGLE"
            overlay_color = COLOR_WHITE
        update_control_from_target()
        return

    if track_state == TRACK_STATE_ACQ or (track_state == TRACK_STATE_LOST and not REQUIRE_AUX_TOGGLE_AFTER_LOST):
        acq_cx, acq_cy, lw, lh, ok = estimate_initial_target(gray)
        if ok:
            lock_cx = float(acq_cx)
            lock_cy = float(acq_cy)
            lock_w = float(lw)
            lock_h = float(lh)
            # РЕШЕНИЕ, ПО ЧЕМУ ВЕСТИ, принимается ЗДЕСЬ, один раз на захват.
            # Если цель отличается от окружения цветом заметно сильнее, чем
            # яркостью, — ведём по цветовой проекции: в ней цель яркая, а
            # фактура фона схлопнута. Иначе остаёмся на яркости.
            color_axis = None
            if TRACK_ON_COLOR:
                ax = measure_color_axis(gray, lock_cx, lock_cy, lock_w, lock_h)
                if ax is not None and ax[4] >= TRACK_ON_COLOR_MIN_GAIN:
                    color_axis = ax
                    flight_log.event(
                        "ВЕДЁМ ПО ЦВЕТУ: цвет выигрывает у яркости в %.1f раза"
                        % ax[4])
                elif ax is not None:
                    flight_log.event(
                        "ведём по яркости: цвет выигрывает лишь в %.1f раза "
                        "(нужно %.1f)" % (ax[4], TRACK_ON_COLOR_MIN_GAIN))
            track_img = gray
            if color_axis is not None:
                proj = color_projection(gray.shape)
                if proj is not None:
                    track_img = proj
                else:
                    color_axis = None
            template_gray = build_template(track_img, lock_cx, lock_cy,
                                           lock_w, lock_h)
            template_base = template_gray.copy()
            template_scale_acc = 1.0
            # Один раз на захват решаем, помогает ли цвет. Если цель и её
            # окружение одного цвета — цвет не включаем, поведение прежнее.
            if COLOR_GUARD_ENABLED:
                target_uv, color_separation = measure_color_separation(
                    lock_cx, lock_cy, lock_w, lock_h)
                color_active = (target_uv is not None
                                and color_separation >= COLOR_MIN_SEPARATION)
                if color_active:
                    flight_log.event(
                        "ЦВЕТ включён: различимость %.1f (порог %.1f) | %s"
                        % (color_separation, COLOR_MIN_SEPARATION,
                           chroma_debug))
                else:
                    flight_log.event(
                        "ЦВЕТ не используется: различимость %.1f (порог %.1f)"
                        " | %s%s"
                        % (color_separation, COLOR_MIN_SEPARATION,
                           chroma_debug,
                           (" | причина: " + chroma_fail_reason)
                           if chroma_fail_reason else ""))
            else:
                color_active = False
            prev_gray = gray.copy()
            prev_pts = refresh_flow_points(gray, lock_cx, lock_cy, lock_w, lock_h)
            lost_frames = 0
            last_match_score = 1.0
            last_flow_ok = False
            box = lores_box_to_main(lock_cx, lock_cy, lock_w, lock_h)
            with state_lock:
                track_state = TRACK_STATE_TRACKED
                target_visible = True
                target_controllable = True
                target_box_main = box
                overlay_text = "LOCK"
                overlay_color = COLOR_RED
            update_control_from_target()
        else:
            with state_lock:
                track_state = TRACK_STATE_ACQ
                target_visible = False
                target_controllable = False
                target_box_main = None
                overlay_text = "ACQ"
                overlay_color = COLOR_WHITE
            update_control_from_target()
        return

    if lock_cx is None or lock_w is None or template_gray is None:
        reset_tracking(to_acq=True)
        return

    flow_ok, pred_cx, pred_cy = flow_predict(prev_gray, gray, prev_pts, lock_cx, lock_cy)
    # Модуль flow-предсказанного смещения цели за кадр — используется
    # template_match_locked для адаптивного выбора search-окна.
    flow_motion = math.hypot(pred_cx - lock_cx, pred_cy - lock_cy) if flow_ok else 0.0
    # Движение цели за кадр — разница между предсказанием потока и прежним
    # положением. Именно с ним сравнивается движение фона.
    match_ok, match_cx, match_cy, score = template_match_locked(
        gray, pred_cx, pred_cy, flow_motion,
        tgt_dx=pred_cx - lock_cx, tgt_dy=pred_cy - lock_cy)
    last_match_score = score
    last_flow_ok = flow_ok

    new_cx, new_cy = lock_cx, lock_cy
    tracked_ok = False

    if flow_ok and match_ok:
        dist_fm = math.hypot(match_cx - pred_cx, match_cy - pred_cy)
        # Насколько матч ТЯНЕТ в сторону от предсказания потока.
        #
        # Поток следит за реальным движением цели и на фон не смотрит, поэтому
        # устойчивое расхождение означает, что матч зацепился за что-то другое.
        # В отличие от score, эта величина различает «держит цель» и «уверенно
        # держит не то»: сидя на фоне, матч даёт высокий score, но расходится с
        # потоком. Ни score, ни доля провалов такого показать не могут.
        _match_dbg["flow_gap"] = float(dist_fm)
        if score >= MATCH_GOOD_SCORE and dist_fm <= MAX_LOCK_STEP:
            w_m = MATCH_WEIGHT
            if MATCH_AMBIGUITY_GUARD:
                second = _match_dbg.get("second")
                if second is not None and score > 0.0:
                    # Насколько выбранный пик выигрывает у лучшего конкурента.
                    # Отрицательный запас = конкурент сильнее, матчу верить
                    # нельзя, ведём по потоку.
                    lead = (score - float(second)) / max(score, 1e-6)
                    if lead <= 0.0:
                        w_m = MATCH_WEIGHT_MIN
                    elif lead < MATCH_LEAD_FULL:
                        # Плавный переход, чтобы не дёргать вес туда-сюда на
                        # границе: на 25% запаса — полное доверие.
                        f = lead / MATCH_LEAD_FULL
                        w_m = MATCH_WEIGHT_MIN + (MATCH_WEIGHT - MATCH_WEIGHT_MIN) * f
            new_cx = (1.0 - w_m) * pred_cx + w_m * match_cx
            new_cy = (1.0 - w_m) * pred_cy + w_m * match_cy
            tracked_ok = True
        elif dist_fm <= MAX_LOCK_STEP * 0.55:
            new_cx = pred_cx
            new_cy = pred_cy
            tracked_ok = True
    elif flow_ok:
        new_cx = pred_cx
        new_cy = pred_cy
        tracked_ok = True
    elif match_ok and score >= MATCH_GOOD_SCORE:
        new_cx = match_cx
        new_cy = match_cy
        tracked_ok = True

    if tracked_ok:
        step = math.hypot(new_cx - lock_cx, new_cy - lock_cy)
        if step > MAX_LOCK_STEP:
            k = MAX_LOCK_STEP / max(step, 1e-6)
            new_cx = lock_cx + (new_cx - lock_cx) * k
            new_cy = lock_cy + (new_cy - lock_cy) * k

        lock_cx = float(clamp(new_cx, 0, LORES_W - 1))
        lock_cy = float(clamp(new_cy, 0, LORES_H - 1))
        lost_frames = 0
        auto_reacq_attempts = 0   # успешно идём — сбрасываем счётчик восстановлений

        if frame_index % FLOW_REFRESH_EVERY == 0:
            prev_pts = refresh_flow_points(gray, lock_cx, lock_cy, lock_w, lock_h)
        prev_gray = gray.copy()

        if not FREEZE_TEMPLATE and match_ok and score >= 0.60:
            cur_tmpl = build_template(gray, lock_cx, lock_cy, lock_w, lock_h)
            # Размер шаблона следует за размером коробки, поэтому при
            # изменении масштаба цели формы перестают совпадать. Раньше в этом
            # случае обновление ПРОПУСКАЛОСЬ — то есть именно на сближении,
            # когда коробка растёт, шаблон переставал обновляться и оставался
            # в старом мелком масштабе. Он покрывал всё меньшую долю цели,
            # матчер цеплялся за случайную деталь внутри объекта и уползал к
            # краю, а потом и на фон.
            #
            # Асимметрия наблюдалась именно поэтому: при УДАЛЕНИИ шаблон
            # оказывается КРУПНЕЕ цели, захватывает фон вокруг и потому
            # остаётся заякоренным — там сбоя не было.
            #
            # Теперь при смене размера шаблон пересчитывается в новый масштаб,
            # а не выбрасывается: накопленный вид цели сохраняется.
            if cur_tmpl.shape == template_gray.shape:
                template_gray = cv2.addWeighted(
                    template_gray, 1 - TEMPLATE_UPDATE_ALPHA,
                    cur_tmpl, TEMPLATE_UPDATE_ALPHA, 0)
            elif TEMPLATE_RESCALE_ON_SIZE_CHANGE and template_base is not None:
                # Размер изменился. Пересчитывать НАКОПЛЕННЫЙ шаблон нельзя:
                # каждый cv2.resize — это интерполяция, то есть размытие, и
                # оно накапливается. Размер коробки гуляет (в логе 16 -> 43 ->
                # 16 -> 40), значит пересчётов десятки, и шаблон превращался в
                # кашу — средний score упал с 0.643 до 0.498.
                #
                # Вместо этого берём ЧИСТЫЙ шаблон текущего кадра в новом
                # масштабе. Накопленный вид теряется, но это разовое событие
                # на смену масштаба, а не деградация каждые несколько кадров.
                # Прежний код в этом месте не делал НИЧЕГО, из-за чего на
                # сближении шаблон застревал в старом масштабе — здесь мы
                # по-прежнему следуем за размером, но без размытия.
                # Масштабируем ЭТАЛОН, снятый при захвате, а не текущий кадр
                # и не накопленный шаблон.
                #
                # Не текущий кадр: TEMPLATE_SCALE=2.0 значит, что шаблон
                # вчетверо больше коробки — три четверти его площади это фон.
                # Свежий вырез приносит В ШАБЛОН текущий фон, и матчер потом
                # честно находит этот фон. Так лок и уходил на похожий по
                # цвету фон (score 0.726 -> 0.561, замерено на борту).
                #
                # Не накопленный: каждый resize размывает, размытие копится,
                # 30 пересчётов съедали всю детализацию (1043 -> 4.7).
                #
                # Эталон снят на цели при захвате и не меняется, поэтому
                # масштабируется ровно один раз в любой новый размер.
                template_gray = cv2.resize(
                    template_base, (cur_tmpl.shape[1], cur_tmpl.shape[0]),
                    interpolation=cv2.INTER_LINEAR)

        # Периодическая адаптация размера коробки. Раз в SIZE_ADAPT_EVERY_FRAMES
        # при уверенном матче запрашиваем заново связную компоненту под текущим
        # центром лока и сдвигаем lock_w/lock_h в её сторону. Решает «дрейф
        # зацепом за край» при сближении — коробка растёт вместе с целью.
        # Измеряем, ПОЧЕМУ адаптация размера не срабатывает. По логам борта
        # коробка стоит на значении по умолчанию (8 px в координатах трекинга)
        # в 76%% кадров и почти не растёт, хотя объект бывает крупным. Гейта
        # два — порог score и допустимый диапазон оценки, — и без записи
        # непонятно, какой именно закрыт.
        # Фон в оси цвета обновляем на ходу: он меняется по-настоящему, когда
        # цель уходит с одного покрытия на другое.
        if (color_axis is not None
                and frame_index % TRACK_ON_COLOR_BG_EVERY == 0):
            refresh_color_axis(lock_cx, lock_cy, lock_w, lock_h)

        if (SIZE_BY_SCALE_ENABLED and SIZE_ADAPT_ENABLED
                and frame_index % SIZE_ADAPT_EVERY_FRAMES == 0):
            # Размер по масштабу совпадения. Сегментация не участвует.
            if not match_ok:
                _match_dbg["size_skip"] = 1
            elif score < SIZE_ADAPT_MIN_SCORE:
                _match_dbg["size_skip"] = 2
            else:
                k_scale = measure_scale_change(gray, lock_cx, lock_cy)
                _match_dbg["size_scale"] = k_scale
                if template_std < TEMPLATE_STARVED_STD:
                    # Эталон безлик — он внутри однородного предмета. Растём,
                    # пока край предмета не вернётся в эталон. Масштаб тут
                    # спрашивать бесполезно: все масштабы одинаково пусты.
                    _match_dbg["size_skip"] = 6
                    lock_w = clamp(lock_w * TEMPLATE_STARVED_GROW,
                                   LOCK_MIN_W, LOCK_MAX_W)
                    lock_h = clamp(lock_h * TEMPLATE_STARVED_GROW,
                                   LOCK_MIN_H, LOCK_MAX_H)
                elif k_scale is None:
                    _match_dbg["size_skip"] = 3     # примерить не удалось
                elif k_scale == 1.0:
                    _match_dbg["size_skip"] = 5     # масштаб не изменился
                else:
                    _match_dbg["size_skip"] = 0
                    grow = 1.0 + (k_scale - 1.0) * SIZE_SCALE_ALPHA
                    lock_w = clamp(lock_w * grow, LOCK_MIN_W, LOCK_MAX_W)
                    lock_h = clamp(lock_h * grow, LOCK_MIN_H, LOCK_MAX_H)
                    # ЗАМКНУТЬ ОБРАТНУЮ СВЯЗЬ. Без этого коробка росла, а
                    # эталон — нет, и примерка каждый раз заново видела ту же
                    # разницу: 1315 кадров подряд она говорила «крупнее» при
                    # 60 «мельче», и коробка уезжала в предел сама по себе,
                    # даже когда оператор остановился.
                    #
                    # Эталон пересчитывается ИЗ ИСХОДНОГО, снятого при
                    # захвате, по накопленному множителю. Именно из исходного,
                    # а не из текущего: каждый cv2.resize размывает, и
                    # пересчёт по цепочке уже губил эталон — резкость падала
                    # в двести раз. Здесь интерполяция всегда ОДНА, от
                    # оригинала к нужному масштабу.
                    if template_base is not None:
                        template_scale_acc = clamp(
                            template_scale_acc * grow, 0.25, 6.0)
                        bh, bw = template_base.shape[:2]
                        nw = int(round(clamp(bw * template_scale_acc,
                                             TEMPLATE_MIN, TEMPLATE_MAX)))
                        nh = int(round(clamp(bh * template_scale_acc,
                                             TEMPLATE_MIN, TEMPLATE_MAX)))
                        if (nw, nh) != (template_gray.shape[1],
                                        template_gray.shape[0]):
                            template_gray = cv2.resize(
                                template_base, (nw, nh),
                                interpolation=cv2.INTER_LINEAR)
                            # Пересчёт из исходного ОТБРАСЫВАЕТ накопленный вид
                            # цели: свет поменялся, ракурс поехал, а мы
                            # возвращаемся к тому, что было при захвате.
                            # На однотонном фоне это незаметно, на фактурном
                            # устаревший эталон начинает совпадать с фоном.
                            # Поэтому вид копим в САМОМ ИСХОДНОМ эталоне:
                            # свежий кусок кадра приводится к его размеру и
                            # подмешивается. Интерполяция при этом всегда одна
                            # и всегда по СВЕЖИМ данным — исходный эталон не
                            # пересчитывается сам из себя и не размывается.
                            _adapt_template_base(gray)
        elif SIZE_ADAPT_ENABLED and frame_index % SIZE_ADAPT_EVERY_FRAMES == 0:
            # Область поиска растягиваем под ТЕКУЩИЙ размер коробки, иначе
            # крупная цель заведомо в неё не помещается и измерить её нельзя.
            est_w, est_h = estimate_size_at_position(
                gray, lock_cx, lock_cy, cur_w=max(lock_w, lock_h))
            _match_dbg["size_est"] = est_w if est_w is not None else -1.0
            _match_dbg["size_why"] = _size_fail["why"]
            _match_dbg["size_R"] = _size_fail["R"]
            if not match_ok:
                _match_dbg["size_skip"] = 1        # матча нет
            elif score < SIZE_ADAPT_MIN_SCORE:
                _match_dbg["size_skip"] = 2        # score ниже порога
            elif est_w is None:
                _match_dbg["size_skip"] = 3        # измерить не удалось
            elif not (SIZE_ADAPT_MIN_W <= est_w <= SIZE_ADAPT_MAX_W
                      and SIZE_ADAPT_MIN_W <= est_h <= SIZE_ADAPT_MAX_W):
                _match_dbg["size_skip"] = 4        # вне допустимого диапазона
            else:
                _match_dbg["size_skip"] = 0        # применена
                # Размер меняем только когда его ДЕЙСТВИТЕЛЬНО измерили.
                # Прежде при неудаче подставлялся минимум, и коробка каждые
                # 10 кадров ужималась обратно.
                lock_w = lock_w * (1.0 - SIZE_ADAPT_ALPHA) + est_w * SIZE_ADAPT_ALPHA
                lock_h = lock_h * (1.0 - SIZE_ADAPT_ALPHA) + est_h * SIZE_ADAPT_ALPHA

        box = lores_box_to_main(lock_cx, lock_cy, lock_w, lock_h)
        with state_lock:
            track_state = TRACK_STATE_TRACKED
            target_visible = True
            target_controllable = True
            target_box_main = box
            overlay_text = "TRACKED"
            overlay_color = COLOR_RED
        update_control_from_target()
    else:
        lost_frames += 1
        prev_gray = gray.copy()
        if lost_frames <= HOLD_FRAMES:
            box = lores_box_to_main(lock_cx, lock_cy, lock_w, lock_h)
            with state_lock:
                track_state = TRACK_STATE_HOLD
                target_visible = True
                target_controllable = False
                target_box_main = box
                overlay_text = "HOLD"
                overlay_color = COLOR_YELLOW
            update_control_from_target()
        elif lost_frames <= LOST_LIMIT:
            with state_lock:
                track_state = TRACK_STATE_LOST
                target_visible = False
                target_controllable = False
                target_box_main = None
                overlay_text = "LOST"
                overlay_color = COLOR_WHITE
            update_control_from_target()
        else:
            if REQUIRE_AUX_TOGGLE_AFTER_LOST:
                with state_lock:
                    track_state = TRACK_STATE_LOST
                    target_visible = False
                    target_controllable = False
                    target_box_main = None
                    overlay_text = "LOST/TOGGLE"
                    overlay_color = COLOR_WHITE
                update_control_from_target()
            else:
                reset_tracking(to_acq=True)
                update_control_from_target()


def _chroma_saturation():
    """Насколько кадр вообще цветной. Ноль — серый.

    Нужна, чтобы отличить «предмет не цветной» от «камера отдаёт серое».
    Второе случалось: вечером цель приходила с U=125 V=126 при нейтрали 128,
    а утром тот же предмет давал U=85 V=203.
    """
    if chroma_u is None or chroma_v is None:
        return None
    try:
        u = chroma_u.astype(np.float32) - 128.0
        v = chroma_v.astype(np.float32) - 128.0
        return float(np.mean(np.abs(u) + np.abs(v)))
    except Exception:
        return None


def print_debug_once_per_second():
    """Раз в DEBUG_PERIOD секунд:
       FPS, state, override, RC со стика (RPYT), наш CMD, что РЕАЛЬНО ушло в FC,
       motor outputs (если Betaflight отдаёт MSP_MOTOR).
    """
    global fps_t0, fps_frames, fps_current
    fps_frames += 1
    now = time.monotonic()
    if now - fps_t0 < DEBUG_PERIOD:
        return

    fps_current = fps_frames / max(now - fps_t0, 1e-6)
    fps_frames = 0
    fps_t0 = now

    if not DEBUG_PRINT:
        return

    with state_lock:
        ch = list(app_state.get("rc_channels", [1500] * 8))
        motors = list(app_state.get("motors", []))
        ov = override_active
        st = track_state
        r_out = int(global_roll_cmd)
        p_out = int(global_pitch_cmd)
        y_out = int(global_yaw_cmd)
        t_out = int(global_throttle_cmd)
        sent = list(app_state.get("last_sent_channels", [1500] * 8))

    c0 = int(ch[0]) if len(ch) > 0 else 1500
    c1 = int(ch[1]) if len(ch) > 1 else 1500
    c2 = int(ch[2]) if len(ch) > 2 else 1500
    c3 = int(ch[3]) if len(ch) > 3 else 1000
    s0 = int(sent[0]) if len(sent) > 0 else 1500
    s1 = int(sent[1]) if len(sent) > 1 else 1500
    s2 = int(sent[2]) if len(sent) > 2 else 1500
    s3 = int(sent[3]) if len(sent) > 3 else 1000

    mot_s = " ".join([f"M{i+1}:{int(v)}" for i, v in enumerate(motors[:4])]) if motors else "M:NA"

    print(
        f"FPS:{fps_current:5.1f} | {st:<7} | OV:{ov} | "
        f"RPYT in: R{c0:4d} P{c1:4d} Y{c2:4d} T{c3:4d} | "
        f"CMD R{r_out:4d} P{p_out:4d} Y{y_out:4d} T{t_out:4d} | "
        f"SENT AETR R{s0:4d} P{s1:4d} T{s2:4d} Y{s3:4d} | "
        f"{mot_s}",
        flush=True
    )

# =========================================================
# 11. FAST IDLE + CAMERA CALLBACK
# =========================================================
def fast_idle_update():
    global prev_aux_on, track_state, override_active
    global global_roll_cmd, global_pitch_cmd, global_yaw_cmd, global_throttle_cmd
    global _ctl_dbg

    with state_lock:
        live_thr = app_state.get("rc_throttle", 1500)

    if prev_aux_on or track_state != TRACK_STATE_IDLE:
        reset_tracking(to_acq=False)
    prev_aux_on = False

    with state_lock:
        app_state["dyn_throttle"] = live_thr
        override_active = False
        _ctl_dbg = {"active": False, "base_thr": live_thr}
        global_roll_cmd = 1500.0
        global_pitch_cmd = 1500.0
        global_yaw_cmd = 1500.0
        global_throttle_cmd = live_thr


_flight_prev_t = None
_flight_prev_state = None
_flight_prev_launch = None
_flight_prev_override = None


def _capture_flight_row(cb_t0):
    """Одна строка лога за кадр. Вызывается в камерном потоке, поэтому здесь
    только чтение переменных и сборка кортежа — ни форматирования, ни диска."""
    global _flight_prev_t, _flight_prev_state, _flight_prev_launch, _flight_prev_override
    if not flight_log.enabled:
        return
    try:
        now = time.monotonic()
        dt_ms = 0.0 if _flight_prev_t is None else (now - _flight_prev_t) * 1000.0
        _flight_prev_t = now

        c = _ctl_dbg
        active = c.get("active", False)

        with state_lock:
            st = track_state
            ctrl = target_controllable
            aux = aux4_state
            ov = override_active
            r_cmd = int(global_roll_cmd)
            p_cmd = int(global_pitch_cmd)
            y_cmd = int(global_yaw_cmd)
            t_cmd = int(global_throttle_cmd)
            sent = app_state.get("last_sent_channels", (1500,) * 8)
            rc = app_state.get("rc_channels", (1500,) * 8)
            motors = app_state.get("motors", ())
            fc_roll = app_state.get("fc_roll_deg")
            fc_pitch = app_state.get("fc_pitch_deg")
            fc_yaw = app_state.get("fc_yaw_deg")
            att_ts = app_state.get("fc_pitch_ts", 0.0)
            armed = app_state.get("armed")
            alt_cm = app_state.get("alt_cm")
            vario_cms = app_state.get("vario_cms")
            alt_ts = app_state.get("alt_ts", 0.0)
            alt_sigma = app_state.get("alt_sigma_cm")
            _gyro = app_state.get("gyro") or (None, None, None)
            _acc = app_state.get("acc") or (None, None, None)
            gyro_x, gyro_y, gyro_z = _gyro
            acc_z = _acc[2]
            gps_fix = app_state.get("gps_fix")
            gps_sats = app_state.get("gps_sats")
            gps_lat = app_state.get("gps_lat")
            gps_lon = app_state.get("gps_lon")
            _sp = app_state.get("gps_speed_cms")
            gps_speed_ms = None if _sp is None else _sp / 100.0
            gps_course = app_state.get("gps_course")
            # ИСТИННАЯ дальность до цели — если известны и наши координаты, и
            # координаты цели. Это тот самый «правильный ответ», с которым
            # сверяется всё, что видит камера. Без GPS остаётся None, и разбор
            # идёт по высоте, углу и скорости роста цели.
            gps_range_m = None
            if (gps_fix and gps_lat is not None and TARGET_LAT is not None
                    and TARGET_LON is not None):
                try:
                    dlat = math.radians(TARGET_LAT - gps_lat)
                    dlon = math.radians(TARGET_LON - gps_lon)
                    la = math.radians(gps_lat)
                    gps_range_m = 6371000.0 * math.hypot(
                        dlat, dlon * math.cos(la))
                except Exception:
                    gps_range_m = None

        att_age = (now - att_ts) * 1000.0 if att_ts else None
        alt_age = (now - alt_ts) * 1000.0 if alt_ts else None

        # Переходы пишем событиями: по CSV их искать глазами неудобно,
        # а именно они отвечают на «когда всё сломалось».
        if st != _flight_prev_state:
            flight_log.event("STATE %s -> %s" % (_flight_prev_state, st))
            # Папка захвата открывается и закрывается ВМЕСТЕ со слежением:
            # один заход — одна выборка.
            if st == TRACK_STATE_TRACKED:
                lock_log.begin(lock_sequence)
                lock_log.event("захват начат")
            elif lock_log.active:
                lock_log.end("состояние %s" % st)
            _flight_prev_state = st
        lp = c.get("launch_phase")
        if lp != _flight_prev_launch:
            flight_log.event("LAUNCH %s -> %s" % (_flight_prev_launch, lp))
            _flight_prev_launch = lp
        if ov != _flight_prev_override:
            flight_log.event("OVERRIDE -> %s" % ov)
            _flight_prev_override = ov

        def g(k, d=None):
            return c.get(k, d) if active else None

        _row_values = (
            now - flight_log._t0, frame_index, fps_current, st, ctrl, aux, ov,
            c.get("launch_phase") if active else "", g("launch_int"),
            last_match_score, last_flow_ok, lost_frames, auto_reacq_attempts,
            g("box_cx"), g("box_cy"), g("box_w"), g("box_h"), g("box_frac"),
            g("dx_raw"), g("dy_raw"), g("comp"), g("lead_x"), g("lead_y"),
            g("dx_aim"), g("dy_aim"), g("adx"), g("ady"), g("dy_alt"),
            g("tgt_vx"), g("tgt_vy"), g("stable"), g("terminal"),
            g("roll_p"), g("roll_d"), g("roll_i"), g("roll_ff"),
            g("roll_off"), g("roll_sat"),
            g("pitch_p"), g("pitch_d"), g("pitch_i"), g("pitch_ff"),
            g("pitch_off"), g("pitch_sat"),
            g("launch_pwm"), g("cruise_pwm"), g("pitch_comb"),
            g("yaw_filt"), g("yaw_weight"), g("yaw_pd"), g("yaw_ff"),
            g("yaw_i"), g("yaw_off"), g("yaw_sat"),
            c.get("base_thr"), g("thr_adjust"), g("thr_i"), g("rc_fresh"),
            r_cmd, p_cmd, y_cmd, t_cmd,
            _idx(sent, 0), _idx(sent, 1), _idx(sent, 2), _idx(sent, 3),
            fc_roll, fc_pitch, fc_yaw, att_age,
            _idx(motors, 0), _idx(motors, 1), _idx(motors, 2), _idx(motors, 3),
            _idx(rc, 0), _idx(rc, 1), _idx(rc, 2), _idx(rc, 3),
            dt_ms, (time.monotonic() - cb_t0) * 1000.0, armed,
            g("launch_target_deg"), g("launch_reached"), g("k"),
            _match_dbg.get("psr"), _match_dbg.get("second"),
            _match_dbg.get("margin"), _match_dbg.get("flow_gap"),
            _match_dbg.get("size_est"), _match_dbg.get("size_skip"),
            _match_dbg.get("size_why"), _match_dbg.get("size_R"),
            _match_dbg.get("size_scale"),
            _match_dbg.get("motion_sep"), _match_dbg.get("motion_on"),
            _match_dbg.get("color_on"), _match_dbg.get("color_pen"),
            _match_dbg.get("color_best"), _chroma_saturation(),
            alt_cm, vario_cms, alt_age,
            g("size_px"), g("growth"), g("tau_s"), g("range_m"),
            g("depression_deg"), g("dy_alt_decoupled"),
            alt_sigma, g("alt_min_m"),
            gyro_x, gyro_y, gyro_z, acc_z,
            gps_fix, gps_sats, gps_lat, gps_lon, gps_speed_ms, gps_course,
            gps_range_m, ground_speed_mps,
        )
        flight_log.row(_row_values)
        # Та же строка — в папку этого захвата. Форматируем один раз здесь, а
        # не в фоне: в папке лежит ровно то, что было в этот кадр.
        if lock_log.active:
            lock_log.row(",".join(_fmt(v) for v in _row_values))
    except Exception:
        # Лог не имеет права мешать полёту.
        pass


def _idx(seq, i):
    try:
        return int(seq[i])
    except Exception:
        return None


class FrameRecorder:
    """Запись сырых кадров яркости для последующего разбора на земле.

    В камерном потоке делается только копия кадра и укладка в очередь — около
    0.1 мс. Всё остальное (запись на карту) идёт в отдельном потоке: диск на
    карте бывает медленным, и его задержка не имеет права попасть в кадр.

    Рядом с кадрами пишется опись: номер, время, состояние, коробка, score.
    По ней потом видно, что трекер думал в каждый момент, и можно сравнить с
    тем, что решит другой алгоритм на тех же кадрах.
    """

    def __init__(self, directory):
        self.dir = directory
        self.active = False
        self._q = collections.deque()
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._thread = None
        self._path = None
        self._index = None
        self._n = 0
        self._bytes = 0
        self._t0 = 0.0
        self.shape = None

    def start(self, shape):
        if self.active or not RECORD_FRAMES:
            return
        try:
            d = os.path.join(self.dir, RECORD_DIR)
            os.makedirs(d, exist_ok=True)
            stamp = time.strftime("%Y%m%d_%H%M%S")
            self._path = os.path.join(d, stamp + ".yuv")
            self._index = open(os.path.join(d, stamp + ".index.csv"), "w")
            self._index.write("frame,t,state,box_cx,box_cy,box_w,box_h,score\n")
            self.shape = shape
            with open(os.path.join(d, stamp + ".meta.txt"), "w") as f:
                # Высота буфера в полтора раза больше кадра: под яркостью лежит
                # цветность. Разборщику надо знать и то, и другое.
                f.write("width=%d\nheight=%d\nbuffer_height=%d\n"
                        "format=YUV420\ndtype=uint8\n"
                        % (CAM_W, CAM_H, shape[0]))
            self._n = 0
            self._bytes = 0
            self._t0 = time.monotonic()
            self._stop.clear()
            self.active = True
            self._thread = threading.Thread(target=self._run, daemon=True)
            self._thread.start()
            flight_log.event("ЗАПИСЬ КАДРОВ начата: %s (%dx%d, с цветом)"
                             % (os.path.basename(self._path), LORES_W, LORES_H))
        except Exception as exc:
            self.active = False
            flight_log.event("ЗАПИСЬ КАДРОВ не началась: %s" % exc)

    def add(self, gray, row):
        if not self.active:
            return
        if (time.monotonic() - self._t0) > RECORD_MAX_SECONDS:
            self.stop("вышло время")
            return
        if self._bytes > RECORD_MAX_MB * 1024 * 1024:
            self.stop("вышло место")
            return
        # Только копия и укладка в очередь: диск в камерном потоке недопустим.
        with self._lock:
            if len(self._q) > 90:      # карта не успевает — лучше пропустить кадр
                return
            self._q.append((gray.copy(), row))
        self._bytes += gray.nbytes

    def _run(self):
        try:
            with open(self._path, "wb") as f:
                while not self._stop.is_set() or self._q:
                    item = None
                    with self._lock:
                        if self._q:
                            item = self._q.popleft()
                    if item is None:
                        time.sleep(0.005)
                        continue
                    gray, row = item
                    f.write(gray.tobytes())
                    self._index.write("%d,%s\n" % (self._n, row))
                    self._n += 1
        except Exception:
            pass

    def stop(self, why=""):
        if not self.active:
            return
        self.active = False
        self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=3.0)
        try:
            self._index.close()
        except Exception:
            pass
        flight_log.event("ЗАПИСЬ КАДРОВ окончена: %d кадров, %.1f МБ%s"
                         % (self._n, self._bytes / 1048576.0,
                            (" (" + why + ")") if why else ""))


frame_recorder = FrameRecorder(FLIGHT_LOG_DIR)


def _gotovnost_k_sboru():
    """Проверка готовности к сбору данных. Пишется в журнал один раз.

    Смысл: не полагаться на то, что «всё вроде сделано». Сбор данных — это
    полётный день, и обнаружить на разборе, что гироскоп не отвечал или что в
    стиках лежит эхо трекера, значит потерять этот день целиком.

    Проверяется то, что нельзя увидеть на земле по коду, — отвечает ли
    железо и не включён ли оверрайд.
    """
    global _gotovnost_done
    if _gotovnost_done:
        return
    _gotovnost_done = True
    try:
        with state_lock:
            imu = app_state.get("imu_seen")
            alt = app_state.get("alt_seen")
            gps = _gps_zhivoy(app_state)
            fc_ovr = app_state.get("fc_override_on")
            armed = app_state.get("armed")
        lines = []
        beda = []

        def check(name, ok, need, why):
            mark = "ДА " if ok else "НЕТ"
            lines.append("  %-28s %s" % (name, mark))
            if need and not ok:
                beda.append(why)

        check("режим наблюдения включён", OBSERVE_ONLY, True,
              "БЕЗ OBSERVE_ONLY в стиках окажется эхо трекера, а не действия "
              "пилота — вся выборка будет негодной")
        check("оверрайд на полётнике выключен", not fc_ovr, True,
              "оверрайд активен: MSP_RC возвращает наши же значения")
        check("папка на каждый захват", LOCK_LOG_ENABLED, True,
              "захваты сольются в один файл, разбирать поштучно не выйдет")
        check("гироскоп отвечает", bool(imu), True,
              "без гироскопа неизвестно, ЧТО ВЫШЛО из действий пилота: в ACRO "
              "стик задаёт угловую скорость, а не угол")
        check("высотомер отвечает", bool(alt), True,
              "без высоты нет ни дальности, ни путевой скорости по земле")
        check("скорость по бегу земли считается", GROUND_SPEED_ENABLED, True,
              "без неё закон упреждения выйдет усреднённым по скорости")
        check("GPS отвечает", gps, False, "")
        check("координаты цели заданы", TARGET_LAT is not None, False, "")

        flight_log.event("ГОТОВНОСТЬ К СБОРУ ДАННЫХ:\n" + "\n".join(lines))
        if beda:
            for b in beda:
                flight_log.event("  НЕ ГОТОВО: %s" % b)
            flight_log.event("  => СБОР ДАННЫХ НЕ ИМЕЕТ СМЫСЛА, пока это не "
                             "исправлено")
        elif not gps:
            flight_log.event(
                "  готово. GPS нет — сбор идёт по высоте, углу и бегу земли, "
                "но без сверки: систематическая ошибка не обнаружится")
        else:
            flight_log.event("  готово полностью, со сверкой по GPS")
    except Exception as exc:
        flight_log.event("проверка готовности не отработала: %s" % exc)


def camera_callback(request):
    global chroma_u, chroma_v
    _cb_t0 = time.monotonic()
    try:
        with state_lock:
            aux_snapshot = aux4_state

        if not aux_snapshot:
            fast_idle_update()
            print_debug_once_per_second()
            with MappedArray(request, "main") as mm:
                draw_overlay_on_frame(mm.array)
            _capture_flight_row(_cb_t0)
            return

        with MappedArray(request, "lores") as lm:
            yuv = lm.array
            if RECORD_HIRES:
                # Камера отдаёт двойное разрешение, но ВЕДЁМ мы по обычному:
                # поведение обязано остаться прежним, иначе запись перестанет
                # соответствовать тому, что мы проверяем. В запись при этом
                # уходит полный кадр — ради него всё и затевалось.
                gray = cv2.resize(yuv[:CAM_H, :CAM_W], (LORES_W, LORES_H),
                                  interpolation=cv2.INTER_AREA)
            else:
                gray = yuv[:LORES_H, :LORES_W].copy()
            if COLOR_GUARD_ENABLED or TRACK_ON_COLOR:
                # Цветность уже в этом же буфере — копируем вместе с яркостью.
                cu, cv_ = extract_chroma(yuv, CAM_W, CAM_H)
                if cu is not None:
                    if RECORD_HIRES:
                        # Цветность приводим к рабочему разрешению: вся
                        # обработка идёт по уменьшенному кадру, и цветность
                        # обязана быть с ним согласована.
                        cu = cv2.resize(cu, (LORES_W // 2, LORES_H // 2),
                                        interpolation=cv2.INTER_AREA)
                        cv_ = cv2.resize(cv_, (LORES_W // 2, LORES_H // 2),
                                         interpolation=cv2.INTER_AREA)
                    chroma_u = cu.copy()
                    chroma_v = cv_.copy()

        # Путевая скорость по бегу земли. Считается всегда, когда включена:
        # она нужна и для разбора налётов, и как замена GPS.
        if GROUND_SPEED_ENABLED:
            estimate_ground_speed(gray, _cb_t0)

        process_locked_tracker(gray)
        # Запись кадров: начинается вместе со слежением, кончается вместе с
        # ним. Пишем ровно то, что видел трекер, — ту же яркость, тот же кадр.
        if RECORD_FRAMES:
            if track_state == TRACK_STATE_TRACKED:
                if not frame_recorder.active:
                    frame_recorder.start((CAM_H * 3 // 2, CAM_W))
                with state_lock:
                    _b = target_box_main
                _bx = ("%.1f,%.1f,%.1f,%.1f" % (
                    (_b[0] + _b[2]) / 2.0, (_b[1] + _b[3]) / 2.0,
                    _b[2] - _b[0], _b[3] - _b[1])) if _b else ",,,"
                # Пишем ВЕСЬ буфер: яркость плюс цветность.
                frame_recorder.add(yuv[:CAM_H * 3 // 2, :CAM_W],
                                   "%.3f,%s,%s,%.4f" % (
                    time.monotonic() - _cb_t0 + _cb_t0, track_state, _bx,
                    last_match_score))
            elif frame_recorder.active:
                frame_recorder.stop("слежение окончено")
        print_debug_once_per_second()

        with MappedArray(request, "main") as mm:
            draw_overlay_on_frame(mm.array)
        _capture_flight_row(_cb_t0)
    except Exception:
        pass

# =========================================================
# МЕСТНЫЕ НАСТРОЙКИ БОРТА
# =========================================================
# Файл local_settings.py, если он есть рядом, переопределяет любые настройки
# выше. Он НЕ в репозитории (см. .gitignore), поэтому:
#   * git pull больше не конфликтует с местными правками;
#   * настройки конкретного борта не уезжают в общий код;
#   * ./record.sh пишет туда, а не правит tracker.py.
#
# До этого record.sh менял tracker.py на месте, и обновление на малине падало
# с «local changes would be overwritten». Правка настроек и правка программы —
# разные вещи, и хранить их надо порознь.
try:
    import local_settings as _ls
    _applied = []
    for _name in dir(_ls):
        if _name.startswith("_"):
            continue
        if _name in globals():
            globals()[_name] = getattr(_ls, _name)
            _applied.append(_name)
        else:
            print("[настройки борта] неизвестное имя %s — пропущено" % _name)
    if _applied:
        print("[настройки борта] применено: %s" % ", ".join(sorted(_applied)))
except ImportError:
    pass
except Exception as _exc:
    print("[настройки борта] НЕ ПРИМЕНЕНЫ: %s" % _exc)

# Разрешение камеры зависит от RECORD_HIRES, а он мог быть переопределён выше.
if RECORD_HIRES:
    CAM_W, CAM_H = LORES_W * 2, LORES_H * 2

# =========================================================
# 12. START
# =========================================================
def main():
    global picam2
    picam2 = Picamera2()

    sensor_mode = None
    preferred = [
        ((1640, 1232), 8),
        ((1640, 1232), 10),
        ((3280, 2464), 8),
        ((3280, 2464), 10),
        ((1920, 1080), 8),
        ((1920, 1080), 10),
        ((640, 480), 8),
        ((640, 480), 10),
    ]
    for target_size, target_bit in preferred:
        for m in picam2.sensor_modes:
            if tuple(m.get("size", ())) == target_size and int(m.get("bit_depth", 0)) == target_bit:
                sensor_mode = m
                break
        if sensor_mode is not None:
            break
    if sensor_mode is None:
        sensor_mode = picam2.sensor_modes[0] if picam2.sensor_modes else None

    kwargs = {
        "main": {"size": (MAIN_W, MAIN_H), "format": "XRGB8888"},
        "lores": {"size": (CAM_W, CAM_H), "format": "YUV420"},
        "buffer_count": 4,
        "queue": False,
        "transform": Transform(hflip=CAMERA_ROTATE_180, vflip=CAMERA_ROTATE_180),
    }
    if sensor_mode is not None:
        kwargs["sensor"] = {
            "output_size": sensor_mode["size"],
            "bit_depth": sensor_mode["bit_depth"],
        }

    config = picam2.create_preview_configuration(**kwargs)
    picam2.configure(config)
    picam2.pre_callback = camera_callback
    picam2.start_preview(Preview.DRM, x=PREVIEW_X, y=PREVIEW_Y,
                         width=PREVIEW_W, height=PREVIEW_H)
    picam2.start()

    try:
        picam2.set_controls({"FrameDurationLimits": (16666, 33333)})
    except Exception:
        pass

    # ЖДЁМ, ПОКА АВТОМАТИКА СОЙДЁТСЯ, а не фиксированные полсекунды.
    #
    # Раньше стояло time.sleep(0.5), и этого не хватало: камера стартует с
    # максимальной выдержки и опускается постепенно. В журнале борта прямо
    # видно, что замораживалось:
    #
    #     выдержка 32939 мкс, усиление 4.00   <- это ПОТОЛОК выдержки
    #     выдержка 32939 мкс, усиление 4.00
    #     выдержка 23128 мкс, усиление 2.00   <- а этот успел сойтись дальше
    #
    # То есть в светлой комнате замораживалась экспозиция для тёмной, и
    # картинка выходила пересвеченной. Скорее всего это же объясняет и
    # прежнюю загадку с обесцвеченными кадрами: неверная экспозиция и
    # неверный баланс белого замораживались вместе.
    #
    # Теперь ждём, пока выдержка и усиление перестанут меняться — но не
    # дольше предела, чтобы не задерживать запуск бесконечно.
    md = {}
    prev = None
    stable = 0
    t_wait0 = time.monotonic()
    while time.monotonic() - t_wait0 < CAM_SETTLE_MAX_S:
        time.sleep(CAM_SETTLE_STEP_S)
        try:
            md = picam2.capture_metadata()
        except Exception:
            break
        cur = (int(md.get("ExposureTime", 0)), float(md.get("AnalogueGain", 0.0)))
        if prev is not None and abs(cur[0] - prev[0]) <= max(50, prev[0] * 0.02) \
                and abs(cur[1] - prev[1]) <= 0.05:
            stable += 1
            if stable >= CAM_SETTLE_STABLE:
                break
        else:
            stable = 0
        prev = cur
    _settle_s = time.monotonic() - t_wait0
    try:
        md = picam2.capture_metadata()
        exp = int(md.get("ExposureTime", 8000))
        exp = min(exp, 33000)
        ctrl = {
            "AeEnable": False,
            "AwbEnable": False,
            "ExposureTime": exp,
            "AnalogueGain": float(md.get("AnalogueGain", 1.0)),
        }
        colour = md.get("ColourGains", None)
        if colour is not None:
            ctrl["ColourGains"] = tuple(colour)
        picam2.set_controls(ctrl)
        # ЧТО ИМЕННО ЗАМОРОЖЕНО — в журнал. Баланс белого фиксируется через
        # полсекунды после запуска, тем, к чему камера успела прийти. Если она
        # не успела или свет другой, цвета уезжают, а цветовой отсев остаётся
        # без работы: в вечерних прогонах цель приходила почти серой
        # (U=125 V=126 при нейтрали 128), тогда как утром тот же предмет давал
        # U=85 V=203. Без этой записи причину не отличить от «предмет просто
        # не цветной».
        flight_log.event(
            "КАМЕРА зафиксирована за %.1f с: выдержка %d мкс%s, усиление %.2f, "
            "баланс белого %s"
            % (_settle_s, exp,
               " (ПОТОЛОК — автоматика не сошлась)" if exp >= 32900 else "",
               float(md.get("AnalogueGain", 1.0)),
               ("%.2f/%.2f" % tuple(colour)) if colour else "не задан"))
    except Exception:
        pass

    # Автозапуск (systemd / rc.local / автологин) останавливает программу
    # СИГНАЛОМ, а не Ctrl+C. По умолчанию Python на SIGTERM умирает мгновенно,
    # минуя finally, — тогда лог не дописывается и итоговый разбор не
    # создаётся. Превращаем сигнал в обычный выход, чтобы finally отработал.
    def _on_terminate(signum, _frame):
        raise SystemExit(128 + signum)

    for _sig in ("SIGTERM", "SIGHUP"):
        try:
            signal.signal(getattr(signal, _sig), _on_terminate)
        except Exception:
            # Не на всех платформах есть оба сигнала — не повод падать.
            pass

    flight_log.start()

    io_thread = threading.Thread(target=fc_io_loop, daemon=True)
    io_thread.start()

    try:
        while True:
            time.sleep(0.5)
    except (KeyboardInterrupt, SystemExit):
        # SystemExit сюда приходит из обработчика сигнала выше. Гасим его,
        # чтобы выйти штатно с кодом 0: для systemd это нормальная остановка.
        pass
    finally:
        # Первым делом дописываем лог: если ниже что-то зависнет на закрытии
        # железа, разбор полёта всё равно останется на диске.
        try:
            flight_log.stop()
        except Exception:
            pass
        io_thread_stop.set()
        try:
            if io_thread.is_alive():
                io_thread.join(timeout=1.0)
        except Exception:
            pass
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            if fc is not None:
                fc.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()
